const DATA = [
  // ---------- PRIMORDIAL ----------
  { id:'chaos', gen:'primordial', zh:'卡俄斯', gr:'Chaos', roman:'—', epithet:'萬有之始',
    domain:'虛空 · 混沌', symbol:'無形的深淵', parents:[],
    astro:'沒有正式對應的天體命名，但天文學界常借用「卡俄斯地形」（Chaos terrain）一詞，形容如木衛二歐羅巴表面那樣破碎、混亂的冰層地貌。',
    story:'卡俄斯是希臘神話中最初的存在，代表宇宙誕生之前的無形虛空。祂並非「混亂」，而是萬物得以從中分化出來的原始空間。從卡俄斯之中，誕生了蓋亞（大地）、塔爾塔羅斯（深淵）、厄瑞玻斯（幽暗）與倪克斯（黑夜）。',
    fullStory:[
      '在一切之前，沒有天，沒有地，沒有海，也沒有任何一顆星辰。詩人赫西俄德說，最先出現的，是卡俄斯——一片沒有形狀、沒有方向、沒有光的浩大虛空。這不是「一團混亂的東西」，而更像是一個尚未被畫出邊界的空間，萬物日後將從這裡被劃分出來。',
      '沒有人見過卡俄斯的樣貌，因為在祂之中，「樣貌」這個概念本身都還不存在。然而正是從這片虛空之中，第一批存在開始浮現：寬廣的蓋亞（大地）鋪展開來，作為萬物日後立足的根基；幽深的塔爾塔羅斯沉落在大地之下，成為比冥界更深的深淵；黑暗的厄瑞玻斯與夜之女神倪克斯也相繼誕生，為世界帶來了明暗交替的雛形。',
      '卡俄斯自己並未參與後來的神界紛爭——祂不與泰坦作戰，也不曾在奧林帕斯山上議事。祂更像是一個永遠留在故事背景中的存在：所有的神祇、所有的英雄、所有的愛恨情仇，最終都可以追溯回這一片最初的虛空。希臘人相信，萬物有始，而卡俄斯，就是那個「始」本身。'
    ]},
  { id:'gaia', gen:'primordial', zh:'蓋亞', gr:'Gaia', roman:'泰拉 Terra', epithet:'大地之母',
    domain:'大地', symbol:'豐饒的土地', parents:['chaos'],
    astro:'歐洲太空總署（ESA）的蓋亞太空望遠鏡（Gaia）正以此為名，精密測繪銀河系中十億顆恆星的位置與運動軌跡。',
    story:'蓋亞是大地本身的化身，萬物之母。她獨自誕生了天空之神烏拉諾斯，再與祂結合，生下十二位泰坦神，以及獨眼巨人與百臂巨人。後來也是她鼓勵幼子克洛諾斯推翻暴虐的烏拉諾斯。',
    fullStory:[
      '蓋亞從卡俄斯的虛空中浮現，成為第一片堅實的土地——她自己，就是大地。萬物需要一個立足之處，而蓋亞，便是那個立足之處本身。她獨力誕下了覆蓋自己的天空烏拉諾斯，讓天與地從此相對而立；又生下了群山與波光粼粼的蓬托斯（海洋），世界的骨架，就此逐漸成形。',
      '之後，蓋亞與親生子烏拉諾斯結合，生下了十二位泰坦神、三位獨眼巨人賽克洛普斯，以及三位擁有百隻手臂的百臂巨人。然而烏拉諾斯厭惡自己這些強大而異形的孩子，將他們一個個推回蓋亞的體內，不許他們見到天光。這使蓋亞承受著難以言喻的痛楚與憤怒。',
      '於是，蓋亞打造了一把鋒利的灰色鐮刀，召集她的孩子們，問誰願意替母親復仇。只有最年幼的泰坦克洛諾斯挺身而出。蓋亞將鐮刀交到他手中，並在暗處為他策劃了伏擊。當夜幕降臨、烏拉諾斯如常靠近蓋亞時，克洛諾斯揮刀閹割了自己的父親，終結了他的暴政。蓋亞終於能讓被囚禁的孩子們重見天日——但這場流血的復仇，也埋下了日後諸神世代相殘的種子。'
    ]},
  { id:'uranus', gen:'primordial', zh:'烏拉諾斯', gr:'Uranus', roman:'凱路斯 Caelus', epithet:'蒼穹之神',
    domain:'天空', symbol:'星辰滿佈的天幕', parents:['gaia'],
    astro:'天王星 Uranus，是太陽系八大行星中唯一保留希臘語名稱、而非羅馬名稱的行星。',
    story:'烏拉諾斯是蓋亞之子，也是她的配偶，象徵覆蓋大地的天空。他懼怕自己孩子的力量，將他們囚禁於蓋亞體內，最終被幼子克洛諾斯以鐮刀閹割推翻，其血肉落入大海，孕育出阿芙蘿黛蒂。',
    fullStory:[
      '烏拉諾斯由蓋亞獨力誕生，成為覆蓋大地的星空穹頂。他與生育自己的蓋亞結合，成為第一代真正意義上的「天地夫妻」，也因此誕下了泰坦神族、獨眼巨人與百臂巨人——一整個世代的強大存在。',
      '然而烏拉諾斯無法忍受這些孩子的力量與異形的外貌，尤其懼怕獨眼巨人與百臂巨人。他將他們一一推回母親蓋亞的體內，不許他們降生於世，也因此讓蓋亞承受無盡的痛苦。這份積壓的怨恨，最終匯聚成一場精心策劃的伏擊。',
      '在蓋亞的授意下，最年幼的泰坦克洛諾斯手持鐮刀，於黑夜中埋伏。當烏拉諾斯一如往常降臨、擁抱大地之時，克洛諾斯揮刀閹割了自己的父親。烏拉諾斯的血滴落在大地上，孕育出復仇女神厄里倪厄斯與巨人族；而他的殘軀被拋入大海，海面泛起白色的泡沫，從中誕生了美麗的愛神阿芙蘿黛蒂。烏拉諾斯自此退出了神界的權力核心，天地由此分離，也開啟了泰坦神族統治世界的時代。'
    ]},
  { id:'tartarus', gen:'primordial', zh:'塔爾塔羅斯', gr:'Tartarus', roman:'同名', epithet:'深淵之神',
    domain:'冥界最深處', symbol:'銅牆鐵壁的地牢', parents:['chaos'],
    astro:'沒有正式對應的天體命名，但常被借用來形容太陽系中最深、最幽暗的區域，例如遙遠的柯伊伯帶邊緣地帶。',
    story:'塔爾塔羅斯既是一位原初神，也是大地之下最深、最黑暗的深淵本身，比冥界還要幽深。戰敗的泰坦神族最終被囚禁於此，由百臂巨人看守。',
    fullStory:[
      '塔爾塔羅斯誕生於卡俄斯的虛空之中，與蓋亞幾乎同時出現，卻位於世界的另一端——大地之下最深、最幽暗的角落。希臘人相信，若一顆銅砧從天界墜落，要花上整整九天九夜才會抵達大地；而若再從大地繼續墜落，又要再花上九天九夜，才會抵達塔爾塔羅斯。它比冥界還要深邃，是宇宙結構中最遙遠、最禁閉的所在。',
      '塔爾塔羅斯既是一個地方，也被視為一位神祇——祂與大地女神蓋亞結合，生下了可怕的巨怪堤豐，那頭幾乎推翻宙斯統治的百頭巨龍。',
      '在泰坦之戰中，宙斯與奧林帕斯眾神最終擊敗了克洛諾斯率領的泰坦神族。戰敗的泰坦們被鎖鏈捆綁，投入塔爾塔羅斯的銅牆鐵壁之中，由百臂巨人日夜看守，永世不得脫身。從此，塔爾塔羅斯也成為日後懲罰惡人與褻瀆神明者的終極監牢，是希臘神話中「永罰」概念的原型。'
    ]},
  { id:'nyx', gen:'primordial', zh:'倪克斯', gr:'Nyx', roman:'諾克斯 Nox', epithet:'黑夜女神',
    domain:'夜晚', symbol:'星空與烏鴉', parents:['chaos'],
    astro:'冥王星的其中一顆衛星「倪克斯」（Nyx）即以她為名，2005年被發現，靜靜地繞行著冥界之王所在的世界。',
    story:'倪克斯是黑夜的化身，力量強大到連宙斯也對她心存敬畏。她獨力或與厄瑞玻斯生下了睡神修普諾斯、死神塔納托斯與命運三女神等一系列抽象概念之神。',
    fullStory:[
      '倪克斯從卡俄斯中誕生，是黑夜本身的化身。荷馬在史詩中描述，就連天神之王宙斯也對她心懷敬畏——傳說宙斯曾因盛怒欲懲罰睡神修普諾斯，修普諾斯逃入母親倪克斯的懷抱躲藏，宙斯竟因忌憚觸怒黑夜女神，而選擇按捺怒氣，不再追究。',
      '倪克斯居住在世界西方邊界的一座幽暗宮殿之中，每個黃昏，她會駕著由黑馬拉著的戰車升起，將黑夜的帷幕拉過大地；而當她返回時，她的女兒——白晝女神赫墨拉——便會從同一扇門走出，為世界帶來光明。母女二人終生輪替，卻幾乎永不相見，只在門口交會一瞬。',
      '倪克斯的子嗣多得驚人，且幾乎全是抽象概念的化身：死神塔納托斯、睡神修普諾斯、掌管命運絲線的命運三女神摩伊賴、復仇女神涅墨西斯、欺騙之神阿帕忒，甚至還有「爭執」與「痛苦」的化身。透過倪克斯，希臘人將人生中最幽微、最難以名狀的經驗——死亡、睡眠、命運、報應——全都賦予了神聖的形貌，也讓黑夜本身，成為理解世界陰暗面的一把鑰匙。'
    ]},

  // ---------- TITANS ----------
  { id:'cronus', gen:'titan', zh:'克洛諾斯', gr:'Cronus', roman:'薩圖恩 Saturn', epithet:'時間與收穫之神',
    domain:'時間、農業', symbol:'鐮刀', parents:['gaia','uranus'],
    astro:'土星 Saturn 的羅馬名稱正對應克洛諾斯，這顆環繞著壯麗光環的行星，也常被想像為時間流轉、緩慢莊重的象徵。',
    story:'克洛諾斯是泰坦神族之首，聽從母親蓋亞的計謀推翻父親烏拉諾斯，成為新一代天地之主。因害怕預言中「將被自己孩子推翻」的命運，他吞下了自己的每一個孩子，直到瑞亞以石頭調包救下幼子宙斯。',
    fullStory:[
      '克洛諾斯是烏拉諾斯與蓋亞最年幼、卻也最果決的孩子。當母親蓋亞因丈夫的暴行而痛苦不堪、召集子女商議復仇時，唯獨克洛諾斯挺身接下了那把鋒利的鐮刀。他在黑夜中埋伏，親手閹割了自己的父親，終結了烏拉諾斯的統治，也讓泰坦神族登上了世界的權力頂端。',
      '克洛諾斯自立為王，與姊妹瑞亞成婚，統治著這個被稱為「黃金時代」的世界——傳說中那是一段沒有戰爭、沒有辛勞、萬物豐美自足的歲月。然而，一則來自蓋亞與被囚禁的烏拉諾斯的預言，始終如影隨形地纏繞著他：他終將被自己的一個孩子推翻，正如他推翻了自己的父親一樣。',
      '為了逃避這個命運，克洛諾斯做出了駭人的決定——每當瑞亞誕下一個孩子，他便將嬰兒整個吞入腹中。狄蜜特、赫拉、波賽頓等孩子相繼被他吞食。瑞亞悲痛欲絕，卻無力阻止，直到她懷上第六個孩子宙斯時，終於在母親蓋亞的協助下策劃了一場調包：她將宙斯秘密送往克里特島撫養，卻用一塊裹著襁褓的石頭謊稱是嬰兒，交給了克洛諾斯吞下。克洛諾斯毫無察覺，而躲過一劫的宙斯，日後正是那個親手終結他統治的孩子——預言，終究應驗。'
    ]},
  { id:'rhea', gen:'titan', zh:'瑞亞', gr:'Rhea', roman:'奧普斯 Ops', epithet:'眾神之母',
    domain:'生育、母性', symbol:'獅子與鑰匙', parents:['gaia','uranus'],
    astro:'土星第二大衛星「瑞亞」（Rhea）即以她命名，是太陽系中已知第九大的衛星。',
    story:'瑞亞是克洛諾斯之妻，奧林帕斯眾神的母親。為了保護幼子宙斯不被丈夫吞食，她將石頭包裹在襁褓中矇騙克洛諾斯，並將宙斯秘密藏於克里特島撫養長大。',
    fullStory:[
      '瑞亞是泰坦神族的一員，也是克洛諾斯的姊妹與妻子。她一次又一次懷胎、生產，卻只能眼睜睜看著丈夫將每一個新生的孩子吞入腹中——狄蜜特、赫斯提亞、赫拉、黑帝斯、波賽頓，一個接一個消失在克洛諾斯的口中，只因一則預言說，他終將被自己的孩子推翻。',
      '當瑞亞懷上第六胎時，她再也無法忍受這樣的悲劇重演。她向自己的父母蓋亞與烏拉諾斯求助，在他們的指引下，秘密前往克里特島的一處山洞，在那裡誕下了宙斯。她將初生的嬰兒交給山林中的仙女與庫瑞特斯武士照顧——傳說庫瑞特斯會敲擊盾牌、發出巨響，掩蓋嬰兒的哭聲，以免被克洛諾斯發現。',
      '瑞亞接著用布料裹起一塊沉重的石頭，佯裝成剛出生的嬰兒，交給了克洛諾斯。毫無戒心的克洛諾斯一如既往地將「孩子」整個吞下，絲毫沒有察覺自己已經失算。多年後，長大成人的宙斯回到父親身邊，用計讓克洛諾斯吐出了先前吞下的所有兄姊，並率領他們對抗泰坦神族，最終奪取了統治世界的權柄。瑞亞也因此被尊為「眾神之母」，是奧林帕斯整個世代得以誕生的關鍵。'
    ]},
  { id:'oceanus', gen:'titan', zh:'俄刻阿諾斯', gr:'Oceanus', roman:'奧刻阿努斯 Oceanus', epithet:'環繞大地之河',
    domain:'環繞世界的大洋', symbol:'環形巨流河', parents:['gaia','uranus'],
    astro:'月球上一片廣闊的玄武岩平原「風暴洋」（Oceanus Procellarum）便以此為名，是月球上唯一被稱為「Oceanus」等級的月海。',
    story:'俄刻阿諾斯是環繞整個已知世界的巨大河流之神，被視為所有江河湖海的源頭。與提坦神忒堤斯結合，生下了無數河神與海洋女神。',
    fullStory:[
      '在古希臘人的世界觀裡，已知的大陸被想像為一塊漂浮於水面的圓盤，而環繞著這塊大陸邊緣、川流不息的巨大河流，就是俄刻阿諾斯——一位泰坦神，同時也是這條河流本身。他不像後來的海神波賽頓那樣性情狂暴，反而以溫和、公正、超然於神界紛爭之外著稱。',
      '俄刻阿諾斯與姊妹忒堤斯結合，生下了三千位被稱為「俄刻阿尼德斯」的海洋仙女，以及數量同樣龐大的河神，幾乎世界上每一條重要的河流，都被認為是他們的孩子。因此，俄刻阿諾斯常被視為地上所有淡水與海洋的共同源頭，是滋養萬物的水之根本。',
      '值得一提的是，在克洛諾斯與宙斯之間爆發的泰坦之戰中，俄刻阿諾斯是少數選擇保持中立、不參與戰鬥的泰坦神之一，甚至傳說他曾試圖勸阻其他泰坦不要輕啟戰端。也因為這份超然的態度，當宙斯獲勝、將戰敗的泰坦神族打入塔爾塔羅斯深淵時，俄刻阿諾斯與他的家族並未遭到懲罰，得以繼續安然流淌，環繞著整個世界。'
    ]},
  { id:'hyperion', gen:'titan', zh:'許珀里翁', gr:'Hyperion', roman:'同名', epithet:'高處觀望者',
    domain:'光、天界的觀察', symbol:'旭日之光', parents:['gaia','uranus'],
    astro:'土星的一顆衛星「許珀里翁」（Hyperion）形狀極不規則，如同一塊被啃咬過的海綿，是太陽系中最大的非球形天體之一。',
    story:'許珀里翁是光明泰坦，與姊妹忒亞結合，生下了太陽神赫利歐斯、月亮女神賽勒涅與曙光女神厄俄斯，一家掌管了天空中最主要的光源。',
    fullStory:[
      '許珀里翁是烏拉諾斯與蓋亞的孩子之一，他的名字被後世解讀為「高處觀望者」或「行走於高空之人」，象徵著他與天界光明之間的緊密聯繫。他雖不像宙斯或克洛諾斯那樣直接參與權力鬥爭的核心敘事，卻在希臘人理解「光」如何降臨世界的宇宙觀中，佔有關鍵位置。',
      '許珀里翁與同為泰坦神的姊妹忒亞結合，生下了三位掌管天空光源的神祇：終日駕著金色馬車橫越天際的太陽神赫利歐斯、以銀色光輝照亮夜空的月亮女神賽勒涅，以及每日清晨最先為世界揭開序幕的曙光女神厄俄斯。這一家三口，幾乎包辦了古希臘人日常生活中所能見到的一切天光。',
      '在後世的文學想像中，許珀里翁本人有時甚至直接與「太陽」的形象重疊——因為他的孩子赫利歐斯太過耀眼，以至於父親的形象逐漸被兒子的光芒所取代。儘管如此，許珀里翁作為「光之泰坦」的原初身分，仍舊透露著希臘神話一個重要的邏輯：在奧林帕斯眾神登場之前，世界早已由這些更古老、更貼近自然現象本身的神祇所照亮。'
    ]},
  { id:'iapetus', gen:'titan', zh:'伊阿珀托斯', gr:'Iapetus', roman:'同名', epithet:'凡人族系之父',
    domain:'凡人的命運、工藝', symbol:'燃燒的火炬', parents:['gaia','uranus'],
    astro:'土星衛星「伊阿珀托斯」（Iapetus）以其奇特的「陰陽臉」聞名——一半表面亮如白雪，另一半卻暗如煤炭。',
    story:'伊阿珀托斯常被視為人類的祖先泰坦。他的兒子普羅米修斯盜取天火贈予人類，另一子阿特拉斯則因參與泰坦戰爭戰敗，被罰扛起蒼天。',
    fullStory:[
      '伊阿珀托斯是烏拉諾斯與蓋亞的兒子，在泰坦神族中，他的角色更多是透過他那幾位聲名遠播的兒子而被記住——赫西俄德將他稱為「凡人族系之父」，因為他的後代與人類的命運有著格外深刻的糾葛。',
      '伊阿珀托斯共有四個著名的兒子：力大無窮卻莽撞的墨諾提俄斯，最終被宙斯以雷霆擊殺；聰明卻思慮不周的厄庇墨透斯；以及兩位性格與命運形成強烈對比的兄弟——普羅米修斯與阿特拉斯。普羅米修斯以智慧著稱，他不僅參與了人類的創造，更在宙斯下令收回火種、讓人類陷入黑暗與寒冷之後，冒險從奧林帕斯盜取天火，重新贈予人類，也因此觸怒宙斯，被鎖在高加索山上，日日遭鷹啄食肝臟。',
      '而阿特拉斯，則在克洛諾斯與宙斯之間的泰坦之戰中，成為泰坦一方最重要的將領。當泰坦最終戰敗，其他泰坦被打入塔爾塔羅斯深淵時，宙斯給予阿特拉斯一項格外沉重的懲罰：他必須永遠站在世界的西方邊界，用雙肩扛起整片天空，不得歇息。透過這對兄弟，伊阿珀托斯的家系，成為了希臘神話中「人類的處境」——既受神明眷顧與贈予，也承受著神明降下的懲罰——最鮮明的象徵。'
    ]},
  { id:'prometheus', gen:'titan', zh:'普羅米修斯', gr:'Prometheus', roman:'同名 Prometheus', epithet:'盜火贈予人類的泰坦',
    domain:'先見之明、人類的守護者、反抗天神的懲罰', symbol:'火炬與被鎖鏈捆綁的巨石', parents:['iapetus'],
    astro:'土星有兩顆相鄰的「牧羊犬衛星」，共同牧守著細窄的F環，其中一顆便叫「普羅米修斯」，另一顆正是他神話裡的「作品」——潘朵拉。兩顆衛星的軌道緊密相依，彷彿真的延續著這段神話裡的因果糾葛。',
    story:'普羅米修斯是伊阿珀托斯之子，希臘神話裡最重要的泰坦之一，因不忍人類在黑暗與寒冷中掙扎求生，違抗宙斯的禁令，從奧林帕斯山盜取天火贈予人類，因此觸怒宙斯，被鎖在高加索山的懸崖上，每日遭一隻巨鷹啄食肝臟，肝臟卻在夜裡重新生長，如此永無止盡地承受痛苦。',
    fullStory:[
      '普羅米修斯的名字，在希臘文裡意為「先見之明」，與意為「後見之明」的弟弟厄庇墨透斯恰成對比——傳說他曾參與創造人類，用泥土依照諸神的形象捏塑出第一批凡人，也因此對人類這個「作品」，懷抱著遠比其他神祇更深的憐憫與責任感。他親眼見到人類在蒙昧與寒冷中艱難求生，甚至不具備任何抵禦野獸、抵禦嚴寒的能力，決心要為他們做點什麼。',
      '宙斯登基之初，曾嚴令禁止將火種賜予人類——火是神明的特權，象徵著文明、技藝與超越野獸的能力，宙斯不願凡人擁有這樣的力量。普羅米修斯卻不顧禁令，將一截火種悄悄藏入茴香莖稈之中，帶下奧林帕斯山，交到了人類手中。火種的降臨，讓人類得以取暖、烹煮食物、鍛造工具，文明自此開始萌芽——但這份禮物，也讓普羅米修斯付出了慘痛的代價。',
      '宙斯震怒之下，命人將普羅米修斯鎖在高加索山的懸崖峭壁上，每日派遣一隻巨鷹啄食他的肝臟；由於他身為不朽的泰坦，肝臟會在夜裡重新生長，隔日又被啄食殆盡，如此永無止盡地循環受苦。這場刑罰持續了數個世紀，直到英雄海克力斯途經此地，射殺巨鷹，並徵得宙斯同意，才將普羅米修斯釋放——而促成這場赦免的，還有半人馬凱隆自願放棄自己不死之身、代替普羅米修斯承受痛苦的犧牲。普羅米修斯自此成為西方文化裡「反抗威權、為人類福祉挺身而出」最經典的象徵，「普羅米修斯式的」（Promethean）一詞，至今仍用來形容那些為追求進步而甘冒天譴風險的行動。'
    ]},
  { id:'atlas', gen:'titan', zh:'阿特拉斯', gr:'Atlas', roman:'同名 Atlas', epithet:'永遠扛著蒼天的泰坦',
    domain:'天空的支撐、忍耐、天文學', symbol:'扛在肩上的天球', parents:['iapetus'],
    astro:'木星有一顆衛星以他命名；「地圖集」（atlas）一詞的由來，也直接源自他——文藝復興時期的地圖繪製者，習慣在地圖集封面畫上阿特拉斯扛著地球的圖像，這個視覺傳統，讓他的名字從此成為「地圖冊」的代名詞。',
    story:'阿特拉斯是伊阿珀托斯之子，在泰坦之戰中擔任泰坦一方的主帥，戰敗後，宙斯罰他永遠站在世界的西方邊界，用雙肩扛起整片天空，不得歇息——這個懲罰後來意外催生了「地圖集」（atlas）這個詞彙。',
    fullStory:[
      '阿特拉斯在克洛諾斯與宙斯之間爆發的泰坦之戰中，是泰坦陣營裡最重要的將領，率領其他泰坦與奧林帕斯新生代神祇對抗了整整十年。當泰坦最終戰敗，其他參戰的泰坦大多被打入塔爾塔羅斯深淵囚禁，宙斯卻給予阿特拉斯一項格外特殊、也格外沉重的懲罰：他必須永遠站在世界最西端，用雙肩扛住整片天空，一刻不得放下，防止天地重新塌陷、合而為一。',
      '在海克力斯完成十二項苦役的其中一項任務裡，他需要摘取赫斯珀里得斯花園裡的金蘋果，由於阿特拉斯的女兒正是看守金蘋果的仙女，海克力斯提議代替阿特拉斯暫時扛起天空，換取阿特拉斯親自去摘取金蘋果——阿特拉斯扛慣了天空，一時卸下重擔後竟想一走了之，海克力斯只得假裝同意接手，卻藉口要調整肩上的墊子，請阿特拉斯先幫忙扶著天空片刻，趁機抽身逃走，再度將重擔留給了阿特拉斯。十六世紀的地圖繪製者，習慣在自己彙編的地圖冊封面，畫上阿特拉斯扛著地球的圖像，象徵著承載全世界地理知識的重量，這個視覺傳統流傳至今，讓「阿特拉斯」一詞，直接成為「地圖集」的代名詞。'
    ]},
  { id:'epimetheus', gen:'titan', zh:'厄庇墨透斯', gr:'Epimetheus', roman:'同名 Epimetheus', epithet:'「後見之明」的泰坦',
    domain:'後知後覺、衝動的決定', symbol:'空的陶罐', parents:['iapetus'], links:['prometheus','pandora'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'厄庇墨透斯是普羅米修斯之弟，名字意為「後見之明」，恰與兄長「先見之明」的稱號相對——儘管普羅米修斯再三警告，絕不可接受宙斯贈予的任何禮物，厄庇墨透斯仍舊沒能抵擋潘朵拉的美貌，娶她為妻，也因此間接為人類招來了災禍。',
    fullStory:[
      '厄庇墨透斯的名字，在希臘文裡意為「後見之明」——總是等事情發生之後，才恍然大悟自己原本該怎麼做，與哥哥普羅米修斯「先見之明」的稱號恰成鮮明對比。相傳厄庇墨透斯也曾參與為各種動物分配求生本能與能力的工作，卻因為粗心大意，把所有實用的天賦（利爪、堅甲、速度、力量）都分配給了其他動物，輪到人類時，才發現已經沒有任何天賦剩下——這個疏失，據說正是普羅米修斯決心盜火贈予人類、彌補這項缺憾的直接原因。',
      '宙斯將潘朵拉送給厄庇墨透斯為妻時，普羅米修斯再三告誡弟弟，絕不可接受宙斯贈予的任何禮物，以免其中暗藏陷阱。然而厄庇墨透斯終究沒能抵擋潘朵拉的美貌，不顧兄長警告，娶她為妻——這場婚姻最終導致潘朵拉打開了那只裝滿災禍的陶罐，讓疾病與憂愁自此進入人間。厄庇墨透斯「後知後覺」的性格，某種程度上也成為西方文化裡，用來提醒世人「三思而後行」時，最常被引用的一則反面教材。'
    ]},
  { id:'metis', gen:'titan', zh:'墨提斯', gr:'Metis', roman:'—', epithet:'被宙斯吞入腹中的智慧女神',
    domain:'智慧、謀略、深思熟慮', symbol:'被吞下的水滴', parents:[], links:['zeus','athena'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'墨提斯是宙斯的第一任妻子，以智慧著稱，曾獻計讓克洛諾斯吐出被吞下的子女，助宙斯奪得天下。宙斯得知她懷有身孕後，因神諭警告這個孩子將取代自己的地位，竟將懷孕的墨提斯直接吞入腹中——女兒雅典娜最終從他的頭顱裡全副武裝地誕生。',
    fullStory:[
      '墨提斯是大洋神俄刻阿諾斯之女，以無人能及的智慧聞名，是宙斯推翻父親克洛諾斯統治過程中，最重要的幕後功臣——正是她獻計調製了一種催吐藥劑，讓宙斯得以說服克洛諾斯服下，吐出先前吞食的所有子女，這些手足隨即與宙斯聯手發動泰坦之戰，奠定了奧林帕斯神系日後的統治格局。',
      '宙斯與墨提斯相戀後，得知一則神諭警告：墨提斯所生的第一個孩子將是女兒，智慧不亞於宙斯本人；若她再誕下第二胎，這個兒子將擁有推翻宙斯、奪取天下的力量——這則預言，與當年克洛諾斯吞食親生子女以防篡位的處境如出一轍。宙斯決心不重蹈父親覆轍，卻選擇了一種更加激進的手段：他趁墨提斯懷孕之際，將她整個人直接吞入自己腹中。數月之後，宙斯突然感到一陣劇烈頭痛，命匠神赫菲斯托斯以斧頭劈開自己的頭顱，全副武裝、智慧與戰略兼備的女神雅典娜，就這樣從宙斯的額頭一躍而出——墨提斯的智慧，某種程度上，也就此永遠寄居在宙斯自己的體內。'
    ]},
  { id:'themis', gen:'titan', zh:'忒彌斯', gr:'Themis', roman:'同名', epithet:'律法與正義女神',
    domain:'秩序、神諭、律法', symbol:'天秤與寶劍', parents:['gaia','uranus'],
    astro:'小行星帶中的「智神星族」（Themis family）便以她為名，其中的忒彌斯型小行星更是目前已知表面覆有水冰的小行星家族之一。',
    story:'忒彌斯代表神聖的律法與秩序，是宙斯的顧問與第二任妻子之一，掌管德爾菲神諭所，並生下了掌管季節與命運的女神們。',
    fullStory:[
      '忒彌斯是烏拉諾斯與蓋亞之女，她所代表的並非某一條具體的法律，而是「秩序」與「律法」這個概念本身——是神與人得以共同遵循、維繫世界不至於崩壞的那條無形界線。她常被描繪為手持天秤，象徵著公正的裁決。',
      '在克洛諾斯與宙斯世代交替的漫長歲月裡，忒彌斯始終被視為一位擁有預知能力的智者。傳說正是她提醒宙斯，若他與海洋仙女墨提斯所生的孩子成長，將會推翻宙斯的統治——這則警告，促使宙斯將懷孕的墨提斯整個吞下，最終導致雅典娜從他頭顱中誕生。忒彌斯也因此被視為德爾菲神諭所最早的主宰者之一，早在阿波羅接管之前，人們便會向她尋求神聖的指引。',
      '宙斯登基之後，忒彌斯成為他最重要的顧問與第二任妻子。兩人結合，生下了掌管季節更替與人間秩序的荷萊三女神，以及掌管每個人命運絲線的摩伊賴三女神（不同於倪克斯所生的那一支同名女神，這是後世傳統中另一種說法）。透過忒彌斯，希臘人將「正義終將降臨」與「季節必然循環」這兩種對世界秩序的信念，緊緊聯繫在了一起。'
    ]},

  // ---------- OLYMPIANS ----------
  { id:'zeus', gen:'olympian', zh:'宙斯', gr:'Zeus', roman:'朱庇特 Jupiter', epithet:'眾神與凡人之王',
    domain:'天空、雷電、秩序', symbol:'雷霆與老鷹', parents:['cronus','rhea'],
    astro:'木星 Jupiter 的羅馬名稱正對應宙斯，是太陽系中體積最大的行星；環繞其軌道的特洛伊小行星群，更以特洛伊戰爭中的英雄們命名。',
    story:'宙斯是奧林帕斯眾神之主，率領兄弟姊妹發動「泰坦之戰」推翻父親克洛諾斯，將世界分為天、海、冥三界，自己執掌天空與最高權柄。他以風流著稱，眾多凡人與神祇之子皆與他有關。',
    fullStory:[
      '宙斯是克洛諾斯與瑞亞最年幼的孩子，也是唯一躲過被父親吞食命運的一個——母親瑞亞用一塊裹著襁褓的石頭騙過了克洛諾斯，將真正的宙斯秘密送往克里特島的山洞撫養長大，由山羊仙女阿瑪爾忒亞的乳汁餵養，庫瑞特斯武士則以敲擊武器的巨響，掩蓋他的哭聲。',
      '成年後的宙斯回到父親身邊，在智慧女神墨提斯的幫助下，讓克洛諾斯服下了一種催吐的藥劑，吐出了先前吞下的所有兄姊——赫斯提亞、狄蜜特、赫拉、黑帝斯與波賽頓。這些手足隨即與宙斯聯手，向克洛諾斯與其餘泰坦神族宣戰，史稱「泰坦之戰」。這場戰爭持續了整整十年，宙斯最終釋放了被囚禁在塔爾塔羅斯的獨眼巨人與百臂巨人作為盟友，獨眼巨人為他打造了無堅不摧的雷霆，成為扭轉戰局的關鍵武器。',
      '戰勝之後，宙斯與兩位兄弟波賽頓、黑帝斯抽籤分配天下：宙斯得到了天空，成為眾神之王；波賽頓執掌海洋；黑帝斯則統治冥界。宙斯定都奧林帕斯山，以雷霆為武器、老鷹為使者，維繫著天地間的秩序。然而他的統治並非只靠威嚴——他一生風流韻事無數，與無數女神及凡人女子育有眾多子女，包括雅典娜、阿波羅、阿蒂蜜絲、荷米斯、戴歐尼修斯，以及海克力斯、柏修斯等著名英雄，這些子嗣的故事，構成了希臘神話中最龐大的一支敘事家族。',
      '若用現代流行語來形容，宙斯大概會被封為希臘神話裡的「海王」始祖——他為了追求心儀對象，變成天鵝、公牛、金雨、甚至別人的丈夫，手法之多樣，放到今天大概能寫成一整本「搭訕技巧大全」。他與無數女神、寧芙仙女、乃至凡人女子留下的後代，幾乎撐起了整個希臘神話的人物版圖；而赫拉綿延不絕的嫉妒與報復，某種程度上，也成了古希臘人理解「權力與慾望難以馴服」這件事，最生動的一則寓言。'
    ]},
  { id:'hera', gen:'olympian', zh:'赫拉', gr:'Hera', roman:'朱諾 Juno', epithet:'婚姻與家庭女神',
    domain:'婚姻、家庭、王后', symbol:'孔雀', parents:['cronus','rhea'],
    astro:'NASA 的朱諾號探測器（Juno，即赫拉的羅馬名）正環繞木星（宙斯）飛行，彷彿神話中赫拉窺探宙斯行蹤的化身。',
    story:'赫拉既是宙斯的姊姊，也是他的正妻，掌管婚姻與家庭的神聖秩序。她以善妒聞名，經常對宙斯的情人與私生子展開報復，海克力斯便是她最著名的targets之一。',
    fullStory:[
      '赫拉是克洛諾斯與瑞亞之女，曾與其他手足一同被父親吞入腹中，直到宙斯設計讓克洛諾斯將他們一一吐出，才重獲自由。她與宙斯既是姊弟，也在日後結為夫妻，成為奧林帕斯眾神之中地位最崇高的女神，掌管婚姻與家庭生活的神聖秩序，被尊為守護每一段婚約的天后。',
      '然而赫拉的婚姻生活，卻幾乎完全被丈夫的不忠所籠罩。宙斯與無數女神及凡人女子有染，赫拉的憤怒也因此成為許多神話故事的核心動力——她不僅懲罰那些與宙斯有染的女子，也將怒火延燒至他們所生的孩子身上。最著名的例子，便是宙斯與凡人王后阿爾克墨涅之子海克力斯：赫拉在他還是嬰兒時便派毒蛇潛入搖籃行刺，之後更在他成年後降下瘋狂，使他在神智不清之下誤殺了自己的妻兒，間接導致他必須完成著名的「十二項任務」來贖罪。',
      '儘管常被描繪為善妒而嚴厲的形象，赫拉同時也是家庭與婚姻誓約最堅定的守護者——正是因為她如此看重婚姻的神聖性，才無法容忍丈夫一次又一次地踐踏這份誓約。她的孔雀座駕與王后姿態，象徵著莊嚴與尊貴，也提醒著人們：在希臘人的想像裡，即便是眾神之后，也無法真正掌控自己婚姻中的一切。'
    ]},
  { id:'poseidon', gen:'olympian', zh:'波賽頓', gr:'Poseidon', roman:'涅普頓 Neptune', epithet:'撼地之神',
    domain:'海洋、地震、馬', symbol:'三叉戟', parents:['cronus','rhea'],
    astro:'海王星 Neptune 的羅馬名稱正對應波賽頓，這顆湛藍色的行星，以其洶湧的大氣風暴著稱，與海神的形象十分貼切。',
    story:'波賽頓掌管海洋與地震，性情如大海般時而平靜、時而狂暴。他與雅典娜爭奪雅典城的守護權而落敗，也是傳說中馬匹的創造者。',
    fullStory:[
      '波賽頓是克洛諾斯與瑞亞之子，宙斯的兄長，在泰坦之戰後與宙斯、黑帝斯三分天下時，抽得了海洋作為自己的領地。他手持三叉戟，能夠掀起滔天巨浪，也能引發地震撼動大地，因此同時被尊為「撼地之神」——在古希臘人的想像中，海洋的怒濤與大地的震動，本質上出自同一股力量。',
      '波賽頓性情如大海一般難以捉摸，時而平靜慷慨，時而狂暴易怒。傳說他曾與智慧女神雅典娜爭奪雅典城的守護權：波賽頓以三叉戟擊打衛城的岩石，湧出一道鹹水泉，象徵著航海與軍事力量；雅典娜則種下一株橄欖樹，象徵和平與豐饒。城中的居民最終選擇了雅典娜的贈禮，波賽頓因此心生怨懟，據說也是他日後屢屢與雅典人及與雅典娜親近的英雄——如奧德修斯——結下樑子的遠因。',
      '波賽頓也被視為馬匹的創造者：傳說他曾愛慕大地女神狄蜜特，狄蜜特為躲避他化身為母馬逃跑，波賽頓則化身為公馬追上了她，兩人的結合最終誕下了一匹神駿的駿馬。也因此，戰車競速與馬術在古希臘常與波賽頓的崇拜連結在一起，沿海城邦的水手們出海前，也總不忘向這位喜怒無常的海神獻上祭品，祈求一路平安。'
    ]},
  { id:'demeter', gen:'olympian', zh:'狄蜜特', gr:'Demeter', roman:'刻瑞斯 Ceres', epithet:'豐收女神',
    domain:'農業、穀物、季節', symbol:'麥穗', parents:['cronus','rhea'],
    astro:'穀神星 Ceres（狄蜜特的羅馬名）是小行星帶中最大的天體，也被歸類為矮行星，是距離地球最近的一顆矮行星。',
    story:'狄蜜特掌管大地的豐饒與農作物生長。當女兒波瑟芬妮被冥王黑帝斯擄走，她因悲痛而使大地枯竭，最終促成了「四季」的誕生——女兒每年須有一段時間留在冥界。',
    fullStory:[
      '狄蜜特是克洛諾斯與瑞亞之女，掌管穀物、農耕與大地的豐饒，古希臘人相信，每一次的播種與收穫，都仰賴著她的祝福。她與宙斯育有一女波瑟芬妮，母女感情極深，這份深情，也成為希臘神話中最動人、也最悲傷的故事之一的核心。',
      '某日，波瑟芬妮在原野上採花時，大地忽然裂開一道深淵，冥王黑帝斯乘著黑色馬車衝出，將她強行擄入冥界，立她為冥后。狄蜜特遍尋女兒不著，日夜悲慟，甚至化身為老婦人，遊蕩人間九天九夜，滴水未進。當她終於從太陽神赫利歐斯口中得知真相——是宙斯默許了黑帝斯的請求——她憤而離開奧林帕斯，拒絕再讓大地結出任何果實。',
      '狄蜜特的悲傷讓整個世界陷入飢荒，穀物枯萎，牲畜死絕，人類與眾神皆陷入了危機——因為沒有收成，人類便無法向神明獻祭。宙斯終於出面斡旋，命令黑帝斯放波瑟芬妮回到人間。然而，波瑟芬妮在冥界期間曾吃下幾顆石榴籽，依照冥界的規則，凡是嚐過冥界食物的人，便注定與那裡有所牽連。最終，眾神達成協議：波瑟芬妮每年須有三分之一（或一說二分之一）的時間留在冥界陪伴黑帝斯，其餘時間則返回人間與母親團聚。狄蜜特每逢女兒離去便悲傷不已，大地因此進入寒冬；而當女兒歸來，她便讓萬物重新甦醒——這便是希臘神話對「四季」由來最著名的解釋。'
    ]},
  { id:'athena', gen:'olympian', zh:'雅典娜', gr:'Athena', roman:'密涅瓦 Minerva', epithet:'智慧與戰略女神',
    domain:'智慧、戰略、工藝', symbol:'貓頭鷹與橄欖枝', parents:['zeus'],
    astro:'小行星 881 Athene 便以她為名；她的羅馬對應密涅瓦，也有小行星 93 Minerva 遨遊於星海之中。',
    story:'雅典娜是宙斯與智慧女神墨提斯之女，傳說她全副武裝、從宙斯的頭顱中誕生。她代表理性與策略性的戰爭，與雅典城締結特殊淵源，因贈予橄欖樹而成為該城的守護神。',
    fullStory:[
      '雅典娜的誕生方式，是希臘神話中最奇特的故事之一。她的母親是海洋女神墨提斯，以智慧著稱，宙斯曾與她結合。然而一則預言警告宙斯：墨提斯若生下第二胎，那個孩子將擁有推翻父親的力量——這正是宙斯自己曾對克洛諾斯做過的事。為了避免歷史重演，宙斯趁墨提斯懷有身孕之時，將她整個吞入自己的腹中。',
      '然而墨提斯並未因此消失，她在宙斯體內繼續孕育著腹中的孩子。數月後，宙斯忽然感到一陣劇烈的頭痛，痛不可當，於是請求匠神赫菲斯托斯以斧頭劈開自己的頭顱。伴隨著一聲巨響，雅典娜從宙斯的頭顱中一躍而出——她已是成年的模樣，全身披掛著閃亮的鎧甲與長矛，發出響亮的戰吼，震動了整片天地。',
      '雅典娜自此成為智慧、戰略與工藝的女神，她所代表的戰爭是經過深思熟慮的、講求策略的戰爭，這與衝動、嗜血的戰神阿瑞斯形成鮮明對比。她也與雅典城結下不解之緣：傳說她與波賽頓競爭這座城市的守護權，最終以一株橄欖樹——象徵和平、光明與豐饒——贏得了城中居民的心，雅典城也因此以她為名。雅典娜終生未婚，被視為永恆的處女神，卻始終是希臘神話中最受敬重、也最頻繁介入凡人事務、扶助英雄（如奧德修斯、柏修斯）的女神之一。'
    ]},
  { id:'apollo', gen:'olympian', zh:'阿波羅', gr:'Apollo', roman:'同名 Apollo', epithet:'光明與預言之神',
    domain:'太陽、音樂、預言、醫術', symbol:'七弦琴與弓', parents:['zeus'],
    astro:'NASA 的阿波羅計畫（Apollo program）以他為名，成功將人類送上月球；天文學上也有一整類「阿波羅型近地小行星」以他命名。',
    story:'阿波羅是宙斯與女神勒托之子，掌管音樂、詩歌、預言與醫療，德爾菲神諭所便由他所主。他外貌俊美、才華洋溢，是奧林帕斯眾神中形象最完美的代表之一。',
    fullStory:[
      '阿波羅是宙斯與泰坦女神勒托之子，與月神阿蒂蜜絲是孿生姊弟。他們的誕生本身就充滿波折：善妒的赫拉得知勒托懷有宙斯的孩子，便詛咒天下所有陸地都不得讓她棲身分娩。勒托四處漂泊，最終在一座漂浮於海上、原本不屬於任何陸地的小島提洛島找到棲身之處，才得以誕下這對孿生神子。',
      '阿波羅一出生便展現出驚人的力量，據說出生後僅僅四天，他便前往德爾菲，殺死了盤據當地、危害人間的巨蟒皮同——那是大地女神蓋亞所生的怪物。阿波羅擊敗巨蟒後，便在當地建立了他最著名的神諭所，此後數百年間，無數凡人與君王前來此地，透過女祭司皮媞亞傳達的神諭，尋求阿波羅對未來的指引。',
      '阿波羅同時也是音樂與詩歌的守護神，他手持七弦琴，是繆思女神們的領袖；他也精通醫術，是醫神阿斯克勒庇俄斯的父親。然而他的形象並非全然完美——他曾因愛慕河神之女達芙妮而窮追不捨，達芙妮最終在絕望中祈求父親將自己化為月桂樹以逃離他；他也曾因音樂比賽中的驕傲，將挑戰他的森林之神瑪爾緒阿斯活活剝皮。這些故事共同勾勒出阿波羅複雜的形象：他是光明與秩序的化身，卻也如同陽光本身，既能滋養萬物，也能灼傷靠得太近的人。'
    ]},
  { id:'artemis', gen:'olympian', zh:'阿蒂蜜絲', gr:'Artemis', roman:'黛安娜 Diana', epithet:'狩獵女神',
    domain:'狩獵、荒野、月亮', symbol:'銀弓與鹿', parents:['zeus'],
    astro:'NASA 現行的「阿蒂蜜絲計畫」（Artemis program）正以她為名，目標是讓人類重返月球——恰好呼應她身為月亮女神的身分。',
    story:'阿蒂蜜絲是阿波羅的孿生姊姊，守護荒野、獵人與野生動物，同時也是純潔與貞潔的象徵。她身邊常伴隨一群同樣立誓不嫁的女獵手仙女。',
    fullStory:[
      '阿蒂蜜絲是宙斯與勒托之女，在漂泊的母親歷經千辛萬苦終於抵達提洛島後，她比孿生弟弟阿波羅早一步降生，甚至傳說她一出生便立刻協助母親接生了自己的弟弟——這也是她日後被尊為守護分娩之女神的原因之一。',
      '傳說阿蒂蜜絲在年幼時，曾坐在父親宙斯的膝上，請求他賜予自己永恆的貞潔、一把銀弓與一群同樣立誓不嫁的仙女隨從，以及所有的山林與荒野作為她的領地。宙斯欣然允諾。自此，阿蒂蜜絲成為荒野、狩獵與野生動物的守護神，終年帶領著一群仙女穿梭於山林之間，追逐鹿群，也守護著森林中的一切生靈。',
      '阿蒂蜜絲對於自己與隨從所立下的貞潔誓言極為看重，任何冒犯這份純潔的人都會遭到嚴厲懲罰——傳說獵人阿克泰翁曾無意間窺見她沐浴的身影，阿蒂蜜絲盛怒之下將他變成一頭雄鹿，使他最終被自己豢養的獵犬撕碎。儘管形象嚴厲而疏離，阿蒂蜜絲同時也是守護年輕女孩與孕婦的仁慈女神，古希臘的少女在成年、步入婚姻之前，往往會前往她的神廟獻上祭品，告別自己無憂無慮的少女時代。'
    ]},
  { id:'leto', gen:'titan', zh:'勒托', gr:'Leto', roman:'拉托娜 Latona', epithet:'漂泊尋找棲身之地的泰坦女神',
    domain:'母性、庇護、隱忍', symbol:'提洛島與棕櫚樹', parents:[], links:['zeus','apollo','artemis'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'勒托是宙斯所愛的泰坦女神，因赫拉的嫉妒詛咒，懷孕期間被迫四處流浪、找不到任何一片陸地願意收留她分娩，最終在漂浮於海上、不屬於任何陸地的提洛島誕下阿波羅與阿蒂蜜絲這對孿生神子。',
    fullStory:[
      '勒托是泰坦神科俄斯與福柏之女，因與宙斯相戀懷有身孕，觸怒了善妒的天后赫拉。赫拉盛怒之下對天下所有堅實的陸地下達禁令，不許任何一寸土地讓勒托棲身分娩——這道詛咒讓身懷六甲的勒托，被迫在希臘各地城邦與島嶼間流離失所，處處遭到拒絕。',
      '幾經波折，勒托終於找到了提洛島——這座島嶼當時尚未固定於海床，而是一座隨波逐流、漂浮不定的島嶼，嚴格說來並不屬於「陸地」的範疇，因此意外地不受赫拉禁令的約束。勒托在此順利誕下了阿蒂蜜絲與阿波羅這對孿生神子，宙斯為感念提洛島的收留，此後將這座島嶼永久固定於海床之上，並使其成為日後阿波羅信仰最重要的聖地之一。勒托本人此後鮮少涉入其他神話糾葛，卻始終是希臘人心目中「忍辱負重的母親」最鮮明的形象。'
    ]},
  { id:'ares', gen:'olympian', zh:'阿瑞斯', gr:'Ares', roman:'瑪爾斯 Mars', epithet:'戰爭之神',
    domain:'戰爭、暴力、勇氣', symbol:'長矛與盾', parents:['zeus','hera'],
    astro:'火星 Mars 的羅馬名稱正對應阿瑞斯，這顆表面因氧化鐵而呈現血紅色澤的行星，自古便與戰爭之神緊密連結。',
    story:'阿瑞斯代表戰爭中血腥、狂暴的一面，與象徵戰略智慧的雅典娜形成鮮明對比。儘管是戰神，他在許多神話中卻常常吃敗仗，並不特別受其他神祇喜愛。',
    fullStory:[
      '阿瑞斯是宙斯與赫拉唯一共同的兒子，象徵著戰爭中最原始、最血腥的一面——衝鋒陷陣的狂熱、廝殺的快感，以及戰場上的混亂與破壞。這與同樣掌管戰爭、卻代表冷靜策略與正義之戰的雅典娜恰成對比：荷馬在《伊利亞德》中，甚至安排兩人在特洛伊戰場上直接對決，而阿瑞斯落敗於雅典娜之手。',
      '儘管貴為奧林帕斯十二主神之一，阿瑞斯在許多神話中的形象卻並不光彩——他常常魯莽行事、缺乏謀略，甚至一度被兩位巨人囚禁在青銅甕中長達十三個月，最終還是靠荷米斯出手相救才得以脫困。就連他的父親宙斯，也曾當面斥責他是奧林帕斯山上自己最厭惡的孩子，因為他總是熱衷於紛爭與殺戮本身。',
      '阿瑞斯最為人熟知的情感故事，是他與愛神阿芙蘿黛蒂的私通——儘管阿芙蘿黛蒂當時已是匠神赫菲斯托斯之妻。赫菲斯托斯察覺妻子的不忠後，打造了一張肉眼看不見的精巧金網，在兩人幽會之時將他們一同罩住，並召來眾神圍觀羞辱他們，成為神話中著名的一則帶有黑色幽默色彩的插曲。儘管形象不算討喜，阿瑞斯所代表的原始戰鬥本能，仍是希臘人理解戰爭殘酷本質不可或缺的一面。'
    ]},
  { id:'aphrodite', gen:'olympian', zh:'阿芙蘿黛蒂', gr:'Aphrodite', roman:'維納斯 Venus', epithet:'愛與美之女神',
    domain:'愛情、美麗、慾望', symbol:'貝殼與桃金孃', parents:['uranus'],
    astro:'金星 Venus 的羅馬名稱正對應阿芙蘿黛蒂；金星表面最大的高地「阿芙蘿黛蒂高地」（Aphrodite Terra）也以她命名。',
    story:'阿芙蘿黛蒂的誕生方式獨樹一格：據赫西俄德記載，她是烏拉諾斯被閹割後落入大海的血肉與泡沫所化生。她掌管愛與美，特洛伊戰爭的導火線便與她許諾給帕里斯的「世間最美女子」有關。',
    fullStory:[
      '按照詩人赫西俄德的記載，阿芙蘿黛蒂的誕生比任何一位奧林帕斯神祇都更為古老、也更為奇特。當克洛諾斯揮刀閹割父親烏拉諾斯之後，將其殘軀拋入大海，海面泛起大片白色泡沫，阿芙蘿黛蒂便從這片泡沫之中誕生，乘著一枚巨大的貝殼漂向岸邊，一登陸便已是成年女神的美麗模樣。她的名字，在希臘語中便與「泡沫」一詞有著密切的關聯。',
      '阿芙蘿黛蒂雖貴為愛與美的女神，婚姻卻並不美滿——宙斯將她許配給外貌醜陋、卻是眾神中手藝最精湛的匠神赫菲斯托斯，據說是為了平息其他神祇為爭奪她而起的紛爭。然而她的心思始終不在丈夫身上，與戰神阿瑞斯的私通關係人盡皆知，甚至一度被赫菲斯托斯設下的金網當場捉姦，成為眾神茶餘飯後的笑談。',
      '阿芙蘿黛蒂對特洛伊戰爭的爆發，負有直接的責任。傳說女神厄里斯因未受邀參加婚宴，憤而拋出一顆刻著「獻給最美者」的金蘋果，引發赫拉、雅典娜與阿芙蘿黛蒂三位女神的爭執。宙斯將裁決權交給特洛伊王子帕里斯，三位女神各自向他許下條件收買：赫拉許以權力，雅典娜許以智慧與戰無不勝，阿芙蘿黛蒂則許諾將世間最美的女子——斯巴達王后海倫——賜予他。帕里斯選擇了阿芙蘿黛蒂，最終誘走海倫，直接引爆了長達十年的特洛伊戰爭。透過這則故事，希臘人將「愛與慾望所能引發的毀滅性後果」，深深銘刻進了他們最偉大的戰爭史詩之中。'
    ]},
  { id:'hephaestus', gen:'olympian', zh:'赫菲斯托斯', gr:'Hephaestus', roman:'伏爾坎 Vulcan', epithet:'鍛造之神',
    domain:'火、鍛造、工匠', symbol:'鐵鎚與鐵砧', parents:['hera'],
    astro:'近地小行星 2212 Hephaistos 便以他為名，是一顆軌道特殊、曾被列為潛在危險小行星的天體。',
    story:'赫菲斯托斯是眾神中的能工巧匠，據說一出生便因跛足而被母親赫拉拋下奧林帕斯山。他為眾神打造了無數神兵利器，包括宙斯的雷霆與阿基里斯的鎧甲。',
    fullStory:[
      '關於赫菲斯托斯的誕生，流傳著一個格外令人心酸的版本：赫拉見宙斯獨力誕下雅典娜（未經過她參與生育），憤而決定也要不靠丈夫獨自生下一個孩子，以此證明自己同樣擁有這樣的力量。於是她獨自誕下了赫菲斯托斯——然而孩子一出生便顯得孱弱、跛足，赫拉見狀感到羞恥與厭惡，竟將他從奧林帕斯山頂直接拋下凡間。',
      '墜落的赫菲斯托斯被海洋女神忒堤斯與歐律諾墨救起，在海底的洞穴中撫養長大。正是在這段流放的歲月裡，他磨練出了驚人的鍛造技藝，打造出無數精巧絕倫的器物。他日後回到奧林帕斯，用計制伏了曾拋棄自己的母親——他打造了一張看似華美、實則暗藏機關的黃金座椅送給赫拉，赫拉一坐下便被無形的鎖鏈牢牢困住，直到赫菲斯托斯親自現身、獲得眾神調解後，才願意將母親釋放。',
      '儘管外貌與其他俊美的奧林帕斯神祇不同，赫菲斯托斯卻是眾神之中不可或缺的存在——他在西西里島埃特納火山下的鍛造坊裡，為宙斯打造了致命的雷霆，為雅典娜打造了神盾埃癸斯，更在特洛伊戰爭期間，應海洋女神忒堤斯之請，為她的兒子阿基里斯打造了一副刻滿精美浮雕、堅不可摧的鎧甲與盾牌。透過赫菲斯托斯，希臘神話傳遞出一個深刻的訊息：真正的力量，未必來自於天生的完美外貌，而往往源於後天磨練出的技藝與智慧。'
    ]},
  { id:'hermes', gen:'olympian', zh:'荷米斯', gr:'Hermes', roman:'墨丘利 Mercury', epithet:'眾神的信使',
    domain:'旅行、商業、盜賊、傳訊', symbol:'雙蛇杖與飛鞋', parents:['zeus'],
    astro:'水星 Mercury 的羅馬名稱正對應荷米斯，這顆太陽系中運行速度最快的行星，恰好呼應他身為神界飛毛腿信使的形象；近地小行星 69230 Hermes 也以他命名。',
    story:'荷米斯是宙斯與仙女邁亞之子，出生當天便展現過人機智，偷走了阿波羅的牛群。他身兼眾神信使，也是引導亡靈前往冥界的靈魂嚮導。',
    fullStory:[
      '荷米斯是宙斯與山林仙女邁亞之子，出生於一座偏僻山洞之中。與其他神祇緩慢成長不同，荷米斯展現出驚人的早熟與機智——傳說他出生當天中午便已能行走，傍晚時分，便已溜出搖籃，一路來到色薩利，偷走了自己異母兄長阿波羅所看管的一群神聖牛群。',
      '為了掩蓋自己的行蹤，年幼的荷米斯讓牛群倒退著行走，使足跡看起來像是牛群朝反方向走去；他還親手發明了一種前所未見的樂器——將烏龜殼繃上羊腸弦，做成了世界上第一把七弦琴。當阿波羅循線找上門來與他對質時，荷米斯厚著臉皮矢口否認，甚至煞有其事地指天發誓自己從未見過牛群。最終，宙斯出面調停，兩兄弟達成和解：荷米斯將牛群歸還，並將自己發明的七弦琴贈予阿波羅作為賠禮，阿波羅則將自己的一根牧羊杖回贈給他，這根杖日後演變為荷米斯著名的雙蛇纏繞權杖。',
      '荷米斯自此成為奧林帕斯眾神的信使，腳踏一雙裝有羽翼的飛鞋，是唯一能夠自由穿梭於天界、人間與冥界三個世界之間的神祇。也因此，他同時肩負著引導亡魂前往冥界的重任，被稱為「靈魂的嚮導」。他機智、敏捷，也帶著一絲狡黠，因此同時也是旅人、商人，乃至於盜賊的守護神——在希臘人眼中，這幾種身分之間的界線，本就不總是那麼分明。',
      '如果荷米斯活在今天，大概會是那種第一天出道就能把話題度衝上熱搜的角色——反應快、嘴皮子利、永遠知道怎麼在混亂的場面裡全身而退，甚至偷了牛群還能倒打一耙、面不改色地矢口否認。這種「機智到讓人又氣又愛」的特質，某種程度上，正是這位神界公關兼信使，兩千多年來始終討喜、從不真正惹人厭惡的原因。'
    ]},
  { id:'dionysus', gen:'olympian', zh:'戴歐尼修斯', gr:'Dionysus', roman:'巴克斯 Bacchus', epithet:'酒神',
    domain:'酒、狂歡、戲劇', symbol:'葡萄藤與酒杯', parents:['zeus','semele'],
    astro:'近地小行星 3671 Dionysus 便以他為名，在星海中靜靜運行。',
    story:'戴歐尼修斯是宙斯與凡人公主賽默勒之子，母親在懷孕時因目睹宙斯真身而喪命，宙斯將未足月的胎兒縫入自己大腿中孕育，因此他被稱為「二次誕生之神」。他掌管酒與狂歡，也是古希臘戲劇的守護神。',
    fullStory:[
      '戴歐尼修斯的母親賽默勒是底比斯的凡人公主，與宙斯相戀懷孕。善妒的赫拉得知此事後，化身為賽默勒的老乳母，慫恿她要求宙斯以真實的神聖形貌現身，作為愛意的證明。宙斯早已對賽默勒立下不可違背的誓言，只得無奈答應——然而凡人的肉身終究無法承受神祇真身所散發的雷霆與烈焰，賽默勒當場被燒成灰燼，香消玉殞。',
      '宙斯在最後一刻搶救出賽默勒腹中尚未足月的胎兒，將他縫入自己的大腿之中，繼續孕育，直到足月後才將他自腿中取出降生。因此，戴歐尼修斯被稱為「二次誕生之神」——一次出自母親賽默勒，一次出自父親宙斯本人。為了躲避赫拉持續的追殺，宙斯將年幼的戴歐尼修斯託付給遠方的仙女撫養，並讓他偽裝成女孩以掩人耳目，他就這樣在躲藏與流浪中逐漸長大。',
      '成年後的戴歐尼修斯發現了葡萄釀酒的技藝，並帶領著一支由薩堤爾、邁納德斯狂女組成的隨從隊伍，遊歷四方，將釀酒與狂歡的儀式傳播到世界各地。凡是接納他的城邦，便能享受葡萄酒帶來的歡愉；凡是拒絕承認他神性的統治者，往往會遭到瘋狂與毀滅性的懲罰，例如底比斯國王彭透斯便因不敬他而在狂亂儀式中慘死。戴歐尼修斯所代表的「狂喜」與「失序」，最終被古希臘人昇華為一種莊重的藝術形式——正是為了向他致敬而舉行的祭典，逐漸演變成古希臘戲劇的起源，他也因此被尊為劇場藝術永恆的守護神。'
    ]},

  { id:'eros', gen:'olympian', zh:'厄洛斯', gr:'Eros', roman:'邱比特 Cupid', epithet:'愛與慾望之神',
    domain:'愛情、慾望、吸引力', symbol:'弓箭與羽翼', parents:['aphrodite'], links:['psyche'],
    astro:'主帶小行星433 Eros是人類史上第一顆被太空船環繞探測的近地小行星（NASA的NEAR-Shoemaker任務，2000年）。',
    story:'厄洛斯是阿芙蘿黛蒂之子，手持弓箭，箭矢一旦射中，便會激起無法抗拒的愛慾——他奉母親之命懲罰普緒克，卻自己愛上了她，兩人歷經波折，最終修成正果，普緒克也因此獲得眾神賜予的不朽之身。',
    fullStory:[
      '厄洛斯是愛神阿芙蘿黛蒂之子，隨身攜帶兩種箭矢：金箭一旦射中，會激起無法抗拒的熾熱愛慾；鉛箭則會讓人對眼前對象心生厭惡、避之唯恐不及。他頑皮而任性，時常在人間與神界之間穿梭，隨意射出箭矢撮合或拆散一段段姻緣，是希臘神話裡最直接掌管「愛欲降臨」這件事本身的神祇。',
      '厄洛斯與普緒克的故事，是希臘神話裡少見「愛神親自墜入愛河」的敘事——阿芙蘿黛蒂嫉妒凡間公主普緒克的美貌，派兒子厄洛斯前去懲罰她，讓她愛上世間最卑劣的對象，不料厄洛斯自己反倒被普緒克的美貌打動，暗中將她迎娶為妻，卻約定她永遠不得看清丈夫的真實面貌。這段婚姻歷經背叛、失去信任、艱難試煉等重重波折，最終在宙斯出面調停下，普緒克獲賜不朽之身，兩人得以真正平等的身分永遠相守——羅馬人將厄洛斯的形象揉合進自己的邱比特（Cupid）之中，那個手持弓箭、時常出現在情人節卡片上的胖嘟嘟男孩，形象正是源自於此。'
    ]},

  { id:'hestia', gen:'olympian', zh:'赫斯提亞', gr:'Hestia', roman:'維斯塔 Vesta', epithet:'爐灶與家庭的女神',
    domain:'家庭、爐火、貞潔的秩序', symbol:'永不熄滅的爐火', parents:['cronus','rhea'],
    astro:'主帶小行星46 Hestia便以她為名；羅馬人將她等同於自己的爐灶女神維斯塔，羅馬城裡專門供奉維斯塔的神廟，由被稱為「維斯塔貞女」的祭司終身看護聖火，確保火焰永不熄滅。',
    story:'赫斯提亞是克洛諾斯與瑞亞的長女，第一個被父親吞下、卻是最後一個被吐出的孩子，性情溫和謙讓，是家庭爐灶與凝聚力的象徵。她曾同時受到波賽頓與阿波羅的追求，卻選擇向宙斯發誓永保貞潔，因此換得每個家庭爐灶都必須供奉她的殊榮。',
    fullStory:[
      '赫斯提亞是克洛諾斯與瑞亞所生的長女，依照出生順序，她原本該是第一個被父親克洛諾斯吞下肚的孩子，卻也因此成為日後被催吐藥劑逼出時，最後一個重見天日的手足——古希臘人因此常說她「既是長女、也是么女」。她性情溫和、與世無爭，在奧林帕斯眾神之間鮮少捲入紛爭。',
      '波賽頓與阿波羅都曾向赫斯提亞求婚，她卻向宙斯莊嚴發誓，永遠保持貞潔獨身，只願安靜看守著爐灶的火焰。宙斯感念她的謙讓與端莊，賜予她一項特殊的殊榮：每一戶人家、每一座城邦的公共爐灶，都必須供奉她，她因此成為家家戶戶最直接感受到神聖存在的一位女神。儘管她鮮少出現在具體的神話故事情節裡，她所守護的「爐火」，卻是古希臘人日常生活裡最核心、最不可或缺的存在——也因為她的角色過於安靜、缺乏戲劇性，後世常見的「奧林帕斯十二主神」名單裡，她的席位有時會被戴歐尼修斯取代，這也是為什麼這套家族圖譜選擇以戴歐尼修斯代表十二主神之一、而將赫斯提亞另外收錄的原因。'
    ]},

  { id:'hades', gen:'olympian', zh:'黑帝斯', gr:'Hades', roman:'普路托 Pluto', epithet:'冥界的統治者',
    domain:'冥界、亡者、地下財富', symbol:'雙叉戟與三頭犬刻耳柏洛斯', parents:['cronus','rhea'],
    astro:'矮行星冥王星的英文名「Pluto」，正是他的羅馬名；而冥王星最大的衛星「凱倫」，則以船夫卡戎命名——他負責划船，載著亡魂渡過冥河。',
    story:'黑帝斯是克洛諾斯與瑞亞之子，泰坦之戰後與宙斯、波賽頓三分天下，抽得冥界作為自己的領地。他鮮少離開自己的疆域，形象並不邪惡，更接近一位嚴格卻公正的統治者——真正被古希臘人畏懼的，其實是「死亡」本身，而非黑帝斯這位神祇。',
    fullStory:[
      '泰坦之戰結束後，宙斯、波賽頓與黑帝斯三兄弟抽籤決定各自的疆域，黑帝斯抽中了地底世界，從此執掌所有亡者的靈魂該去往何處。他很少離開自己統治的冥界，鮮少出現在奧林帕斯山的神界聚會之中，這種疏離也讓後世常誤以為他性情陰鬱、甚至邪惡——但在多數古希臘神話裡，黑帝斯其實是位嚴格卻公正的統治者，他嚴守冥界的規則，卻不隨意懲罰或傷害無辜的靈魂。',
      '黑帝斯最著名的故事，是強行擄走豐收女神狄蜜特之女波瑟芬妮，立她為冥后——這場擄劫最終促成了「四季」的誕生。儘管故事的開端充滿強迫色彩，後世不少版本的敘事裡，波瑟芬妮逐漸適應、甚至真正掌握了冥后的權柄，與黑帝斯共同統治著這片亡者的國度。',
      '有趣的是，古希臘人對「說出黑帝斯之名」本身，抱持著一種近乎迷信的忌諱，時常改以「普路托」（Plouton，意為「財富」）這個委婉稱呼代替他的本名，因為地底不僅埋葬著死者，也蘊藏著金屬礦藏與農作物生長所需的養分——這也是為什麼他同時也被視為地下財富的賜予者。這個委婉稱呼後來被羅馬人直接採用為他的羅馬名「普路托」（Pluto），二十世紀天文學家發現一顆運行在太陽系邊緣、幽暗遙遠的矮行星，便以此為名，向這位深居簡出的冥界之王致敬。'
    ]},

  { id:'persephone', gen:'olympian', zh:'波瑟芬妮', gr:'Persephone', roman:'普洛塞庇娜 Proserpina', epithet:'冥后與春之女神',
    domain:'冥界王后、春天的復甦', symbol:'石榴與麥穗', parents:['zeus','demeter'],
    astro:'主帶小行星399 Persephone便以她為名。',
    story:'波瑟芬妮是宙斯與狄蜜特之女，被冥王黑帝斯擄走成為冥后，因誤食冥界石榴籽而必須每年往返人間與冥界，她的離去與歸來，正是希臘神話裡「四季」由來最經典的解釋。',
    fullStory:[
      '波瑟芬妮是宙斯與狄蜜特之女，天真爛漫、常年伴隨母親往來於希臘的原野之間。某日她在原野上採花，忽然大地裂開一道深淵，冥王黑帝斯乘著黑色馬車衝出，將她強行擄入冥界，立她為冥后——這場劇變，讓她從一位無憂無慮的少女，一夕之間成為統治亡者國度的女王。',
      '母親狄蜜特遍尋女兒不著，最終在宙斯的斡旋下，黑帝斯同意放波瑟芬妮返回人間，條件卻暗藏玄機——依照冥界的規則，凡是嚐過冥界食物的人，便注定與那裡有所牽連，而波瑟芬妮在冥界期間，已經吃下了幾顆石榴籽。眾神因此達成協議：她每年須有部分時間返回冥界陪伴黑帝斯，其餘時間才能回到人間與母親團聚——狄蜜特每逢女兒離去便悲傷不已，大地隨之進入寒冬；女兒歸來，萬物才重新甦醒。',
      '儘管故事的起點是一場擄劫，後世許多版本裡，波瑟芬妮並非只是被動的受害者——她逐漸適應、甚至真正掌握了冥后的權柄，在冥界擁有不遜於黑帝斯的權威，時常介入決定死者的命運。她的形象也因此成為希臘神話裡少見的「雙重身分」象徵：既是為大地帶來春天甦醒的少女神，也是統治幽暗國度、令人敬畏的冥后。'
    ]},

  // ---------- HEROES ----------
  { id:'heracles', gen:'hero', zh:'海克力斯', gr:'Herakles', roman:'海克力士 Hercules', epithet:'最偉大的凡人英雄',
    domain:'力量、贖罪、堅忍', symbol:'獅皮與棍棒', parents:['zeus'],
    astro:'小行星 5143 Heracles 以他為名；他的羅馬名「海克力斯」也是天空中一個壯觀的星座，其中的M13球狀星團是北半球最壯麗的深空天體之一。',
    story:'海克力斯是宙斯與凡人王后阿爾克墨涅之子，因赫拉的嫉恨而一生飽受磨難。為贖清在瘋狂中誤殺親人之罪，他完成了著名的「十二項任務」，最終死後被眾神接納，升上奧林帕斯成為半神。',
    fullStory:[
      '海克力斯是宙斯與底比斯王后阿爾克墨涅之子，出生前便已成為赫拉憤怒的目標——她派了兩條毒蛇潛入嬰兒的搖籃，想要謀害他，然而年幼的海克力斯竟徒手掐死了兩條毒蛇，展現出驚人的天生神力。這份神力伴隨他一生，卻也因赫拉持續不斷的迫害，讓他的人生充滿了苦難。',
      '成年後的海克力斯娶妻生子，本應迎來平靜的生活，然而赫拉降下的瘋狂卻讓他在神智不清之下親手殺害了自己的妻兒。清醒過來後的海克力斯痛不欲生，前往德爾菲神諭所尋求贖罪之道，神諭指示他必須聽命於邁錫尼國王歐律斯透斯，完成他所指派的任務，才能洗清罪孽。國王一連指派了十二項近乎不可能的任務，這便是著名的「海克力斯十二項任務」。',
      '這十二項任務包括：徒手扼殺刀槍不入的涅墨亞獅子並剝下其皮作為戰袍；斬除擁有多顆頭顱、每砍一顆便會再生兩顆的九頭蛇許德拉；生擒凶猛的厄律曼托斯山野豬；在一天之內清理堆積三十年之久的奧革阿斯牛舍；捕捉會噴火傷人的克里特公牛；前往世界盡頭盜取赫斯珀里德斯姊妹看守的金蘋果；甚至下到冥界，將看守冥門的三頭犬刻耳柏洛斯活捉帶回人間。海克力斯憑藉超凡的力量與過人的機智，一一克服了這些看似不可能的挑戰。多年後，他因誤穿沾有毒血的衣袍而痛苦身亡，宙斯憐憫他一生的功績與苦難，將他的靈魂接引至奧林帕斯山，賜予他永生，並讓他與赫拉最終和解，迎娶青春女神赫柏為妻——這也是希臘神話中，少數凡人英雄最終得以位列眾神的傳奇故事。'
    ]},
  { id:'perseus', gen:'hero', zh:'柏修斯', gr:'Perseus', roman:'同名 Perseus', epithet:'蛇髮女妖的屠殺者',
    domain:'勇氣、機智', symbol:'蛇髮女妖梅杜莎的頭顱', parents:['zeus'], links:['medusa','athena','danae','andromeda'],
    astro:'英仙座（Perseus）是天空中一個著名的星座，每年八月固定造訪的「英仙座流星雨」（Perseid meteor shower），輻射點正位於此星座之中。',
    story:'柏修斯是宙斯化為金雨降臨、與被囚禁的公主達那厄所生之子。他憑藉諸神贈予的裝備，成功斬下蛇髮女妖梅杜莎的頭顱，並救下被獻祭的公主安卓美達，成為她的丈夫。',
    fullStory:[
      '柏修斯的故事，始於一則令人不安的預言：阿爾戈斯國王阿克里西俄斯得知神諭警告，自己終將死於外孫之手，於是將女兒達那厄囚禁在一座青銅高塔之中，不許任何男子接近。然而宙斯化身為一陣金色雨絲，穿過高塔的縫隙，與達那厄相會，誕下了柏修斯。國王得知後大為驚恐，將母子二人封入一只木箱，拋入大海，任其自生自滅。所幸木箱漂流至一座島嶼，被當地漁夫救起，柏修斯自此在島上長大成人。',
      '島上的國王覬覦達那厄的美貌，為了支開柏修斯，設下計謀，要求他去取回蛇髮女妖梅杜莎的頭顱——凡是與梅杜莎四目相對的生物，都會瞬間化為石像，這幾乎是一項必死無疑的任務。然而柏修斯獲得了諸神的相助：雅典娜贈予他一面光可鑑人的青銅盾牌，荷米斯借予他飛鞋與彎刀，冥王的頭盔則能讓他隱身。柏修斯憑藉盾牌的反射，避開了與梅杜莎直視的危險，成功斬下了她的頭顱。',
      '在返鄉途中，柏修斯飛越衣索比亞海岸，見到公主安卓美達被鎖鏈綁在岩石上，即將獻祭給一頭海怪，只因她的母親曾誇口女兒美貌勝過海中仙女，觸怒了海神。柏修斯當場擊殺海怪，救下安卓美達，並娶她為妻。多年後，柏修斯參加一場擲鐵餅比賽，鐵餅意外偏離軌道，擊中了台下觀眾席中一位年邁的老者——那人正是他素未謀面的外祖父阿克里西俄斯。多年前的預言，終究以柏修斯自己也未曾預料到的方式應驗。'
    ]},
  { id:'medusa', gen:'hero', zh:'梅杜莎', gr:'Medusa', roman:'同名 Medusa', epithet:'一眼便能石化世人的蛇髮女妖',
    domain:'恐懼、詛咒、致命的凝視', symbol:'蛇髮與石化之眼', parents:[], links:['athena','perseus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'梅杜莎原本是一位容貌絕美的凡間女子，因故觸怒雅典娜，被詛咒成一頭蛇髮女妖，任何直視她雙眼的生物，都會瞬間化為石像。她最終被英雄柏修斯斬首，鮮血落地化為飛馬佩加索斯，她的頭顱此後仍具有石化的力量，被柏修斯用來對付敵人。',
    fullStory:[
      '梅杜莎原本是海神波賽頓神廟裡的一位凡間祭司，容貌美豔動人。傳說波賽頓在雅典娜的神廟裡冒犯了她，雅典娜遷怒於梅杜莎，將她的一頭秀髮化為滿頭毒蛇，容貌也隨之扭曲成任何生物直視便會當場石化的恐怖模樣——這則神話的責任歸屬，在後世不同版本裡屢屢引發爭議，不少現代學者與作家，重新詮釋這則故事時，特別強調梅杜莎本身其實才是這場悲劇裡真正的受害者。',
      '梅杜莎此後獨自居住在世界盡頭一座荒涼的島嶼上，英雄柏修斯奉命取下她的首級，藉助雅典娜贈予的青銅盾牌（可映照出梅杜莎的倒影，避免與她雙眼直接對視）、荷米斯贈予的飛鞋，成功將她斬首。梅杜莎倒地時，鮮血滴落大地，竟化生出一匹展翅的飛馬佩加索斯——這正是她與波賽頓所生的孩子，直到死後才得以降生。柏修斯此後將梅杜莎的頭顱隨身攜帶，多次用來將敵人石化脫困，這顆頭顱最終被獻給雅典娜，鑲嵌在她的神盾埃癸斯正中央，成為女神盾牌上最具威懾力的裝飾。'
    ]},
  { id:'danae', gen:'hero', zh:'達那厄', gr:'Danaë', roman:'同名 Danae', epithet:'被囚禁高塔、宙斯化為金雨造訪的公主',
    domain:'囚禁、母愛、不可違逆的預言', symbol:'青銅高塔與金雨', parents:[], links:['zeus','perseus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'達那厄是阿爾戈斯公主，因神諭警告她的兒子將弒殺外祖父，被父親囚禁在一座青銅高塔之中，卻仍被化身金雨的宙斯造訪，誕下英雄柏修斯——這則預言最終仍以誰也未曾預料的方式應驗。',
    fullStory:[
      '達那厄是阿爾戈斯國王阿克里西俄斯之女。阿克里西俄斯膝下無子，向神諭求問，得到的答案卻是一則令他毛骨悚然的警告：他終將死於自己外孫之手。為了阻止這則預言成真，阿克里西俄斯將達那厄囚禁在一座密不透風的青銅高塔之中，不許任何男子接近，企圖徹底斷絕女兒生育後代的可能。',
      '然而宙斯對達那厄的美貌一見傾心，化身為一陣金色雨絲，穿透高塔的縫隙與她相會，達那厄因此誕下了柏修斯。阿克里西俄斯得知後大為驚恐，卻不敢直接殺害女兒與外孫、觸怒宙斯，只得將母子二人封入一只木箱，拋入大海，任其自生自滅——所幸木箱漂流至一座島嶼，母子倆因此得以倖存，柏修斯也在島上長大成人，日後那則關於「死於外孫之手」的預言，最終仍以誰也未曾預料的方式，於一場擲鐵餅意外中應驗。'
    ]},
  { id:'andromeda', gen:'hero', zh:'安卓美達', gr:'Andromeda', roman:'同名 Andromeda', epithet:'被獻祭給海怪、後被柏修斯所救的公主',
    domain:'犧牲、拯救、星空的紀念', symbol:'鎖鏈與海怪', parents:[], links:['perseus'],
    astro:'仙女座（Andromeda）是天空中一個著名的星座，其中的「仙女座星系」（M31）是肉眼可見、離銀河系最近的大型鄰近星系，也是人類肉眼所能觀測到最遙遠的天體之一。',
    story:'安卓美達是衣索比亞公主，因母親誇口女兒美貌勝過海中仙女，觸怒海神，被鎖鏈綁在海邊岩石上獻祭給海怪，所幸英雄柏修斯途經此地，擊殺海怪救下了她，兩人結為夫妻，死後雙雙被諸神升上夜空，化為緊鄰的星座。',
    fullStory:[
      '安卓美達是衣索比亞國王刻甫斯與王后卡西俄佩亞之女。卡西俄佩亞生性愛慕虛榮，公開誇口自己（或女兒）的美貌，勝過海神波賽頓身邊的海中仙女涅瑞伊得斯，這番狂妄之言觸怒了波賽頓，他降下一頭海怪，肆虐衣索比亞沿海。神諭指示，唯有將安卓美達獻祭給海怪，災禍才能平息，絕望的國王夫婦只得將女兒鎖鏈綁在海邊的岩石上，等候海怪降臨。',
      '恰逢英雄柏修斯完成斬殺蛇髮女妖梅杜莎的任務、乘著飛鞋返鄉途中，飛越此地，一眼看見了命懸一線的安卓美達，當場對她一見鍾情。柏修斯與國王談妥，若能救下公主，便將她許配為妻，隨即持劍擊殺了海怪，解救了安卓美達。兩人婚後育有多名子女，死後，雅典娜將這對夫妻連同她的父母，一同升上夜空，化為彼此緊鄰的星座——安卓美達座裡的仙女座星系，是人類肉眼所能望見最遙遠的天體之一，某種程度上，也讓這則兩千多年前的拯救故事，至今仍高懸夜空、遙遙可見。'
    ]},
  { id:'semele', gen:'hero', zh:'賽默勒', gr:'Semele', roman:'同名 Semele', epithet:'戴歐尼修斯的凡人母親',
    domain:'凡人的愛戀、被神聖焚毀的軀體', symbol:'雷電與底比斯王室', parents:[], links:['zeus','dionysus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'賽默勒是底比斯凡人公主，與宙斯相戀懷有身孕，卻因赫拉的嫉妒設局，要求宙斯以真實神聖形貌現身，凡人肉身無法承受神威而當場化為灰燼——宙斯搶救出腹中胎兒縫入自己大腿孕育，這名胎兒便是日後的酒神戴歐尼修斯。',
    fullStory:[
      '賽默勒是底比斯國王卡德摩斯之女，容貌出眾，與宙斯相戀懷有身孕。善妒的赫拉察覺此事後，並未直接對賽默勒下手，而是化身為她年邁的乳母，一步步慫恿賽默勒心生疑慮——既然情人自稱是宙斯本人，何不要求他以真實的神聖形貌現身，作為愛意最有力的證明？',
      '賽默勒天真地向宙斯提出了這個要求，宙斯早已對她立下絕不可違背的重誓，即便深知後果，也只能無奈應允。然而凡人的血肉之軀，終究無法承受神祇真身所散發的雷霆與烈焰，賽默勒在宙斯現出真身的瞬間，當場被燒成灰燼、香消玉殞。宙斯在最後一刻搶救出她腹中尚未足月的胎兒，縫入自己的大腿中繼續孕育，直到足月才取出降生——這名胎兒，正是日後掌管酒與狂歡的戴歐尼修斯，他也因此被稱為「二次誕生之神」。後世的酒神信仰儀式裡，賽默勒本人也逐漸被尊崇為一位半神性質的存在，據說戴歐尼修斯成年後，還曾親自下冥界尋回母親的靈魂，將她接至奧林帕斯山長住。'
    ]},
  { id:'jason', gen:'hero', zh:'伊阿宋', gr:'Jason', roman:'同名 Iason', epithet:'率領阿爾戈號尋找金羊毛的統帥',
    domain:'冒險、王位的正統性、背叛', symbol:'阿爾戈號與金羊毛', parents:[], links:['chiron','medea'],
    astro:'木星的特洛伊小行星群裡，有一顆便以「伊阿宋」命名。',
    story:'伊阿宋是伊俄爾科斯王位的正統繼承人，自幼受半人馬凱隆撫養教導，成年後率領一群希臘英雄組成的阿爾戈號船隊，遠征科爾基斯尋找金羊毛，途中得到女巫美狄亞相助，才得以完成這項幾乎不可能的任務。',
    fullStory:[
      '伊阿宋的叔叔珀利阿斯篡奪了本應屬於伊阿宋父親的伊俄爾科斯王位，年幼的伊阿宋因此被秘密送往珀利翁山，交由半人馬凱隆撫養教導。成年後，伊阿宋返回伊俄爾科斯，向珀利阿斯討回王位，珀利阿斯表面應允，卻開出一個近乎不可能的條件——唯有取回遠在科爾基斯的金羊毛，才能繼承王位。',
      '伊阿宋召集了當時希臘最傑出的一批英雄，共同搭乘特製的阿爾戈號船，展開了這場史詩級的遠征——隊伍裡包括了海克力斯、雙子星卡斯托爾與波魯克斯等人。抵達科爾基斯後，當地國王同樣提出了幾乎不可能完成的試煉，所幸國王之女、精通魔法的美狄亞對伊阿宋一見鍾情，暗中以魔法相助，伊阿宋才得以通過試煉、取得金羊毛，並帶著美狄亞一同逃離科爾基斯。',
      '伊阿宋與美狄亞歷經千辛萬苦返回希臘，卻在多年後，伊阿宋為了政治聯姻而拋棄了美狄亞，另娶科林斯公主——這個決定，最終引爆了希臘神話裡最令人不寒而慄的一場復仇。'
    ]},
  { id:'medea', gen:'hero', zh:'美狄亞', gr:'Medea', roman:'同名 Medea', epithet:'為愛不惜弒親、後又復仇弒子的女巫',
    domain:'魔法、復仇、母愛的黑暗面', symbol:'毒藥與飛龍戰車', parents:[], links:['jason'],
    astro:'主帶小行星212 Medea便以她為名。',
    story:'美狄亞是科爾基斯公主，精通魔法，愛上前來尋找金羊毛的伊阿宋，不惜背叛父親、弒殺親弟以助他脫身。多年後，伊阿宋另娶他人拋棄她，美狄亞在極致的悲憤中，親手殺死了自己與伊阿宋所生的孩子，作為對負心丈夫最慘烈的報復。',
    fullStory:[
      '美狄亞是科爾基斯國王埃厄忒斯之女，精通巫術，是太陽神赫利歐斯的孫女。伊阿宋率領阿爾戈號船隊抵達科爾基斯尋找金羊毛時，美狄亞對他一見鍾情，違背父命，暗中以魔法藥膏助他通過重重試煉，甚至在逃亡途中，親手將自己的親弟弟殺害分屍、拋入海中，藉此拖延追兵——她為了這段愛情，付出的代價極其慘烈。',
      '美狄亞與伊阿宋歷經波折返回希臘，一路上她多次施展魔法助伊阿宋脫困，甚至以計謀讓篡位的珀利阿斯死於自己女兒之手。兩人育有數名子女，本該安穩度日，伊阿宋卻在多年後，為了迎娶科林斯公主、鞏固自己的政治地位，決定拋棄美狄亞。',
      '遭到背叛的美狄亞陷入極致的悲憤，她先以浸過毒藥的禮服殺死了伊阿宋即將迎娶的新娘與岳父，接著，在這場復仇裡做出了希臘神話裡最令人震驚的抉擇——親手殺死了自己與伊阿宋所生的孩子，只為讓伊阿宋在餘生裡，永遠背負著失去至親的痛苦。她最終乘著祖父赫利歐斯賜予的飛龍戰車揚長而去，未受到任何懲罰——這則故事後世不斷被重新搬演，尤其是古希臘悲劇作家歐里庇得斯的版本，將美狄亞塑造成一位在父權社會裡被逼至絕境、卻依然令人不寒而慄的複雜女性形象。'
    ]},
  { id:'adonis', gen:'hero', zh:'阿多尼斯', gr:'Adonis', roman:'同名 Adonis', epithet:'令阿芙蘿黛蒂傾心的絕美凡人',
    domain:'美貌、狩獵、早逝的青春', symbol:'銀蓮花與野豬獠牙', parents:[], links:['aphrodite','persephone'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'阿多尼斯是容貌絕美的凡間青年，令阿芙蘿黛蒂與波瑟芬妮同時傾心、甚至為他爭執不休，最終在一次狩獵中被野豬咬死，鮮血落地化為銀蓮花——他的生死，此後每年在冥界與人間之間往返，成為希臘神話裡另一則「季節輪替」的敘事。',
    fullStory:[
      '阿多尼斯自幼容貌便異於常人，阿芙蘿黛蒂對他一見傾心，將尚是嬰兒的他託付給冥后波瑟芬妮撫養。然而波瑟芬妮同樣被阿多尼斯的美貌深深吸引，長大成人後拒絕將他交還，兩位女神因此爭執不下，最終請宙斯出面裁決——宙斯判定，阿多尼斯一年之中，須有三分之一的時間陪伴波瑟芬妮留在冥界，三分之一與阿芙蘿黛蒂共度人間，剩餘三分之一則由他自己決定。',
      '阿多尼斯熱愛狩獵，儘管阿芙蘿黛蒂再三警告他狩獵猛獸的危險，他仍舊執意獨自出獵，一次意外遭遇一頭野豬（傳說是善妒的戰神阿瑞斯化身，或受阿瑞斯指使），被野豬獠牙刺穿身亡。阿芙蘿黛蒂聞訊悲痛欲絕，趕至他倒地之處，他的鮮血滴落之處，竟綻放出一片鮮紅色的銀蓮花——這則故事後來與波瑟芬妮、狄蜜特的季節神話相互呼應，共同構成希臘神話裡，用「凡人短暫的生死」比喻「大地萬物枯榮循環」最動人的一組敘事。'
    ]},
  { id:'hyacinthus', gen:'hero', zh:'海亞辛斯', gr:'Hyacinthus', roman:'同名 Hyacinthus', epithet:'因意外死於鐵餅、化為風信子的斯巴達王子',
    domain:'美貌、意外的死亡、永恆的哀悼', symbol:'風信子與鐵餅', parents:[], links:['apollo'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'海亞辛斯是容貌俊美的斯巴達王子，深受太陽神阿波羅寵愛，兩人時常一同競技遊玩，卻在一次擲鐵餅遊戲中，海亞辛斯意外被鐵餅擊中頭部身亡（一說是善妒的西風之神齊費羅斯故意將鐵餅吹偏）。阿波羅悲痛不已，讓他鮮血滴落之處綻放出以他為名的花朵——風信子。',
    fullStory:[
      '海亞辛斯是斯巴達王子，容貌俊美出眾，太陽神阿波羅對他極為寵愛，兩人時常一同狩獵、競技，形影不離。然而，西風之神齊費羅斯同樣深深愛慕著海亞辛斯，見他獨獨鍾情於阿波羅，心中妒火中燒。',
      '一日，阿波羅與海亞辛斯一同玩擲鐵餅遊戲，阿波羅擲出的鐵餅在空中劃出一道優美的弧線，海亞辛斯興奮地追上前去接住——就在此時，一陣不尋常的強風突然吹來，將鐵餅的軌跡整個吹偏，狠狠擊中了海亞辛斯的頭部，多數版本都指向，這正是妒火中燒的齊費羅斯暗中所為。阿波羅眼睜睜看著心愛之人倒在血泊之中，卻因身為神祇無法以醫術挽回凡人的性命，只能悲痛地讓他的鮮血滴落之處，綻放出一朵朵深紫色的花——阿波羅將這種花命名為「海亞辛斯」（也就是後世的風信子），並讓花瓣上天然的紋路，永遠帶著如同哀悼般的印記，年年提醒世人這段悲劇。'
    ]},
  { id:'theseus', gen:'hero', zh:'忒修斯', gr:'Theseus', roman:'同名 Theseus', epithet:'雅典的建國英雄',
    domain:'智謀、王權', symbol:'線團與雙劍', parents:['poseidon'], links:['ariadne','daedalus'],
    astro:'木星的特洛伊小行星群中，有一顆便以他命名為 1809 Theseus，與其他神話英雄一同環繞木星運行。',
    story:'忒修斯身世特殊，同時是海神波賽頓與雅典國王埃勾斯之子。他自願前往克里特島，藉助公主亞莉阿德妮贈與的線團，在迷宮中殺死牛頭怪彌諾陶洛斯，日後成為雅典的傳奇君王。',
    fullStory:[
      '忒修斯的身世頗為特殊：雅典國王埃勾斯與特羅曾公主埃特拉在同一夜分別與凡人及海神波賽頓結合，因此忒修斯身兼「凡間王子」與「海神之子」的雙重血統。埃勾斯在離開特羅曾之前，將自己的佩劍與涼鞋藏在一塊巨石之下，囑咐若日後兒子力大能移開巨石，便讓他前來雅典相認。多年後，成年的忒修斯果然輕鬆搬開巨石，取出信物，動身前往雅典。',
      '當時的雅典正被克里特島的彌諾斯王掌控，每隔九年，雅典必須獻上七對童男童女，送入代達羅斯所建造的迷宮之中，餵食盤據其中、人身牛頭的怪物彌諾陶洛斯。忒修斯得知此事後，自願加入獻祭的隊伍，決心終結這場悲劇。抵達克里特島後，彌諾斯王的女兒亞莉阿德妮公主對他一見鍾情，暗中贈予他一團線球，教他在進入迷宮時將線頭繫在入口，一路展開，如此便能在殺死怪物後循著線路安全走出這座錯綜複雜的迷宮。',
      '忒修斯憑藉線團與過人的勇氣，成功在迷宮深處殺死了彌諾陶洛斯，解救了雅典的童男童女，並帶著亞莉阿德妮一同啟程返鄉。然而歸途中，他卻將公主遺棄在納克索斯島上（後來她被酒神戴歐尼修斯所救並娶為妻）。更令人遺憾的是，忒修斯在返航時忘記依照約定，將船帆由黑色換成象徵勝利的白色——在岸邊終日盼望的父親埃勾斯望見遠方依舊懸掛的黑帆，誤以為兒子已經喪命，悲痛之下投海自盡。忒修斯自此繼承王位，成為雅典史上最受尊崇的君王，據信他日後更推動了雅典城邦的政治統一，為這座城市奠定了深遠的立國基礎。'
    ]},
  { id:'ariadne', gen:'hero', zh:'亞莉阿德妮', gr:'Ariadne', roman:'同名 Ariadne', epithet:'用一團線救出忒修斯的克里特公主',
    domain:'迷宮、忠貞、被遺棄的愛情', symbol:'線團', parents:[], links:['theseus','dionysus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'亞莉阿德妮是克里特國王米諾斯之女，愛上前來挑戰迷宮的忒修斯，向工匠代達洛斯求教，想出以線團繫在入口、一路展開的辦法，助他成功殺死彌諾陶洛斯、逃出生天。忒修斯卻在返航途中將她遺棄在納克索斯島，所幸酒神戴歐尼修斯途經此地，對她一見鍾情，娶她為妻。',
    fullStory:[
      '亞莉阿德妮是克里特國王米諾斯與王后帕西法厄之女，同父異母的弟弟正是被囚禁在迷宮深處、每年需要雅典獻上童男童女祭品的牛頭怪彌諾陶洛斯。當雅典王子忒修斯自願前來挑戰迷宮、企圖終結這場獻祭時，亞莉阿德妮對他一見傾心，暗中向迷宮的建造者代達洛斯求教，得知只要將一團線繫在迷宮入口、一路深入時緩緩展開，事後就能沿著線團原路脫身。',
      '忒修斯依計行事，成功殺死彌諾陶洛斯，並沿著亞莉阿德妮給予的線團，順利逃出這座曾令無數人有去無回的迷宮。亞莉阿德妮不惜背叛自己的家族與父親，隨忒修斯一同搭船離開克里特島，卻沒想到，忒修斯竟在返航途中，趁她熟睡之際，將她獨自遺棄在納克索斯島上——他遺棄的原因，在不同版本裡眾說紛紜，有人說是變心，也有人說是奉神諭行事，不得不然。所幸酒神戴歐尼修斯途經此地，對傷心欲絕的亞莉阿德妮一見鍾情，娶她為妻，並將她的黃金冠冕擲上夜空，化為「北冕座」——這則故事的結局，也讓亞莉阿德妮的命運，從一則背叛與遺棄的悲劇，意外轉折成另一場神聖婚姻的開端。'
    ]},
  { id:'aeneas', gen:'hero', zh:'埃涅阿斯', gr:'Aeneas', roman:'同名 Aeneas', epithet:'特洛伊的流亡者',
    domain:'虔誠、命運', symbol:'背負老父逃離火城', parents:['aphrodite'],
    astro:'木星的特洛伊小行星群中，有一顆便以他命名為 1172 Äneas，靜靜地與其他特洛伊英雄一同環繞木星運行。',
    story:'埃涅阿斯是愛神阿芙蘿黛蒂與凡人安基塞斯之子，特洛伊淪陷之時，他背著年邁的父親、牽著幼子逃出火海。羅馬詩人維吉爾在史詩《埃涅阿斯記》中，將他描寫為羅馬人的祖先，銜接了希臘神話與羅馬建國傳說。',
    fullStory:[
      '埃涅阿斯是愛神阿芙蘿黛蒂與特洛伊貴族安基塞斯之子。傳說阿芙蘿黛蒂被宙斯施法，使她愛上了這位凡人牧羊人，兩人結合誕下埃涅阿斯，女神並囑咐安基塞斯不得向外人透露孩子真正的身世。埃涅阿斯自幼便展現出過人的勇氣與虔誠，在特洛伊戰爭期間，他是僅次於赫克托爾的重要將領，據荷馬記載，他甚至曾與希臘第一勇士阿基里斯正面交鋒，幸得海神波賽頓出手相救才逃過一劫——傳說中，波賽頓之所以救他，正是因為命運早已注定，埃涅阿斯與他的後裔將延續特洛伊的血脈。',
      '當希臘人以木馬計攻破特洛伊城牆、城內陷入一片火海與屠殺之時，埃涅阿斯本欲奮戰到底，卻在夢中或神啟中意識到，自己肩負著比守衛這座即將淪陷的城市更重要的使命。他將年邁行動不便的父親安基塞斯背負在肩上，一手牽著年幼的兒子阿斯卡尼俄斯，帶領著一批倖存的特洛伊人，在戰火與混亂中殺出一條血路，逃離了這座燃燒的城市——他的妻子克瑞烏莎則在逃亡途中的混亂中與眾人失散，最終未能一同脫身。',
      '羅馬詩人維吉爾在史詩《埃涅阿斯記》中，接續了這段流亡的旅程：埃涅阿斯率領倖存者輾轉漂泊地中海各地，途中曾與迦太基女王狄多相戀，卻因神諭指引的命運而忍痛離去，最終抵達義大利半島，在此建立了日後羅馬文明的根基。透過埃涅阿斯這位「戰敗者的後裔」，古羅馬人巧妙地將自己的起源，與希臘神話中最偉大的一場戰爭連結在一起，也讓特洛伊的陷落，不再只是一個結局，而成為了另一個文明的開端。'
    ]},

  { id:'pandora', gen:'hero', zh:'潘朵拉', gr:'Pandora', roman:'同名 Pandora', epithet:'帶來第一份「祝福」與第一場災難的女子',
    domain:'好奇心、災禍的起源、諸神的懲罰', symbol:'封閉的陶罐', parents:[], links:['zeus','iapetus','prometheus'],
    astro:'主帶小行星55 Pandora便以她為名；土星也有一顆衛星叫「潘朵拉」，與另一顆衛星共同牧守著土星的細窄F環。',
    story:'潘朵拉是眾神合力打造的第一位凡間女子，宙斯為了報復普羅米修斯盜火贈予人類，命匠神赫菲斯托斯以陶土捏塑出她的身形，再讓眾神各自賜予她一份「禮物」——她的名字「潘朵拉」，正是希臘文「集眾神饋贈於一身」之意。她奉命嫁給普羅米修斯之弟厄庇墨透斯，卻在好奇心驅使下，打開了那只裝滿災禍的陶罐，讓疾病、憂愁與死亡從此進入人間。',
    fullStory:[
      '普羅米修斯盜取天火贈予人類後，宙斯決心報復，卻沒有直接懲罰人類本身，而是設下了一個更精巧的陷阱——他命匠神赫菲斯托斯以水與陶土，捏塑出希臘神話裡第一位凡間女子的身形。隨後，眾神紛紛獻上各自的「禮物」：雅典娜教她織布與手藝，阿芙蘿黛蒂賦予她無可抗拒的美貌，荷米斯則悄悄在她心中植入了謊言與狡黠的言辭——她的名字「潘朵拉」，在希臘文裡正是「集眾神饋贈於一身」的意思。',
      '宙斯將潘朵拉送給普羅米修斯的弟弟厄庇墨透斯為妻——儘管普羅米修斯（意為「先見之明」）早已再三警告弟弟，絕不可接受宙斯贈予的任何禮物，但厄庇墨透斯（意為「後見之明」）終究沒能抵擋潘朵拉的美貌，娶她為妻。潘朵拉隨身帶著一只陶罐（後世常誤譯為「盒子」），宙斯早已叮囑她絕不可打開，然而好奇心終究戰勝了戒心——她揭開罐蓋的那一刻，疾病、憂傷、嫉妒、衰老等種種災禍，全數從罐中飛散而出，從此進入了人間。',
      '據說當潘朵拉驚慌之下重新蓋上罐蓋時，罐底卻只剩下一樣東西尚未逃逸——「希望」。這則神話的結尾，長久以來引發各種不同的詮釋：有人認為，希望之所以被留在人間，是眾神留給人類唯一的慈悲；也有人認為，希望本身其實也是宙斯設下的另一重陷阱——讓人類即使身處無盡的苦難之中，也永遠懷抱著虛妄的期待，遲遲不肯真正認清處境。潘朵拉的故事，與希伯來聖經裡夏娃因好奇而食下禁果、為人間帶來苦難的敘事，形成了一次跨文化的深刻呼應——兩則神話，都不約而同地，將人類苦難的起源，追溯回一位女性因好奇心而做出的選擇。'
    ]},

  { id:'deucalion', gen:'hero', zh:'丟卡利翁', gr:'Deucalion', roman:'同名 Deucalion', epithet:'希臘神話裡大洪水後的人類始祖',
    domain:'大洪水、重建人類、虔誠', symbol:'木箱與新生的石頭人', parents:['prometheus'], links:['zeus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'丟卡利翁是泰坦神普羅米修斯之子，當宙斯因人類墮落而降下大洪水滅世時，他與妻子皮拉因預先受到父親警告、建造了一只木箱得以倖存，成為希臘神話裡大洪水後人類重新繁衍的始祖——夫妻倆遵循神諭，將石頭拋在身後，石頭竟一一化為新生的人類。',
    fullStory:[
      '丟卡利翁是泰坦神普羅米修斯之子——正因為普羅米修斯擁有「先見之明」的預知能力，他早早便警告兒子，宙斯已經決心以一場毀滅性的大洪水，終結墮落敗壞的青銅時代人類。丟卡利翁依照父親的指示，建造了一只巨大的木箱，與妻子皮拉一同儲備糧食，靜候洪水降臨。',
      '大洪水持續了九天九夜，淹沒了整片希臘大地，唯獨丟卡利翁夫婦乘著木箱倖存，最終在帕納索斯山頂停靠。洪水退去後，兩人向神諭求教，該如何重新讓人類在大地上繁衍——神諭給出的指示晦澀難解：「蒙上臉，解開衣帶，將你們母親的骨頭，拋到身後。」夫妻倆百思不得其解，最終皮拉靈光一閃，領悟到神諭所說的「母親」，其實是指大地本身，而「骨頭」，指的正是地上的石頭。',
      '於是兩人蒙面解衣，一路將撿拾的石頭拋在身後——丟卡利翁拋出的石頭，一一化為男子；皮拉拋出的石頭，則化為女子。希臘神話裡的人類，便是由這些「石頭之子」重新繁衍而來。這則故事後來也被用來解釋「laos」（希臘文的「人民」）一詞的由來，因為它與「laas」（石頭）發音相近——丟卡利翁與皮拉的洪水傳說，此後也長期被拿來與近東地區流傳的洪水滅世敘事（包括《吉爾伽美什史詩》與希伯來聖經裡的諾亞方舟）相互比較，是探討「洪水神話」這一世界性母題時，最常被引用的希臘版本。'
    ]},

  // ---------- NATURE SPIRITS (outside the Olympian order) ----------
  { id:'pan', gen:'nature', zh:'潘', gr:'Pan', roman:'（後與法翁努斯融合）', epithet:'荒野牧神',
    domain:'荒野、牧羊、恐慌、音樂', symbol:'蘆笛與羊角', parents:['hermes'],
    counterpart:'faunus',
    astro:'土星有一顆真實存在的衛星就叫「潘」（Pan），1990年被發現，恰好運行於土星環的一道縫隙（恩克環縫）之中，如同真正的牧神穿梭在自己的牧場邊界上。',
    story:'潘是希臘本土、阿卡迪亞地區的古老牧神，人身羊足、頭生雙角，是宙斯之子荷米斯與一位山林仙女所生。他掌管荒野、牧羊與即興的蘆笛音樂，「恐慌」（panic）一詞正源自於他能在寂靜山林中憑空喚起的莫名恐懼。',
    fullStory:[
      '潘是希臘神話中格外「土生土長」的一位神祇——他的信仰核心始終落在阿卡迪亞，那是伯羅奔尼撒半島上多山、多牧地、遠離城市文明的荒僻地區。也因此，潘從未真正被吸納進奧林帕斯山上那個講究秩序與位階的神界核心，他始終是山林與牧地之神，屬於邊界，而非殿堂。',
      '關於他的身世，較常見的說法是：他是荷米斯與一位山林仙女（一說德律俄佩，一說佩涅羅佩）所生之子。傳說他一出生便是人身羊足、額生雙角、滿臉鬍鬚的模樣，母親一見到他的長相便嚇得逃離。荷米斯卻對這個孩子的模樣愛不釋手，將他用兔皮包裹，抱上奧林帕斯山展示給眾神看，眾神見了無不歡喜——後世作家便附會，「潘」這個名字與希臘語「全部、所有」（pan）諧音，象徵他「使眾神皆感愉悅」。',
      '潘最著名的故事，與他所發明的樂器「排簫」（Syrinx）有關。傳說他愛上了一位名叫緒任克斯的仙女，緒任克斯不堪其擾、拚命奔逃至一條河邊，眼看即將被追上，她向河神求助，瞬間化為一叢中空的蘆葦。潘悵然若失，卻靈機一動，將長短不一的蘆葦割下，並排束成一件樂器，以此紀念這段無疾而終的愛戀——這便是排簫的由來，也是潘最重要的象徵物之一。',
      '潘同時也是「恐慌」（panic）一詞的神話起源。古希臘人相信，獨自行走於荒山野嶺、或在寂靜午後突然感到的莫名恐懼，正是潘在附近出沒所引發的——這種不安並非來自任何具體的威脅，而是曠野本身的神祕與不可預測。據史書記載，西元前490年的馬拉松戰役前夕，潘曾在夢中向雅典信使菲迪皮德斯許諾相助；戰役中，波斯軍隊據說也確實陷入了莫名的恐慌潰散，雅典人因此在戰後於衛城腳下為潘建立了神廟，感念他的庇佑。'
    ]},

  { id:'satyrs', gen:'nature', zh:'薩堤爾', gr:'Satyroi', roman:'法翁 Fauns', epithet:'林間的頑皮精靈',
    domain:'荒野、酒宴、嬉鬧', symbol:'羊尾與酒囊', parents:[],
    astro:'目前沒有正式的天體命名，但他們放蕩不羈的形象，常被後世藝術與文學借用來形容任何「狂野失控」的自然現象或氛圍。',
    story:'薩堤爾是一整個種族的山林精靈，人身羊尾（有時也有羊足），常年追隨酒神戴歐尼修斯的隊伍，以貪杯、好色、愛惡作劇聞名，是希臘藝術中最常見的荒野配角之一。',
    fullStory:[
      '薩堤爾並非單一一位神祇，而是一整個種族的荒野精靈，數量眾多，性格幾乎千篇一律：貪戀美酒、追逐仙女、喜好音樂與舞蹈，總是帶著幾分頑劣的惡作劇性格。他們的外貌通常是人的上半身，配上馬尾或羊尾，部分傳統中還加上一對小小的羊角與微微前凸的耳朵，是希臘陶瓶畫上出現頻率極高的角色。',
      '薩堤爾們幾乎從不單獨行動，而是成群結隊追隨在酒神戴歐尼修斯的巡遊隊伍之中，與同樣縱情狂歡的邁納德斯狂女一起，組成了戴歐尼修斯祭典中最喧鬧、最不受拘束的一群隨從。他們象徵著人類天性中未經馴化的一面——衝動、慾望、對享樂毫不掩飾的追求，與雅典娜所代表的理性、阿波羅所代表的秩序恰成兩極。',
      '儘管形象多半滑稽而放蕩，薩堤爾在希臘悲劇文化中卻意外佔有一席重要地位：古希臘的戲劇節在正劇之後，慣例會演出一齣輕鬆詼諧的「薩堤爾劇」作為調劑，劇中的合唱團便打扮成薩堤爾的模樣插科打諢。透過這個傳統，薩堤爾這個看似邊緣的荒野形象，反而深深嵌入了古希臘最核心的公共藝術活動之中。'
    ]},

  { id:'silenus', gen:'nature', zh:'西勒諾斯', gr:'Silenos', roman:'同名 Silenus', epithet:'年長的智慧醉漢',
    domain:'酒、預言、養育', symbol:'酒罈與驢子', parents:[],
    astro:'目前沒有正式對應的天體命名。',
    story:'西勒諾斯是年長、肚腹圓滾、常年醉醺醺的薩堤爾，傳說是酒神戴歐尼修斯幼年的導師與養父，儘管平時醉態可掬，據說一旦被灌醉捕獲，便會道出深奧難解的預言與智慧。',
    fullStory:[
      '西勒諾斯是薩堤爾一族中年紀最長、地位也最特殊的一位——他常被描繪成一位肚腹圓滾、禿頭、蓄著大鬍子、總是醉醺醺地騎在驢背上、需要旁人攙扶才不至於跌倒的老者形象。與其他薩堤爾單純追求享樂不同，西勒諾斯身上多了一層「智者」的色彩。',
      '傳說西勒諾斯是幼年戴歐尼修斯的導師，甚至一說是他的養父，教導這位日後的酒神各種釀酒與狂歡儀式的奧秘。也因此，成年後的戴歐尼修斯待他極為敬重，即便西勒諾斯終日爛醉、行為滑稽，也始終將他留在自己的隨行隊伍之中，備受禮遇。',
      '西勒諾斯最富傳奇色彩的故事，與他「醉後吐真言」的能力有關：據說凡人若能設法將他灌醉並趁機捕獲、加以束縛，他便會被迫道出隱藏極深的智慧與預言。弗里吉亞國王邁達斯便曾以此設下酒宴陷阱，成功擒住西勒諾斯，逼問出一番關於人生本質、悲喜無常的深刻箴言——這則故事後來也被哲學家們反覆引用，將西勒諾斯塑造為「醉態之中藏有真理」這一古老母題的代表人物。'
    ]},

  { id:'priapus', gen:'nature', zh:'普里阿普斯', gr:'Priapos', roman:'同名 Priapus', epithet:'園圃與豐產之神',
    domain:'生殖、果園、家畜', symbol:'豐饒角與果園', parents:['dionysus','aphrodite'],
    astro:'目前沒有正式對應的天體命名。',
    story:'普里阿普斯是酒神戴歐尼修斯與愛神阿芙蘿黛蒂之子，掌管果園、菜圃與家畜的豐產。傳說赫拉曾詛咒他生來畸形醜陋，因此被母親遺棄山野，最終仍成為鄉間農人虔誠供奉、祈求豐收的守護神。',
    fullStory:[
      '普里阿普斯的父母是希臘神話中兩位形象反差極大的神祇：狂放不羈的酒神戴歐尼修斯，與美麗優雅的愛神阿芙蘿黛蒂。然而，關於他的誕生，卻流傳著一則格外悲傷的插曲——傳說善妒的赫拉不滿阿芙蘿黛蒂的美貌，暗中對懷孕中的她下咒，使腹中的孩子生來便異常醜陋。阿芙蘿黛蒂見到孩子的模樣後大感羞恥，將他遺棄在弗里吉亞的荒山野嶺之中。',
      '所幸，被遺棄的普里阿普斯由當地的牧羊人拾獲並撫養長大。儘管外貌始終不受待見，他卻逐漸展現出守護果園、菜圃與牲畜豐產的神聖力量，鄉間的農人與果農開始為他立起簡陋的木製雕像，安放在田園之中，祈求作物豐收、牲畜興旺，也用以嚇阻偷竊蔬果的盜賊與鳥獸。',
      '普里阿普斯的信仰雖然起源於相對邊緣、甚至帶有喜劇色彩的鄉野傳統，卻在希臘化時代與羅馬時期廣泛流傳開來，成為地中海地區農家庭院中極為常見的守護象徵。他的故事也提醒著人們：在希臘神話的世界觀裡，即便是最受排斥、最不符合「完美神祇」形象的存在，依然能在人間找到屬於自己、且十分實際的信仰位置。'
    ]},

  { id:'nymphs', gen:'nature', zh:'寧芙仙女', gr:'Nymphai', roman:'同名 Nymphae', epithet:'自然萬物的化身',
    domain:'山林、河川、海洋、樹木', symbol:'清泉與花冠', parents:[],
    astro:'沒有單一對應的天體，但這個名字本身在天文學史上意義重大：十九世紀天文學家曾借用「寧芙」的概念，形容繞行大行星的眾多小型衛星，如同眾女神環繞在主神身邊。',
    story:'寧芙仙女是自然萬物中無所不在的年輕女性精靈，依棲息地不同而分成許多支系：樹林中的德律阿得斯、江河湖泊中的那伊阿得斯、山巒間的俄瑞阿得斯，以及大海中的涅瑞伊得斯，她們是希臘神話中連結「地方」與「神聖」的重要橋樑。',
    fullStory:[
      '寧芙並非單一一位神祇，而是數量龐大、遍布於希臘世界每一個角落的年輕女性自然精靈。她們地位低於奧林帕斯主神，卻與每一片具體的山林、河流、泉水緊密相連——某種意義上，她們就是那個地方本身的神聖化身，是希臘人理解「這片土地是有靈性的」這一信念最直接的體現。',
      '依照棲息之處的不同，寧芙被劃分為許多支系：住在樹木之中、與樹木共存亡的德律阿得斯（其中專屬橡樹的又稱哈瑪德律阿得斯）；居住在泉水、溪流與湖泊中的那伊阿得斯；棲息於山巒與洞穴間的俄瑞阿得斯；以及居住在大海深處、由海神涅柔斯所生的五十位涅瑞伊得斯——阿基里斯的母親忒堤斯，便是其中最著名的一位。',
      '寧芙們雖然地位不算崇高，卻頻繁出現在許多重要神話之中，往往是英雄與神祇愛戀、追逐、甚或衝突的對象——荷米斯與潘的母親、宙斯眾多情人中的俄刻阿尼德斯、被潘追逐化為蘆葦的緒任克斯，都是寧芙。透過她們，希臘神話將「大自然本身值得敬畏」這種樸素的信仰，轉化成了一則又一則生動具體的人物故事。'
    ]},

  { id:'centaurs', gen:'nature', zh:'半人馬', gr:'Kentauroi', roman:'同名 Centauri', epithet:'半人半馬的荒野種族',
    domain:'荒野、狂暴、（凱隆例外：醫術與教育）', symbol:'弓箭與馬蹄', parents:[], links:['prometheus'],
    astro:'天文學上真的有一整類小天體被正式命名為「半人馬族」（Centaurs）——它們軌道游移於木星與海王星之間，性質介於小行星與彗星之間，正如神話中半人半馬的雙重身分。首顆被發現的半人馬型天體，甚至就直接命名為「2060 凱隆」（Chiron）。',
    story:'半人馬族是上半身為人、下半身為馬的荒野種族，多數性情狂暴、嗜酒好鬥，但其中最年長的凱隆卻是截然不同的智者，精通醫術、音樂與預言，是海克力斯、阿基里斯等多位英雄的導師。',
    fullStory:[
      '希臘神話中的半人馬族，多半誕生於一則帶有懲罰意味的故事：色薩利國王伊克西翁曾覬覦天后赫拉，宙斯以雲朵化作赫拉的模樣試探他，伊克西翁與雲之仙女涅斐勒結合，生下的後代便是半人馬——上半身為人，下半身則是馬的驅幹與四肢。這個出身，某種程度上也解釋了半人馬族普遍狂野、易怒、難以自制的性格。',
      '半人馬族最著名的一場衝突，發生在拉皮斯人的婚宴上：受邀出席的半人馬們因酒醉而失控，試圖擄走新娘與其他女賓，引發了一場慘烈的「半人馬之戰」，這場戰役後來成為希臘神廟浮雕上極受歡迎的裝飾題材，象徵著「文明」對「野蠻」的勝利。',
      '然而，半人馬族之中卻有一位截然不同的例外——凱隆。他並非出自伊克西翁的血脈，而是泰坦神克洛諾斯與海洋仙女菲呂拉所生，因此擁有不死之身與截然不同的高潔品格。凱隆精通醫術、音樂、狩獵與預言，隱居在珀利翁山的洞穴之中，教育出了包括海克力斯、阿基里斯、傑森在內的一整代希臘英雄。晚年，他意外被沾有九頭蛇毒血的箭矢誤傷，儘管身為不死之身，傷口卻痛苦難癒，最終他自願將自己的不死之身讓與被鎖在高加索山上的普羅米修斯，換取自己解脫痛苦、平靜死去——宙斯感念他一生的智慧與犧牲，將他的形象升上夜空，成為人馬座。'
    ]},

  { id:'chiron', gen:'nature', zh:'凱隆', gr:'Chiron', roman:'同名 Chiron', epithet:'半人馬中最有智慧的賢者',
    domain:'醫術、教育、犧牲', symbol:'弓箭與藥草', parents:[], links:['prometheus','centaurs'],
    astro:'首顆被發現的「半人馬型天體」，便直接以他命名，稱為「2060 凱隆」——這類天體軌道游移於木星與海王星之間，性質介於小行星與彗星之間，恰好呼應凱隆本人「介於凡人導師與不朽之神之間」的特殊身分。',
    story:'凱隆是半人馬族裡唯一的例外——出身高貴、性情溫和、精通醫術與各類技藝，是海克力斯、阿基里斯等眾多希臘英雄共同的導師。他意外被沾染九頭蛇劇毒的箭矢誤傷，身為不死之身卻求死不能，最終自願放棄自己的不朽，代替普羅米修斯承受懲罰，才得以解脫。',
    fullStory:[
      '凱隆與其他半人馬族不同，並非由伊克西翁與雲朵所生的粗野後代，而是泰坦神克洛諾斯與海洋仙女菲呂拉所生——這個特殊的出身，讓他自幼便展現出遠超一般半人馬的智慧與教養。他精通醫術、音樂、弓箭與預言，隱居於佩利翁山的洞穴中，先後教導過海克力斯、阿基里斯、伊阿宋等眾多日後名震希臘的英雄，是神話裡最受敬重的一位導師。',
      '一場意外中，凱隆被海克力斯射出、沾染九頭蛇劇毒的箭矢誤傷，儘管他身為神祇之子擁有不死之身，這股劇毒卻讓他終日承受著無法痊癒的劇痛，求生不得、求死也不能。恰逢普羅米修斯正被鎖在高加索山受苦，凱隆得知後，主動向宙斯請求，願意放棄自己的不朽之身，代替普羅米修斯承受懲罰，換取普羅米修斯的自由——宙斯應允了這場交換，凱隆因此得以解脫痛苦、安然辭世，也讓他「以有限換取他人自由」的犧牲，成為半人馬族裡最為人稱頌的一則故事。'
    ]},

  { id:'faunus', gen:'nature', zh:'法翁努斯', gr:'（源自羅馬）', roman:'Faunus', epithet:'羅馬的原生林野之神', isRoman:true,
    domain:'森林、預言、豐產（羅馬本土信仰）', symbol:'橡樹葉與羊角', parents:[],
    counterpart:'pan',
    astro:'目前沒有正式對應的天體命名。',
    story:'法翁努斯是羅馬人自己土生土長的森林與豐產之神，並非直接由希臘傳入，而是與希臘的潘各自獨立發展、性質相近的兩位「野性自然之神」——後來因形象太過相似，在羅馬文學中逐漸與潘融合、幾乎難以區分。',
    fullStory:[
      '法翁努斯與潘不同，他不是希臘神祇的翻版，而是義大利本土、拉丁民間信仰中原生的森林之神。羅馬傳說將他描述為古義大利傳說中一位早期國王的孫子——最早的拉丁姆國王薩圖爾努斯（即希臘的克洛諾斯流傳至義大利後的形象）之子皮庫斯的兒子，經過世代之後被神化，成為守護森林、田野與牧群的神祇，也被視為能透過夢境向人傳達預言的神秘存在。',
      '法翁努斯在羅馬鄉間的信仰中，與希臘的潘所扮演的角色極為相似：兩者都棲居荒野、守護牧人與家畜、並且同樣被認為能在寂靜的林間，突然喚起令人毛骨悚然的莫名恐懼感。也正因為這種高度的相似性，當希臘文化大量湧入羅馬之後，詩人與作家們很快便開始將法翁努斯與潘的形象交互使用，甚至直接互換——奧維德、維吉爾等羅馬詩人筆下，法翁努斯經常直接被描繪成人身羊足、頭生雙角的模樣，與希臘的潘幾乎無從分辨。',
      '因此，法翁努斯的故事，其實提供了一個理解「希臘神話如何變成羅馬神話」的絕佳範例：不是所有羅馬神祇都是希臘神祇的簡單翻譯（如宙斯之於朱庇特），有些像法翁努斯這樣，本就是義大利本土獨立發展出的信仰，只是恰好與某位希臘神祇性質相近，才在文化交流中逐漸融合為一。潘，因此始終是道地的希臘神祇；而法翁努斯，才是那位真正誕生於羅馬土壤之上的近親。'
    ]},

  // ---------- ZODIAC (myths written into the night sky) ----------
  { id:'aries', gen:'zodiac', zh:'白羊座', gr:'Aries', roman:'Aries', epithet:'黃道十二宮之首',
    domain:'黃道十二宮 · 春分', symbol:'金羊毛', parents:[], links:[],
    astro:'白羊座是黃道十二宮之首，卻是其中最暗淡的一個，最亮星哈馬爾（Hamal）目視星等僅約2等；由於地球歲差運動，如今真正的春分點早已偏移至鄰近的雙魚座範圍內。',
    story:'白羊座的原型，是那隻馱著弗里克索斯與赫勒兩兄妹逃離殺意繼母的會飛金色公羊。妹妹赫勒中途墜海身亡，弟弟弗里克索斯平安抵達科爾基斯後，將羊獻祭給宙斯，羊皮則化為傳說中的「金羊毛」。',
    fullStory:[
      '這隻金色公羊的故事，起於一場家庭悲劇：波俄提亞國王阿塔瑪斯的繼室因忌恨前妻所生的一對兒女弗里克索斯與赫勒，設計讓王國陷入假造的飢荒，並謊稱神諭指示必須獻祭這對兄妹才能挽救國家。就在祭壇前千鈞一髮之際，兩人的生母涅斐勒（正是後來生下半人馬一族的雲之仙女）派來一隻擁有金色羊毛、能夠飛翔的公羊，將兄妹倆救起，馱著他們飛越大海逃亡。',
      '飛行途中，妹妹赫勒不慎鬆手墜入下方的海峽溺斃，這片海峽後來被稱為「赫勒斯滂」（即今日的達達尼爾海峽），以紀念她的墜落。弟弟弗里克索斯則平安抵達黑海東岸的科爾基斯王國，受到當地國王埃厄忒斯的收留，並將他的女兒許配給了弗里克索斯。',
      '為了感謝宙斯的搭救，弗里克索斯將這隻公羊獻祭給眾神之王，並將牠珍貴的金色羊皮贈予岳父埃厄忒斯，後者將羊皮懸掛在一片聖林之中，交由一頭永不闔眼的巨龍看守。這張羊皮，便是日後傑森率領阿爾戈號英雄們遠征奪取的「金羊毛」，而那隻犧牲自己、救下兩個孩子的公羊，則被宙斯升上夜空，成為白羊座，永遠紀念牠的忠誠與犧牲。'
    ]},

  { id:'taurus', gen:'zodiac', zh:'金牛座', gr:'Taurus', roman:'Taurus', epithet:'化身公牛的宙斯',
    domain:'黃道十二宮 · 誘拐與航渡', symbol:'公牛', parents:[], links:['zeus'],
    astro:'金牛座擁有兩個肉眼可見的著名疏散星團——昴宿星團（M45，七姊妹星團）與畢宿星團，是全天最容易以肉眼辨認的星座之一。',
    story:'宙斯為了接近腓尼基公主歐羅巴，化身為一頭毛色雪白、性情溫馴的公牛混入牛群，誘使歐羅巴爬上牛背後突然躍入大海，一路游泳將她載至克里特島，兩人在此結合，「歐洲」（Europe）一名便源自她的名字。',
    fullStory:[
      '腓尼基公主歐羅巴某日在海邊與侍女嬉戲時，發現牛群之中混入了一頭毛色純白、雙角如新月般彎曲的俊美公牛。這頭公牛性情異常溫馴，甚至主動跪臥在她腳邊，任由她撫摸、為牠戴上花環。好奇又毫無戒心的歐羅巴，最終被牠吸引，坐上了牛背。',
      '就在此刻，公牛忽然起身狂奔，衝入海中，載著驚慌失措的歐羅巴一路游過整片地中海，直抵克里特島岸邊。此時公牛才恢復宙斯的真身，向她表明身分，並在一株梧桐樹下與她結合。歐羅巴後來為宙斯生下了三個兒子，其中之一米諾斯，日後成為克里特島著名的國王——正是他，向雅典徵收童男童女獻祭給牛頭怪彌諾陶洛斯，間接催生了忒修斯的傳奇。',
      '為了紀念這場橫渡海洋的誘拐，也為了紀念自己化身成的這頭公牛，宙斯將牛的形象升上夜空，成為金牛座。而歐羅巴的名字，後世則被用來稱呼她被帶往的那整片大陸——「歐洲」（Europe），使這則神話成為地理命名中一次格外深遠的迴響。'
    ]},

  { id:'gemini', gen:'zodiac', zh:'雙子座', gr:'Gemini', roman:'Gemini', epithet:'情同手足的孿生兄弟',
    domain:'黃道十二宮 · 手足之情', symbol:'孿生兄弟', parents:[], links:['zeus'],
    astro:'雙子座最明亮的兩顆星，正好分別命名為卡斯托爾（北河二）與波魯克斯（北河三），彷彿天上真正的孿生兄弟；每年12月固定出現的雙子座流星雨，輻射點便位於此。',
    story:'卡斯托爾與波魯克斯是斯巴達王后麗達所生的孿生兄弟，卻擁有截然不同的血統——一位是凡人之子，另一位則是宙斯所生的半神。當凡人的卡斯托爾戰死，波魯克斯懇求與兄長分享自己的不朽，宙斯感念這份情誼，將兩人一同升上星空。',
    fullStory:[
      '傳說宙斯曾化身天鵝與斯巴達王后麗達相會，麗達同一夜也與丈夫廷達瑞俄斯同房，之後誕下兩對孿生子女：其中卡斯托爾與克呂泰涅斯特拉被視為凡人丈夫之子，而波魯克斯與海倫（後來引發特洛伊戰爭的那位）則被視為宙斯的半神子女——因此，看似形影不離的卡斯托爾與波魯克斯，其實一位終將老死，另一位卻擁有不朽之身。',
      '兩兄弟自幼形影不離，一同參與了卡呂冬狩獵、阿爾戈號遠征等多場著名的英雄冒險，以驍勇善戰、情誼深厚聞名於世。然而，在一場與表兄弟間的牛群紛爭中，凡人之軀的卡斯托爾身受重傷，即將氣絕身亡。波魯克斯眼見兄長將死，自己卻因不朽之身無法陪他一同離去，悲痛之下向父親宙斯苦苦哀求，願意放棄部分永生，只求能與兄長永不分離。',
      '宙斯被這份手足之情深深打動，提出了一個折衷的安排：讓兩兄弟輪流分享波魯克斯的不朽——一人在人間存活的同時，另一人便留在冥界，兩人如此日復一日輪替，永不真正分離。最終，宙斯將這份情誼的象徵升上夜空，讓兩兄弟並肩化為雙子座，永遠肩並肩地閃耀在同一片星域之中。'
    ]},

  { id:'cancer', gen:'zodiac', zh:'巨蟹座', gr:'Cancer', roman:'Cancer', epithet:'赫拉派出的螃蟹',
    domain:'黃道十二宮 · 忠誠的犧牲', symbol:'螃蟹', parents:[], links:['heracles','hera'],
    astro:'巨蟹座是黃道十二宮中最暗淡的一個星座，肉眼幾乎難以辨認完整輪廓，中央卻藏有一個肉眼可見的疏散星團「鬼宿星團」（M44，蜂巢星團）。',
    story:'海克力斯與九頭蛇許德拉纏鬥之時，赫拉派出一隻巨蟹前去夾咬他的腳跟意圖干擾，卻輕易被他一腳踩碎。赫拉感念這隻螃蟹對自己的忠誠，仍將牠的形象升上星空，成為巨蟹座。',
    fullStory:[
      '這是海克力斯十二項任務中的第二項：剷除盤據勒拿沼澤、每砍下一顆頭便會再生兩顆的九頭巨蛇許德拉。始終伺機報復海克力斯的赫拉，在他與怪物纏鬥得難分難解之際，暗中派出一隻巨大的螃蟹，命牠悄悄爬近，狠狠夾住海克力斯的腳踝，企圖打亂他的陣腳，助許德拉一臂之力。',
      '然而對神力驚人的海克力斯而言，這隻螃蟹的攻擊幾乎不痛不癢——他甚至沒有分心多看一眼，隨手一腳便將牠踩得粉碎，隨即繼續專心對付九頭蛇，最終在姪子伊奧勞斯的協助下，以火燒斷頸的方式，阻止了頭顱的再生，成功剷除了這頭怪物。',
      '儘管這隻螃蟹的犧牲近乎徒勞，甚至有些滑稽，赫拉卻對牠這份不計後果、忠誠追隨自己意志的精神深受感動，仍舊將牠的形象高高升上夜空，成為巨蟹座——這也讓巨蟹座成為黃道十二宮中，少數並非因「偉大功績」、而是因「純粹忠心」而獲得一席之地的特殊星座。'
    ]},

  { id:'leo', gen:'zodiac', zh:'獅子座', gr:'Leo', roman:'Leo', epithet:'刀槍不入的涅墨亞獅子',
    domain:'黃道十二宮 · 力量與征服', symbol:'獅子', parents:[], links:['heracles'],
    astro:'獅子座是少數星形輪廓與其名稱神似的星座之一，鐮刀狀的頭部清晰可辨，最亮星軒轅十四（Regulus）意為「小小的王」，恰好幾乎緊貼著黃道本身。',
    story:'涅墨亞獅子擁有刀槍不入的堅硬毛皮，是海克力斯十二項任務中的第一項考驗。他發現武器對牠毫無作用，最終徒手將牠扼死，並剝下獅皮製成終身穿戴的戰袍，這頭獅子的形象也因此升上夜空。',
    fullStory:[
      '涅墨亞獅子盤據在伯羅奔尼撒半島的涅墨亞山谷，长期獵食當地居民與牲畜，令人聞風喪膽。牠最令人恐懼之處，在於那身刀槍不入的金色毛皮——無論是青銅的劍刃、還是海克力斯自己引以為傲的弓箭，全都無法穿透這身皮毛，紛紛應聲彈開。',
      '海克力斯很快意識到，尋常的武器對這頭猛獸毫無用處。他索性放下弓箭與長劍，徒手追蹤獅子進入牠棲身的雙口洞穴，堵住其中一個出口，逼牠只能從另一端與自己正面交鋒。在洞穴之中，海克力斯以雙臂緊緊扼住獅子的咽喉，憑藉驚人的怪力，硬是將牠活活勒斃。',
      '獅子死後，海克力斯試圖剝下牠那身堅韌的毛皮作為戰利品，卻發現凡間刀刃依舊束手無策——最終他急中生智，利用獅子自己銳利的爪子，才成功劃開了牠自身的毛皮。這張獅皮從此成為海克力斯終身的戰袍與頭盔，也是他最鮮明的標誌性形象。宙斯則將這頭猛獸的形象升上星空，成為獅子座，永遠紀念兒子這第一項、也是最具代表性的一場勝利。'
    ]},

  { id:'virgo', gen:'zodiac', zh:'處女座', gr:'Virgo', roman:'Virgo', epithet:'最後離開人間的女神',
    domain:'黃道十二宮 · 正義與豐饒', symbol:'手持麥穗的少女', parents:[], links:['demeter'],
    astro:'室女座（處女座）是全天面積第二大的星座，最亮星角宿一（Spica，意為「麥穗」）恰好呼應了這個星座與豐收、農業之間的悠久連結。',
    story:'處女座最常與正義女神阿斯特莱亞的形象連結——傳說黃金時代結束、人心逐漸敗壞之後，眾神紛紛離開人間，阿斯特莱亞是最後一位仍留下、試圖以正義感化世人的女神，最終心灰意冷升天，化為手持天秤與麥穗的處女座。',
    fullStory:[
      '在希臘人的神話想像中，世界歷經了黃金、白銀、青銅等每況愈下的時代，人類的品行也隨之逐漸墮落——從最初與神明比鄰而居的純真，逐漸走向猜忌、暴力與不義。正義女神阿斯特莱亞（其名意為「星辰女神」）原本與人類親密共處，親自教導世人是非對錯的道理。',
      '然而隨著青銅時代的到來，戰爭與貪婪日益氾濫，其他神祇一位接一位失望地退回奧林帕斯山，不再涉足人間事務。阿斯特莱亞卻始終不願放棄，獨自留在人間，苦口婆心地遊走於各個城邦之間，試圖以說理與勸誡，挽回世人逐漸沉淪的心。',
      '直到人類的惡行終於突破了她所能忍受的極限，阿斯特莱亞才終於心灰意冷，成為最後一位離開人間、返回天界的神祇。她升上夜空時，手中依舊持著象徵公正裁決的天秤——這副天秤後來獨立化為緊鄰的天秤座，而她本人的身影，則化為手持麥穗、象徵豐饒與純潔的處女座，靜靜俯瞰著她曾經深愛、卻終究無法挽回的人間世界。'
    ]},

  { id:'libra', gen:'zodiac', zh:'天秤座', gr:'Libra', roman:'Libra', epithet:'正義女神的天秤',
    domain:'黃道十二宮 · 公正與衡量', symbol:'天秤', parents:[], links:['themis'],
    astro:'天秤座是黃道十二宮中唯一以「物品」而非人物或動物命名的星座；牠的兩顆主星名稱直譯正是「南爪」與「北爪」，因為在更早的巴比倫與希臘傳統中，這片星域原本被視為緊鄰天蠍座、由牠伸出的一對蟹螯。',
    story:'天秤座象徵著正義女神手中用以衡量善惡、裁決是非的天秤，在不同傳統中，這副天秤時而歸屬於正義女神阿斯特莱亞，時而歸屬於掌管神聖秩序與律法的泰坦女神忒彌斯，兩者都與「公正裁決」的核心意象緊密相連。',
    fullStory:[
      '天秤座是黃道十二宮中相當特殊的一個存在：牠不是人物，也不是動物，而是一件器物——一副用來秤量的天秤。這樣的設計本身，便直接呼應了希臘人對「正義」最直觀的想像：如同商賈秤量貨物一般精準、公正，不偏袒任何一方。',
      '這副天秤最常與正義女神阿斯特莱亞連結在一起，被視為她隨身攜帶、用以衡量人間善惡的重要法器；然而在更古老的傳統中，掌管神聖律法與秩序的泰坦女神忒彌斯，同樣以手持天秤的形象聞名——她是宙斯早期最重要的顧問之一，也曾主掌德爾菲神諭所，象徵著比人間法律更為古老、根植於宇宙秩序本身的正義。',
      '有趣的是，考古與天文史料顯示，天秤座在更早的巴比倫與希臘傳統中，其實原本被視為鄰近天蠍座向外伸展的一對巨大蟹螯，直到羅馬時代才逐漸被獨立劃分出來，正式定名為天秤座——象徵著人類文明終於將「公正裁決」這個抽象的概念，鄭重地標記進了自己的星空版圖之中。'
    ]},

  { id:'scorpio', gen:'zodiac', zh:'天蠍座', gr:'Scorpio', roman:'Scorpius', epithet:'刺死獵人俄里翁的毒蠍',
    domain:'黃道十二宮 · 復仇與制衡', symbol:'蠍子', parents:[], links:[],
    astro:'天蠍座的心臟位置，是一顆呈現血紅色的超巨星「心宿二」（Antares），其名稱本意為「火星的對手」，因其顏色與亮度常被拿來與火星相提並論；天蠍座與獵戶座在天球上恰好位於相對的兩端，永遠不會同時升起。',
    story:'狩獵好手俄里翁自誇能獵殺世間所有野獸，觸怒了蓋亞或阿蒂蜜絲，她們派出一隻毒蠍將他螫死。宙斯將蠍子與俄里翁分別升上夜空，並刻意安排在天球兩端，使兩者永不同時出現，彷彿獵人至今仍在躲避那隻蠍子的追殺。',
    fullStory:[
      '俄里翁是希臘神話中著名的巨人狩獵好手，力大無窮、箭法精湛，甚至一度誇下海口，聲稱自己能夠獵盡世間所有的野獸。這番狂妄的言論，依照不同的版本，觸怒了大地女神蓋亞（她視所有野獸為自己的孩子），或是同樣以狩獵為傲、心高氣傲的月神阿蒂蜜絲。',
      '為了懲戒這份傲慢，一隻毒蠍被悄悄派往俄里翁所在之處。儘管俄里翁擅長狩獵大型猛獸，面對這隻毫不起眼、卻攜帶致命毒液的小小蠍子，卻毫無防備，最終被牠狠狠螫中要害，當場毒發身亡——一代狩獵英雄，竟死於一隻最不起眼的生物之手，成為希臘神話中對「驕兵必敗」最鮮明的警示。',
      '宙斯憐惜俄里翁生前的驍勇，仍將他的身影升上夜空，成為壯觀的獵戶座；然而，為了避免這位獵人與那隻曾經致他於死地的蠍子再度相遇，宙斯特意將天蠍座安排在天球的另一端——當天蠍座從東方升起時，獵戶座便已從西方落下，兩者永遠此消彼長、無法同時現身於夜空之中，彷彿這場追逐與恐懼，至今仍在星空裡無聲地延續著。',
      '值得一提的是，若嚴格依照現代天文學重新劃定的星座邊界計算，太陽穿越天蠍座的時間其實極短，短短數日便已離開——這個容易被忽略的細節，長久以來讓少數留意黃道帶精確邊界的人暗自懷疑：傳統占星術沿用至今的十二宮，或許並不是黃道帶上真正的全貌。'
    ]},

  { id:'sagittarius', gen:'zodiac', zh:'射手座', gr:'Sagittarius', roman:'Sagittarius', epithet:'銀河中心的半人馬弓箭手',
    domain:'黃道十二宮 · 狩獵與歡宴', symbol:'弓箭與人馬', parents:[], links:['satyrs'],
    astro:'人馬座（射手座）的方向，正指向銀河系的中心；銀河系中央那個超大質量黑洞「人馬座A*」，便是以此星座命名，是天文學上極為重要的參考方位。',
    story:'射手座常被描繪成一位半人半馬、正拉弓瞄準的形象，多數傳統認為牠代表的並非智者凱隆，而是酒神身邊一位擅長射箭、名為克洛托斯的薩堤爾——他因發明箭矢狩獵的技巧，深受繆思女神喜愛，死後升上星空。',
    fullStory:[
      '射手座的圖像雖然常被直覺聯想到智慧的半人馬凱隆，然而在多數古代天文與神話傳統中，這個星座真正對應的角色，其實是另一位半人半馬、卻性情截然不同的存在——克洛托斯。他被認為是薩堤爾之父潘或西勒諾斯的後代，本身也是薩堤爾一族的一員，居住在阿卡迪亞的山林之中。',
      '與其他終日縱情酒宴、嬉鬧玩樂的薩堤爾稍有不同，克洛托斯尤其擅長狩獵與騎射，據說是他率先發明了以箭矢進行狩獵的技藝。他同時也深受繆思九女神的喜愛，時常與她們作伴同遊，甚至被視為熱烈鼓掌喝采這個習俗的發明者——每當繆思們演奏或吟唱完畢，克洛托斯總會率先熱情鼓掌喝彩。',
      '克洛托斯死後，繆思女神們感念他生前對藝術的熱愛與支持，向宙斯請求將他的形象升上星空以為紀念。宙斯應允，並特意為他添上一副弓箭，讓他化為半人半馬、正引弓待發的射手座——恰好也讓這位喜好狂歡的薩堤爾後裔，與智者凱隆所在的半人馬族群，在星空與神話之間，留下了一段耐人尋味的交會。'
    ]},

  { id:'capricorn', gen:'zodiac', zh:'摩羯座', gr:'Capricorn', roman:'Capricornus', epithet:'倉皇跳水的潘',
    domain:'黃道十二宮 · 倉皇與應變', symbol:'羊首魚尾', parents:[], links:['pan'],
    astro:'摩羯座是黃道十二宮中面積第三小、也是如今全天最暗淡的星座之一；然而地球「南迴歸線」（Tropic of Capricorn）之名，卻正源自古代冬至太陽曾一度運行至此星座範圍內的緣故。',
    story:'當巨怪堤豐突襲奧林帕斯，眾神紛紛化身動物倉皇逃竄，牧神潘急欲跳入尼羅河躲避，卻在變身途中受到驚嚇而變身不全——潛入水中的下半身化為魚尾，來不及沒入水面的上半身則仍是山羊模樣，從此定格為「羊首魚尾」的奇特形象。',
    fullStory:[
      '這場驚慌，起於蓋亞為了替被囚禁在塔爾塔羅斯的泰坦子孫復仇，孕育出的最可怕的怪物——堤豐。牠體型龐大到頭頂能觸及星辰，全身盤繞著無數噴火毒蛇，聲勢駭人，一度嚇得眾神紛紛化身為各種動物、四散奔逃至埃及避難，就連宙斯本人一開始也未能倖免。',
      '牧神潘同樣身處這場混亂之中。相傳他正在尼羅河畔悠閒地吹奏排簫，堤豐的可怕吼聲驟然逼近，令他大驚失色，情急之下想要立刻跳入河中變身為魚、藏身水底逃生。然而由於過度驚慌，這次的變身並不徹底——潛入水面以下的下半身順利化為魚尾，來不及沒入水中的上半身，卻依舊維持著山羊的模樣，最終定格成一副「羊首魚尾」的奇特形貌，狼狽又滑稽。',
      '諷刺的是，「潘」正是「恐慌」（panic）這個詞彙的神話起源，而這一次，他自己竟也徹底陷入了同名的恐慌之中，倉皇失措、變身不全。後世的天文學家認為，這副半羊半魚、狼狽逃生的模樣，正是摩羯座造型的由來——一則將「神明也會恐慌失措」這樣充滿人性溫度的插曲，永遠定格在了夜空之中。'
    ]},

  { id:'aquarius', gen:'zodiac', zh:'水瓶座', gr:'Aquarius', roman:'Aquarius', epithet:'眾神的斟酒侍者',
    domain:'黃道十二宮 · 侍奉與永恆青春', symbol:'水瓶', parents:[], links:['zeus'],
    astro:'寶瓶座（水瓶座）是全天第十大星座，其中的行星狀星雲NGC 7293因外形酷似一隻凝視的眼睛，被暱稱為「上帝之眼」，是業餘天文攝影中極受歡迎的深空天體。',
    story:'甘尼米德是特洛伊王室中容貌俊美絕倫的少年王子，被化身為老鷹的宙斯看中，直接擄至奧林帕斯山，成為眾神專屬的斟酒侍者，並被賜予永恆的青春——他手持水瓶的形象，最終被升上夜空，成為水瓶座。',
    fullStory:[
      '甘尼米德是特洛伊城的一位年輕王子，據荷馬史詩記載，他是當時凡人之中容貌最為俊美的一位，甚至超越了絕大多數的凡人男子。他的美貌傳遍天界，最終引起了宙斯本人的注意——這樣的美，在宙斯眼中，已不僅僅屬於凡間，理應為神界所擁有。',
      '傳說宙斯化身為一隻巨大的老鷹（一說是派遣自己的聖鳥老鷹代勞），從正在弗里吉亞山間放牧羊群的甘尼米德身邊，將他直接攫走，帶回了奧林帕斯山。這場突如其來的擄劫，讓甘尼米德的父親特洛斯國王悲痛萬分，宙斯後來特地贈予他一群神駿的駿馬作為補償，稍稍平息了這場失去愛子的傷痛。',
      '甘尼米德抵達奧林帕斯後，被賜予永恆的青春，從此取代了原本擔任斟酒職務的青春女神赫柏，成為眾神宴會上專屬的司酒侍者，負責為眾神斟倒神聖的仙饌美酒——這是一項極為尊貴的職位，象徵著他已被正式接納為天界的一員。宙斯感念他為眾神帶來的美好，將他手持水瓶、正在傾倒甘露的姿態升上夜空，成為水瓶座，永遠銘記著這位凡間最美的少年。'
    ]},

  { id:'pisces', gen:'zodiac', zh:'雙魚座', gr:'Pisces', roman:'Pisces', epithet:'相繫而逃的愛神母子',
    domain:'黃道十二宮 · 護佑與牽絆', symbol:'以繩相繫的雙魚', parents:[], links:['aphrodite'],
    astro:'雙魚座如今是春分點實際所在的星座——由於地球歲差運動，春分點已從白羊座緩緩移動至此，也因此天文學上常以「雙魚座時代」來描述我們目前所處的這個天文分期。',
    story:'當巨怪堤豐突襲奧林帕斯，阿芙蘿黛蒂與兒子厄洛斯倉皇逃至幼發拉底河邊，情急之下雙雙躍入水中化身為魚，並用一條繩索繫住彼此的尾鰭，以免在慌亂之中失散——這雙相依相繫的魚，便是雙魚座的由來。',
    fullStory:[
      '這同樣是巨怪堤豐襲擊奧林帕斯那場混亂中發生的插曲。當眾神紛紛化身動物、倉皇逃往埃及避難之時，愛神阿芙蘿黛蒂正與年幼的兒子厄洛斯一同待在幼發拉底河畔，堤豐駭人的吼聲驟然逼近，讓母子二人陷入了前所未有的恐慌。',
      '在這電光火石的瞬間，阿芙蘿黛蒂顧不得思考太多，一把抱起厄洛斯，兩人一同縱身躍入河中，化身為兩尾魚以躲避怪物的追擊。然而，湍急的水流隨時可能將母子二人沖散——身為愛與牽絆的化身，阿芙蘿黛蒂於是急中生智，取來一條絲繩，將自己與兒子的尾鰭牢牢繫在一起，確保無論水流如何翻湧，兩人都不會在慌亂中失去彼此。',
      '母子二人最終憑藉這份緊緊相繫的牽絆，安然躲過了堤豐的追擊。後世的天文學家認為，這兩尾以繩相連、彼此依偎的魚，正是雙魚座造型的由來——比起其他象徵英勇戰績或神聖裁決的星座，雙魚座所紀念的，反而是一段最樸素、卻也最深刻的親情：在巨大的恐懼面前，緊緊抓住自己所愛之人，不讓彼此走散。'
    ]},

  // ---------- TROJAN WAR & ODYSSEY ----------
  { id:'helen', gen:'troy', zh:'海倫', gr:'Helen', roman:'同名 Helena', epithet:'引發戰爭的絕世美人', parents:['zeus'],
    astro:'小行星 101 Helena 便以她為名，是十九世紀發現的一顆主帶小行星。',
    story:'海倫是宙斯化為天鵝與斯巴達王后麗達所生之女，是當世公認最美的女子。她原是斯巴達王后，被特洛伊王子帕里斯帶走（一說誘拐、一說私奔），直接引爆了長達十年的特洛伊戰爭。',
    fullStory:[
      '海倫的美貌自幼便聞名希臘各地，成年後向她求婚的王公貴族多達數十位，她的凡人繼父為了避免落選者尋仇，要求所有求婚者立下誓言：無論誰最終娶得海倫，其餘人都必須在她受到侵害時挺身相助。海倫最終嫁給了斯巴達國王墨涅拉俄斯，這則誓言在多年後，正是希臘各城邦聯合出兵特洛伊的法理依據。',
      '當特洛伊王子帕里斯依照阿芙蘿黛蒂的許諾來到斯巴達、帶走海倫之後，墨涅拉俄斯依約召集當年立誓的眾王公——包括阿伽門農、阿基里斯、奧德修斯——組成聯軍遠征特洛伊。海倫本人在戰爭中的角色始終曖昧，荷馬筆下的她時而懊悔自責，時而被描述成身不由己，她的美貌從此成為希臘文學裡「毀滅性之美」最經典的象徵。'
    ]},

  { id:'paris', gen:'troy', zh:'帕里斯', gr:'Paris', roman:'同名 Paris', epithet:'金蘋果的裁判者', parents:['priam'], links:['aphrodite'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'帕里斯是特洛伊王子，被赫拉、雅典娜、阿芙蘿黛蒂三位女神要求裁定誰最美，他選擇了許諾贈他絕世美人的阿芙蘿黛蒂，因而得到海倫，卻也直接點燃了特洛伊戰爭的導火線。',
    fullStory:[
      '帕里斯出生前，母親曾夢見自己誕下一支即將燒毀全城的火把，先知解讀為凶兆，國王普里阿摩斯因此下令將剛出生的帕里斯棄於荒山。他奇蹟般存活下來，由牧羊人撫養長大，渾然不知自己的王室身分，直到成年後才被家族尋回。',
      '婚宴上，不和女神厄里斯因未受邀而心生怨懟，拋出一顆刻著「獻給最美者」的金蘋果，赫拉、雅典娜、阿芙蘿黛蒂三位女神當場爭執不下，宙斯將這個燙手的裁決權推給了凡人帕里斯。三位女神各自向他開出條件：赫拉許以統治全亞細亞的權力，雅典娜許以戰無不勝的智慧，阿芙蘿黛蒂則許諾將世間最美的女子賜予他。帕里斯選擇了阿芙蘿黛蒂，這個決定不僅為他贏得海倫，也讓赫拉與雅典娜自此對特洛伊懷恨在心，在後來的戰爭中始終站在希臘聯軍一方。'
    ]},

  { id:'priam', gen:'troy', zh:'普里阿摩斯', gr:'Priam', roman:'同名 Priamus', epithet:'特洛伊的末代國王',
    domain:'王權、晚年的悲劇、為人父的哀慟', symbol:'王冠與深夜的懇求', parents:[], links:['hector','paris','cassandra'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'普里阿摩斯是特洛伊末代國王，在位期間見證了兒子帕里斯拐走海倫、引爆特洛伊戰爭，晚年又親眼目睹愛子赫克托爾死於阿基里斯之手、遺體遭受羞辱，最終親自深夜潛入敵營，含淚懇求阿基里斯歸還兒子遺體，這一幕成為《伊利亞德》裡最悲愴動人的場景之一。',
    fullStory:[
      '普里阿摩斯統治特洛伊長達數十年，膝下子女眾多，包括帕里斯、赫克托爾與擁有預言能力卻無人相信的卡珊德拉。當帕里斯不顧眾人反對、執意將海倫帶回特洛伊時，普里阿摩斯儘管憂心忡忡，終究還是選擇庇護自己的兒子，這個決定，最終將整座城邦拖入了長達十年的毀滅性戰爭之中。',
      '戰爭進入尾聲，普里阿摩斯最鍾愛的兒子赫克托爾在城牆外與阿基里斯決一死戰、壯烈犧牲，悲憤的阿基里斯甚至將赫克托爾的遺體綁在戰車後方，一連多日拖行示眾，拒絕歸還安葬。年邁的普里阿摩斯不顧個人安危，在諸神的協助下，深夜親自潛入希臘聯軍陣營，跪在殺子仇人阿基里斯面前，含淚懇求他看在自己也有年邁父親的份上，歸還兒子的遺體——這一幕跨越仇恨、直指人類共通哀慟的場景，被公認是《伊利亞德》全書裡最具人性光輝、也最悲愴動人的高潮。'
    ]},

  { id:'achilles', gen:'troy', zh:'阿基里斯', gr:'Achilles', roman:'同名 Achilles', epithet:'希臘第一勇士', parents:[], links:['hector','patroclus'],
    astro:'588 Achilles 是天文史上第一顆被發現的「木星特洛伊小行星」（1906年），如今這整類運行於木星軌道前後的小行星，都以特洛伊戰爭的英雄們命名，即是源自於他。',
    story:'阿基里斯是希臘聯軍最驍勇的戰士，母親忒堤斯曾將他浸入冥河欲使他刀槍不入，卻獨獨漏了握著他的腳踝，這個弱點最終要了他的命——「阿基里斯之踵」也因此成為「唯一致命弱點」的代名詞。',
    fullStory:[
      '阿基里斯是海洋女神忒堤斯與凡人英雄珀琉斯之子。忒堤斯不忍愛子終將一死，據後世傳說，她曾將幼年的阿基里斯倒提著浸入冥河斯堤克斯之水，河水賦予他幾乎刀槍不入的軀體，唯獨她緊握不放的那隻腳踝，始終未曾沾到河水，成了他全身唯一的破綻。',
      '特洛伊戰爭爆發後，阿基里斯率領麾下精銳部隊參戰，是聯軍中戰力最強的個體戰士，卻也因與主帥阿伽門農爭奪一名女俘而憤怒退出戰場，導致希臘聯軍節節敗退，這場「阿基里斯之怒」正是荷馬史詩《伊利亞德》的敘事主軸。他最終在摯友帕特羅克洛斯戰死後重返戰場，殺死特洛伊第一勇士赫克托爾為友復仇，自己也在戰爭尾聲，被帕里斯一箭射中那唯一致命的腳踝，就此殞命沙場。'
    ]},

  { id:'hector', gen:'troy', zh:'赫克托爾', gr:'Hector', roman:'同名 Hector', epithet:'特洛伊最偉大的守護者',
    domain:'家園的守護、責任、英雄式的犧牲', symbol:'頭盔與城牆', parents:['priam'], links:['achilles','paris'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'赫克托爾是特洛伊王子，全軍統帥，以英勇與責任感著稱，與弟弟帕里斯魯莽引發的戰爭形成鮮明對比——他深知特洛伊終將淪陷，卻仍舊選擇挺身而出，保衛城邦與家人，最終在城牆外與阿基里斯決一死戰，壯烈犧牲。',
    fullStory:[
      '赫克托爾是特洛伊國王普里阿摩斯的長子，特洛伊軍隊的統帥，在《伊利亞德》裡，被塑造成一位遠比弟弟帕里斯更加成熟、也更受敬重的英雄形象——帕里斯因一己私慾拐走海倫，引發了這場曠日持久的戰爭，赫克托爾卻始終清楚意識到，這場戰爭終將為特洛伊帶來滅頂之災，依然選擇肩負起保衛城邦與家人的責任，一次次披甲上陣。',
      '荷馬史詩裡最動人的一幕，正是赫克托爾在出征前，與妻子安卓瑪姬、幼子在城牆邊的訣別——他脫下嚇哭孩子的頭盔，溫柔地抱起兒子，向諸神祈求孩子將來能比自己更加英勇，成為特洛伊的驕傲。這場家庭場景，與戰場上的殺伐形成強烈對比，也讓赫克托爾成為荷馬史詩裡，最具人性溫度的一位英雄。他最終在城牆外與阿基里斯正面對決，為了替好友帕特羅克洛斯復仇而怒火中燒的阿基里斯，將他擊敗殺死，還一度將他的遺體綁在戰車後拖行示眾，直到普里阿摩斯親自深夜前往敵營，含淚懇求，才終於贖回兒子的遺體。'
    ]},

  { id:'patroclus', gen:'troy', zh:'帕特羅克洛斯', gr:'Patroclus', roman:'同名 Patroclus', epithet:'阿基里斯最深摯的同伴',
    domain:'友誼、犧牲、悲慟', symbol:'阿基里斯的盔甲', parents:[], links:['achilles','hector'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'帕特羅克洛斯是阿基里斯自幼相伴的摯友與同伴，在阿基里斯因與阿伽門農反目、憤而退出戰局後，穿上他的盔甲代替出戰，卻被赫克托爾識破身分、擊殺陣亡——這場死亡，成為阿基里斯重返戰場、為友復仇的最直接導火線。',
    fullStory:[
      '帕特羅克洛斯自幼便與阿基里斯情同手足，兩人一同在半人馬凱隆門下習武求學，情誼深厚，《伊利亞德》裡兩人之間的情感連結，究竟屬於摯友還是戀人，是後世學者長期爭論不休的議題——古典時代的希臘人多半將兩人視為戀人關係，這也是理解這段情誼強度的重要脈絡。',
      '當阿基里斯因戰利品分配問題與統帥阿伽門農爆發激烈衝突，憤而退出戰局、拒絕再為希臘聯軍出力時，希臘陣營在特洛伊軍隊的猛攻下節節敗退。帕特羅克洛斯不忍見希臘軍隊潰敗，說服阿基里斯讓自己穿上他那身著名的盔甲，代替出戰、震懾特洛伊軍隊。然而帕特羅克洛斯在戰場上得意忘形，一路追擊至特洛伊城牆下，最終被赫克托爾識破身分、當場擊殺。這場摯友之死，讓阿基里斯陷入巨大的悲慟與憤怒，一改先前置身事外的態度，重新披甲上陣，誓言為帕特羅克洛斯復仇——正是這股怒火，直接導致了赫克托爾最終的敗亡。'
    ]},

  { id:'agamemnon', gen:'troy', zh:'阿伽門農', gr:'Agamemnon', roman:'同名 Agamemnon', epithet:'希臘聯軍統帥', parents:[],
    astro:'小行星 911 Agamemnon 是1919年發現的一顆木星特洛伊小行星，以他為名。',
    story:'阿伽門農是邁錫尼國王、海倫姊夫墨涅拉俄斯的兄長，被推舉為希臘聯軍統帥。為求出征順風，他一度獻祭親生女兒伊菲革涅亞，這個決定也為他自己日後的悲劇埋下了伏筆。',
    fullStory:[
      '阿伽門農統領著整個希臘聯軍，是特洛伊戰爭中名義上地位最高的將領，卻也因與阿基里斯爭奪女俘、以及戰前為求順風而獻祭親生女兒伊菲革涅亞，讓自己在史詩敘事中始終背負著剛愎自用、犧牲他人成就自己的形象。',
      '戰爭結束、阿伽門農凱旋返回邁錫尼之後，等待他的卻不是英雄式的歡迎——他的妻子克呂泰涅斯特拉始終未曾原諒他當年獻祭女兒一事，趁他返鄉沐浴之際，與情夫合謀將他刺殺身亡。這場發生在家門之內的復仇悲劇，後來又牽動了他的兒子俄瑞斯忒斯為父報仇、弒母的連鎖血案，成為希臘悲劇裡最著名的「家族詛咒」敘事之一。'
    ]},

  { id:'odysseus', gen:'troy', zh:'奧德修斯', gr:'Odysseus', roman:'尤利西斯 Ulysses', epithet:'足智多謀的漂泊者', parents:[], links:['athena'],
    astro:'小行星 1143 Odysseus 是1930年發現的木星特洛伊小行星，以他為名；他的羅馬名「尤利西斯」也被NASA用於命名多項太空探測計畫。',
    story:'奧德修斯是伊薩卡國王，以機智聞名，特洛伊木馬計正是他的計謀。戰爭結束後，他歷經整整十年才輾轉返鄉，途中遭遇獨眼巨人、女巫喀耳刻、海妖塞壬等重重考驗，這段返鄉之旅便是荷馬史詩《奧德賽》的主線。',
    fullStory:[
      '奧德修斯以機智著稱，「足智多謀」是荷馬給他最常見的稱號。特洛伊戰爭進入第十年、雙方僵持不下之際，正是他獻計打造一匹巨大的木馬，讓希臘士兵藏身其中，佯裝撤退，誘使特洛伊人將木馬當作戰利品拖入城中——當夜，藏在馬腹中的士兵悄悄爬出，打開城門迎接大軍，終結了這場長達十年的戰爭。',
      '戰爭結束後，奧德修斯本該只需數週的航程返回家鄉伊薩卡，卻因觸怒海神波賽頓（他刺瞎了波賽頓之子獨眼巨人波呂斐摩斯），被迫在海上漂泊整整十年，途中遭遇了希臘神話中最著名的一連串考驗——女巫喀耳刻的巫術、海妖塞壬的死亡歌聲、海怪斯庫拉與大漩渦卡律布狄斯的夾擊、仙女卡呂普索的挽留。他始終憑藉智慧一一化解危機，最終在雅典娜的暗中協助下，隻身返回伊薩卡，剷除了纏著妻子佩涅羅佩不放的求婚者們，一家團圓。'
    ]},

  { id:'penelope', gen:'troy', zh:'佩涅羅佩', gr:'Penelope', roman:'同名 Penelope', epithet:'忠貞等待的王后', parents:[],
    astro:'小行星 201 Penelope 是1879年發現的一顆主帶小行星，以她為名。',
    story:'佩涅羅佩是奧德修斯之妻，在丈夫外出征戰、音訊全無長達二十年間，始終堅拒眾多求婚者，並以「白天織布、夜裡拆線」的計策拖延時間，成為忠貞與智謀並存的經典女性形象。',
    fullStory:[
      '奧德修斯出征特洛伊後遲遲未歸，伊薩卡王宮裡陸續湧入上百位覬覦王位與佩涅羅佩的求婚者，長年賴在宮中大肆揮霍，逼迫她盡快改嫁。佩涅羅佩以「必須先織完公公的壽衣才能改嫁」為由拖延時間，白天當著眾人面前織布，入夜後卻悄悄將白天織好的部分拆掉重來，如此周而復始整整三年，才被一名侍女洩密識破。',
      '這份長達二十年的堅忍與智謀，讓佩涅羅佩成為《奧德賽》裡與丈夫奧德修斯智慧相互輝映的角色——當奧德修斯終於喬裝返鄉，佩涅羅佩甚至謹慎地設下考驗確認他的真實身分，才願意相認。她的故事後來也成為西方文學中「忠貞等待」最經典的原型，「佩涅羅佩式的等待」至今仍是一個常見的文學典故。'
    ]},

  { id:'telemachus', gen:'troy', zh:'忒勒馬科斯', gr:'Telemachus', roman:'同名 Telemachus', epithet:'尋父的王子', parents:['odysseus','penelope'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'忒勒馬科斯是奧德修斯與佩涅羅佩之子，父親出征時他尚在襁褓，成年後在雅典娜的鼓勵下踏上尋父之旅，最終與返鄉的父親裡應外合，剷除了糾纏母親的求婚者們。',
    fullStory:[
      '忒勒馬科斯出生不久，父親奧德修斯便被徵召前往特洛伊，他幾乎是在父親缺席的狀態下獨自長大，眼看著家中被上百位求婚者佔據、母親被逼婚、家業被揮霍殆盡，自己卻年輕勢單，無力阻止。《奧德賽》開篇的前幾卷，其實正是以他的視角展開，講述他如何在雅典娜化身智者的鼓勵下，鼓起勇氣出海尋找父親的下落。',
      '忒勒馬科斯的旅程本身也是一則成長故事——他從一個被眾人輕視的少年，逐漸磨練成能夠獨當一面的青年。當他終於與喬裝返鄉的父親重逢相認，兩人聯手策劃、裡應外合，一舉剷除了盤據王宮多年的求婚者們，父子共同奪回家業的這場戲，也讓「尋父」與「父子並肩作戰」成為這則史詩裡另一條動人的主線。'
    ]},

  { id:'polyphemus', gen:'troy', zh:'波呂斐摩斯', gr:'Polyphemus', roman:'同名 Polyphemus', epithet:'被刺瞎的獨眼巨人', parents:['poseidon'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'波呂斐摩斯是海神波賽頓之子、獨眼巨人族的一員，奧德修斯一行人誤入他的洞穴，遭他囚禁並吞食同伴，奧德修斯用計將他灌醉並刺瞎其獨眼才得以逃脫——這也是波賽頓此後一路追殺奧德修斯的直接原因。',
    fullStory:[
      '奧德修斯一行人在返鄉途中誤闖獨眼巨人波呂斐摩斯棲身的洞穴，波呂斐摩斯將洞口以巨石封死，將他們囚禁其中，並一連生吞了數名船員充飢。奧德修斯急中生智，先以美酒將波呂斐摩斯灌醉，並謊稱自己名叫「無人」（Nobody），待他醉倒沉睡後，率領同伴以燒紅的木樁刺瞎了他唯一的獨眼。',
      '波呂斐摩斯痛苦地向鄰近的其他獨眼巨人求救，喊著「無人傷害了我」，鄰居們聽聞「無人」行凶，自然無人前來相助，奧德修斯藉此巧妙金蟬脫殼，帶著同伴綁在羊腹之下逃出洞穴。然而波呂斐摩斯在船隻離岸後認出了奧德修斯的真名，向父親波賽頓祈求降罪——這正是波賽頓此後十年間不斷在海上刁難、阻撓奧德修斯返鄉的直接起因。'
    ]},

  { id:'circe', gen:'troy', zh:'喀耳刻', gr:'Circe', roman:'同名 Circe', epithet:'能施法變形的女巫', parents:[],
    astro:'小行星 34 Circe 是1855年發現的一顆主帶小行星，以她為名。',
    story:'喀耳刻是精通魔法的女神，居住在艾尤島上，奧德修斯的船員登島後被她施法變成豬，奧德修斯在荷米斯贈予的解藥護持下逃過一劫，最終降服喀耳刻，在島上停留了整整一年。',
    fullStory:[
      '喀耳刻精通藥草與魔法，能將靠近她島嶼的旅人變成野獸。奧德修斯的船員一登島便中了她的法術，全數被變成豬隻，只有一人僥倖逃脫、跑回船上報信。奧德修斯隻身前往營救，途中幸遇荷米斯現身相助，贈予他一株名為「莫呂」的神奇藥草，使他得以免疫喀耳刻的法術。',
      '面對法術失效、依然從容不迫的奧德修斯，喀耳刻大為驚訝，兩人隨後不打不相識，她不僅將船員們變回人形，還盛情款待奧德修斯一行人，兩人更相戀同居長達一年之久。臨別之際，喀耳刻更指點奧德修斯必須先前往冥界請教先知忒瑞西阿斯，才能真正找到返鄉的路——她從危險的女巫，轉變為奧德修斯旅程裡意外重要的引路人。'
    ]},

  { id:'calypso', gen:'troy', zh:'卡呂普索', gr:'Calypso', roman:'同名 Calypso', epithet:'挽留旅人的海島仙女', parents:[],
    astro:'土星有一顆真實的衛星就叫「卡呂普索」，1980年被發現，與另一顆衛星忒堤斯共享同一軌道，如同神話中她島嶼上永恆停滯的時光。',
    story:'卡呂普索是居住在孤島上的海中仙女，奧德修斯船難漂流至此，被她挽留長達七年之久，甚至許諾賜予他永生，奧德修斯卻始終思鄉情切，最終在眾神介入下，才獲准離開返鄉。',
    fullStory:[
      '奧德修斯的船隊在經歷斯庫拉與卡律布狄斯的夾擊後幾乎全軍覆沒，他隻身漂流上岸，來到仙女卡呂普索所居住的孤島。卡呂普索對他一見傾心，將他留在島上，兩人共同生活了整整七年，她甚至向他許諾，若願意留下，便能賜予他永恆的青春與不死之身。',
      '然而奧德修斯終究無法忘懷家鄉與妻兒，終日坐在海邊遙望大海、暗自神傷。雅典娜為此多次向宙斯請命，最終宙斯派遣荷米斯傳令，命令卡呂普索放行。卡呂普索雖萬般不捨，仍依照神諭協助奧德修斯打造木筏，讓他得以繼續踏上返鄉的旅程——這則故事也常被視為「即便是永生與安逸，也比不過對家與根源的眷戀」的經典寓言。'
    ]},

  { id:'sirens', gen:'troy', zh:'塞壬', gr:'Seirenes', roman:'同名 Sirenae', epithet:'以歌聲致命的海妖', parents:[],
    astro:'目前沒有廣為人知的正式天體命名，但「塞壬」一詞後世被直接借用為警報器（siren）的英文名稱，取其「令人無法抗拒、必須高度警覺」的意象。',
    story:'塞壬是棲息於海上礁岩間的海妖，以無比動聽卻致命的歌聲引誘水手觸礁沉船。奧德修斯依照喀耳刻的指點，命船員以蠟封耳、自己則被綁在桅杆上，成為傳說中唯一聽過塞壬之歌卻倖存下來的凡人。',
    fullStory:[
      '塞壬棲息在一片遍布觸礁沉船殘骸的海域，她們的歌聲美妙到能讓任何聽見的水手，不由自主地操舵駛向礁岩，最終船毀人亡，屍骨堆積在她們棲身的島嶼四周。荷馬並未詳細描寫她們的外貌，但後世藝術傳統多將她們描繪成人首鳥身、或人首魚尾的形象。',
      '喀耳刻事先警告了奧德修斯此地的危險，並教他一個兩全其美的辦法：命令全體船員以蜂蠟封住雙耳，使他們聽不見歌聲；而奧德修斯自己則出於好奇，堅持要親耳聽聽這傳說中的歌聲，於是命人將自己牢牢綁在船桅上，並吩咐無論自己如何哀求掙扎，都不准鬆綁。船隻安然駛過塞壬棲息的海域，奧德修斯也因此成為傳說中唯一親耳聽過塞壬之歌、卻活著離開的凡人。'
    ]},

  { id:'scylla', gen:'troy', zh:'斯庫拉', gr:'Scylla', roman:'同名 Scylla', epithet:'礁岩上的六頭海怪', parents:[], links:['charybdis'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'斯庫拉是棲身於狹窄海峽一側礁岩洞穴中的六頭海怪，每個頭顱都能一口吞下一名水手；她與海峽另一側的大漩渦卡律布狄斯遙遙相對，逼得過往船隻必須在兩害之間抉擇，「進退維谷」的意象即源於此。',
    fullStory:[
      '斯庫拉原是一位美麗的海中仙女，因遭到嫉妒的女巫施法（部分傳說認為正是喀耳刻，因妒忌她的美貌），被永久變成了下半身環繞六隻犬首的恐怖海怪，永遠困在海峽一側的礁岩洞穴之中，無法再變回原形。每當船隻經過，她會同時伸出六個頭顱，各自叼走一名水手吞食。',
      '奧德修斯事先得到喀耳刻的警告：海峽的另一側棲息著會吞吐海水、形成致命大漩渦的卡律布狄斯，若試圖完全避開斯庫拉、貼著另一側航行，整艘船都可能被卷入漩渦、無一倖免；相較之下，緊貼斯庫拉一側航行，雖然必然會犧牲幾名船員，卻能保全整艘船的其餘人。奧德修斯忍痛選擇了後者，親眼目睹六名同伴被斯庫拉生吞，這也成為《奧德賽》裡最殘酷、也最無可奈何的一場抉擇。'
    ]},

  { id:'charybdis', gen:'troy', zh:'卡律布狄斯', gr:'Charybdis', roman:'同名 Charybdis', epithet:'吞吐海水的巨大漩渦', parents:['poseidon'],
    astro:'目前沒有廣為人知的正式天體命名，但「在斯庫拉與卡律布狄斯之間」（between Scylla and Charybdis）至今仍是英語中形容「進退兩難」的常見慣用語。',
    story:'卡律布狄斯是波賽頓之女，因觸怒宙斯而被打入海峽之中，化為一個每日三次大口吞吐海水、形成致命漩渦的怪物，與海峽對岸的斯庫拉遙相呼應，共同構成水手們最恐懼的一道關卡。',
    fullStory:[
      '卡律布狄斯原是波賽頓之女，傳說她曾協助父親與宙斯爭奪領地，一度大肆吞噬陸地以擴張海洋的疆域，觸怒了宙斯，被降罪打入海峽之中，化為一個永遠困守原地的巨大漩渦——她每日三次大口吞入海水、又三次猛烈噴吐而出，形成足以將整艘船隻捲入海底的致命漩渦。',
      '她所盤據的海峽恰好與斯庫拉的礁岩洞穴遙遙相對，寬度窄到船隻幾乎不可能同時避開兩者。奧德修斯的船隊在別無選擇之下，選擇冒險貼近斯庫拉一側通過，犧牲了六名同伴，卻也因此保住了整艘船不被卡律布狄斯的漩渦徹底吞沒。這道兩難的海峽，後世也成為英語中「between Scylla and Charybdis」（在斯庫拉與卡律布狄斯之間）這句成語的直接出處，用來形容必須在兩種同樣兇險的選擇之間做出抉擇的處境。'
    ]},

  // ---------- PHILOSOPHERS & CLASSICAL WORKS ----------
  { id:'thales', gen:'philosophy', zh:'泰勒斯', gr:'Thales', roman:'—', epithet:'哲學之父',
    year:-624, yearLabel:'約西元前624年',
    domain:'自然哲學、天文、幾何', symbol:'水與星盤', parents:[], links:[],
    astro:'泰勒斯最著名的事蹟之一，是準確預言了西元前585年的一次日食——這場日食甚至讓交戰中的呂底亞與米底軍隊當場停戰議和，是西方天文史上最早有記載的日食預測。',
    story:'泰勒斯是古希臘公認第一位哲學家，主張水是萬物的本源，開創了以自然原因（而非神話）解釋世界的思考方式，被視為西方哲學與科學的共同起點。',
    fullStory:[
      '泰勒斯生活於米利都，是愛奧尼亞學派的創始者。在他之前，希臘人普遍以神話——諸神的意志與爭鬥——來解釋世界的起源與自然現象；泰勒斯卻主張，萬物的根本原因可以用自然本身去尋找。他提出「水」是萬物的本源，一切存在都由水生成、也終將復歸於水，這個答案本身或許顯得樸素，但「向自然提問、而非向神明求答案」的態度，才是他真正劃時代的貢獻。',
      '泰勒斯同時也是傑出的天文學家與幾何學家，傳說他曾準確預言了一次日食的發生，這場日食甚至讓正在交戰的呂底亞與米底兩國，因目睹天象突變而心生敬畏，當場停戰議和。也因為這樣的成就，後世將他尊為「希臘七賢」之首，也是西方哲學史公認的起點人物。',
      '值得老實說一句：泰勒斯這個「水生萬物」的具體答案，用現代科學眼光來看當然是錯的——水並非構成萬物的基本元素。他真正留給後世的遺產，其實不是任何一個正確答案，而是那個「應該去自然本身尋找原因、而非訴諸神明」的提問方式。記住這點，或許比記住他的答案本身更重要。'
    ]},

  { id:'pythagoras', gen:'philosophy', zh:'畢達哥拉斯', gr:'Pythagoras', roman:'—', epithet:'數與和諧的追尋者',
    year:-570, yearLabel:'約西元前570年',
    domain:'數學、音樂、靈魂學說', symbol:'直角三角形與七弦琴', parents:[], links:[],
    astro:'畢達哥拉斯發現弦長比例與音程之間的數學關係，後世稱為「畢氏音律」，他更進一步主張天體運行同樣遵循和諧的數學比例，這個「天體音樂」（musica universalis）的構想，深深影響了後世數百年的天文學思考。',
    story:'畢達哥拉斯相信萬物的本質是「數」，並發現弦長比例決定音程和諧與否，由此推論宇宙運行同樣遵循數學和諧的法則。他創立的學派亦信奉靈魂轉世，將哲學、數學與宗教修行融為一體。',
    fullStory:[
      '畢達哥拉斯出生於薩摩斯島，成年後在南義大利的克羅頓建立了一個兼具哲學學派、宗教團體與數學研究會性質的社群。他最著名的數學貢獻，是以他為名的「畢氏定理」（直角三角形兩股平方和等於斜邊平方），但對他自己而言，數學從來不只是計算工具，而是通往宇宙真理的鑰匙——他相信「萬物皆數」，一切現象背後都存在著可以用數字比例描述的和諧秩序。',
      '這個信念最迷人的延伸，發生在音樂與天文的交會處：畢達哥拉斯發現，將琴弦按簡單整數比例（如二比一、三比二）截斷，會產生悅耳和諧的音程，這個發現被後世稱為「畢氏音律」。他進一步推論，天空中的日月星辰在各自軌道上運行時，同樣會依循和諧的數學比例，發出人耳無法聽見、卻真實存在的「天體音樂」——這個浪漫的構想，深深影響了往後兩千年間，人們想像宇宙秩序的方式。',
      '不過也該老實說：畢達哥拉斯學派更像是一個帶有宗教色彩的祕密教團，而非現代意義下的學術機構——例如他們嚴格禁止吃豆子、相信靈魂轉世，這些主張顯然缺乏任何理性論證基礎。甚至連舉世聞名的「畢氏定理」，是否真是他本人所證明，學界至今都存疑，很可能是後代弟子的集體研究成果，被歸功於創始人一人之名。'
    ]},

  { id:'socrates', gen:'philosophy', zh:'蘇格拉底', gr:'Socrates', roman:'—', epithet:'雅典的牛虻',
    year:-470, yearLabel:'西元前470年',
    domain:'倫理學、詰問法', symbol:'毒堇之杯', parents:[], links:['athena'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'蘇格拉底終生未曾留下任何著作，卻透過在雅典街頭不斷詰問世人「你真的知道自己在說什麼嗎」，開創了西方哲學最重要的方法論之一。晚年被控腐蝕青年、不敬城邦諸神，最終被判飲鴆而死。',
    fullStory:[
      '蘇格拉底一生不曾寫下隻字片語，我們今日對他思想的理解，幾乎全部來自學生柏拉圖與其他人的記述。他自稱是雅典城邦的「牛虻」——如同牛虻叮咬遲鈍的馬匹使其保持警醒，他透過不斷向雅典公民提出尖銳的詰問（後世稱為「蘇格拉底詰問法」），逼迫人們正視自己引以為傲的知識其實充滿矛盾與空洞。他最著名的宣稱，正是「我唯一知道的，就是我一無所知」。',
      '這種毫不留情的詰問，讓蘇格拉底得罪了不少雅典的權貴與政治人物，最終在西元前399年，他被控「腐蝕青年心智」與「不敬城邦所信奉的諸神」，交付陪審團審判。面對指控，蘇格拉底不僅拒絕認罪求饒，反而在法庭上為自己的哲學生涯慷慨辯護，這場審判經柏拉圖記錄成《申辯篇》流傳至今。最終他被判處死刑，依照雅典法律飲下毒堇汁而死，臨終前依然與弟子們平靜地討論靈魂與死亡的本質，這一幕成為西方哲學史上最著名的死亡場景之一。',
      '值得留意的是，我們對蘇格拉底思想的認識，幾乎完全來自學生柏拉圖的轉述——而柏拉圖顯然帶有為老師辯護、甚至將自己的哲學主張借蘇格拉底之口說出的動機。喜劇作家阿里斯托芬筆下的蘇格拉底，形象卻近乎滑稽可笑、截然不同。這讓「歷史上真實的蘇格拉底究竟說過什麼」，成為西方哲學史上一個永遠無法徹底解開的謎題——我們讀到的，終究是被轉述、甚至被塑造過的蘇格拉底。'
    ]},

  { id:'plato', gen:'philosophy', zh:'柏拉圖', gr:'Plato', roman:'—', epithet:'理型論的建構者',
    year:-428, yearLabel:'西元前428年',
    domain:'形上學、政治哲學', symbol:'洞穴與太陽', parents:[], links:['socrates'],
    astro:'月球上有一座直徑101公里、地形平坦幽暗的著名撞擊坑，就命名為「柏拉圖坑」（Plato crater），是業餘天文愛好者用小型望遠鏡就能輕易觀察到的月面地標之一。',
    story:'柏拉圖是蘇格拉底最重要的學生，在雅典創立「學院」，是西方第一所有制度的高等學府。他主張感官所見的世界只是更高層次「理型」世界的影子，最著名的著作《理想國》以正義為核心，構築了一整套理想城邦的藍圖。',
    fullStory:[
      '柏拉圖出身雅典貴族家庭，年輕時師從蘇格拉底，蘇格拉底之死對他造成了極深的衝擊——他親眼見證了雅典民主制度以「多數決」的方式，處死了自己認為最有智慧的人，這個經驗成為他日後政治哲學思考的重要起點。此後，他遊歷各地，最終返回雅典創立了「學院」（Academy），這是西方歷史上第一所具有制度性課程的高等學府，教授哲學、數學與政治學，一直運作了近九百年之久。',
      '柏拉圖最核心的哲學主張是「理型論」：他認為我們感官所見的一切具體事物，都只是更高層次、永恆不變的抽象「理型」的不完美投影，就如同他在《理想國》中著名的「洞穴寓言」所描述——世人如同被鎖鏈困在洞穴裡的囚犯，畢生只能看見牆上晃動的影子，卻誤以為那就是真實本身。而《理想國》全書正是以「什麼是正義」為核心問題，層層推演出一套由「哲學家王」統治的理想城邦藍圖，是西方政治哲學史上最具影響力的著作之一。',
      '這套藍圖並非只被讚頌——二十世紀哲學家卡爾・波普爾便嚴厲批評，《理想國》裡由少數「知曉真理」的菁英全面主導城邦的構想，帶有壓制個人自由、走向極權的危險傾向，是他所謂「開放社會」最危險的敵人之一。就連理型論本身，也早被柏拉圖自己最優秀的學生亞里斯多德，當面指出邏輯上的漏洞——師徒二人這場延續兩千多年的爭論，至今仍未有定論。'
    ]},

  { id:'aristotle', gen:'philosophy', zh:'亞里斯多德', gr:'Aristotle', roman:'—', epithet:'萬學之師',
    year:-384, yearLabel:'西元前384年',
    domain:'邏輯學、倫理學、自然哲學', symbol:'金律與呂克昂學院', parents:[], links:['plato'],
    astro:'月球上另一座著名的撞擊坑「亞里斯多德坑」（Aristoteles crater），與柏拉圖坑一樣清晰可辨，兩人的名字如今仍並列於月球表面的同一片區域。',
    story:'亞里斯多德是柏拉圖學院裡最傑出的學生，後來自立門戶創辦呂克昂學院，並曾親自教導年少的亞歷山大大帝。他的研究幾乎涵蓋當時所有知識領域，被後世尊為「萬學之師」。',
    fullStory:[
      '亞里斯多德十七歲時進入柏拉圖的學院求學，一待就是二十年，是學院裡公認最傑出的學生，柏拉圖甚至稱他為「學院之才智」。然而在哲學根本立場上，他逐漸與老師分道揚鑣——柏拉圖認為真實存在於超越感官世界的抽象理型之中，亞里斯多德卻主張，應該從具體可觀察的事物本身出發去探究真理，這個分歧也奠定了西方哲學此後兩千年間理性主義與經驗主義兩大傳統的雛形。',
      '柏拉圖逝世後，亞里斯多德離開雅典，一度受馬其頓國王腓力二世之邀，擔任年僅十三歲的王子——也就是日後的亞歷山大大帝——的私人教師。後來他返回雅典，創立了自己的學院「呂克昂」，其學派因師生習慣邊散步邊講學，被稱為「逍遙學派」。亞里斯多德的著述橫跨邏輯學、倫理學、政治學、生物學、物理學、詩學等幾乎所有當時已知的知識領域，其著作長期被中世紀歐洲與伊斯蘭世界奉為各學科的權威範本，也因此被後世尊稱為「萬學之師」。',
      '然而，正因為亞里斯多德的權威在中世紀被奉為近乎不可挑戰的真理，他在自然科學上的諸多錯誤主張——例如物體越重下墜越快、地球是宇宙中心靜止不動——反而長期阻礙了後續科學的發展，直到伽利略、哥白尼等人以實際觀測挑戰他的權威，現代科學才得以真正起步。這也提醒我們：即使是史上最博學的人，他的話依然值得被檢驗，而非盲目奉為定論。'
    ]},

  { id:'hypatia', gen:'philosophy', zh:'希帕提亞', gr:'Hypatia', roman:'—', epithet:'亞歷山大城最後的哲學明燈',
    year:350, yearLabel:'約西元350年',
    domain:'新柏拉圖主義、數學、天文學', symbol:'星盤與圖書館', parents:[], links:['plato','serapis'],
    astro:'月球上有一座撞擊坑就以她命名，稱為「希帕提亞坑」；主帶小行星238 Hypatia同樣以她為名，1884年被發現。',
    story:'希帕提亞是希臘化埃及亞歷山大城最後一位重要的異教哲學家，教授數學、天文與新柏拉圖主義，深受各方敬重，卻在西元415年遭一群基督教暴民殘忍殺害，她的死常被視為古典異教哲學傳統在地中海世界終結的象徵性時刻。',
    fullStory:[
      '希帕提亞是亞歷山大城數學家席昂之女，自幼便接受父親悉心栽培，成年後接掌亞歷山大城的新柏拉圖主義學派，教授數學、天文學與哲學。她的學識與辯才吸引了來自羅馬帝國各地的學生，其中不乏日後身居高位的政治人物與教會人士，在當時的亞歷山大城，她是公認的知識權威，甚至時常受邀為地方官員排解政治糾紛。',
      '然而，希帕提亞所處的時代，正值基督教在羅馬帝國迅速崛起、異教信仰與哲學傳統節節敗退的動盪時期——就在她出生前不久，這座城市裡供奉塞拉皮斯的宏偉神廟才剛被一群基督徒暴民搗毀。西元415年，亞歷山大城主教區與地方總督之間爆發激烈的權力鬥爭，希帕提亞因與總督交好、又代表著異教哲學的知識權威，成為這場鬥爭的犧牲品——一群暴民將她從馬車上拖下，殘忍地將她處死。',
      '希帕提亞的死，後世常被視為古典哲學傳統在地中海世界逐漸終結的象徵性時刻——儘管歷史學界普遍認為，將她的死簡化為「宗教對抗理性」的單一敘事，其實忽略了背後更複雜的政治鬥爭脈絡。她沒有任何著作留存至今，我們對她思想的認識，幾乎全數來自後世學生與同時代人的轉述——這也讓希帕提亞的形象，某種程度上與蘇格拉底有著相似的處境：一位影響深遠、卻幾乎沒有留下自己聲音的哲學家。'
    ]},

  { id:'diotima', gen:'philosophy', zh:'戴奧提瑪', gr:'Diotima of Mantinea', roman:'—', epithet:'蘇格拉底口中教導愛欲階梯的女祭司',
    domain:'愛欲、美、靈魂昇華', symbol:'曼提尼亞的祭壇', parents:[], links:['symposium','socrates'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'戴奧提瑪是柏拉圖《會飲篇》裡，蘇格拉底親口轉述曾指點自己「愛欲哲學」的曼提尼亞女祭司——她提出的「愛之階梯」，主張真正的愛欲應從迷戀某個具體對象，逐步昇華至對「美」本身的永恆追求。然而她是否真有其人，至今仍是學界懸而未決的謎題。',
    fullStory:[
      '在《會飲篇》裡，當輪到蘇格拉底發言讚頌愛神時，他並未直接提出自己的見解，而是轉述了一位名叫戴奧提瑪的曼提尼亞女祭司多年前教導給他的一番話——據蘇格拉底描述，正是這位女性，啟發了他對「愛欲」本質最深刻的理解。這個敘事手法本身便耐人尋味：在整場清一色男性發言的酒宴上，全書思想上最深刻的一段見解，竟是透過一位缺席的女性、經由男性之口間接轉述而來。',
      '戴奧提瑪提出的「愛之階梯」，主張愛欲的發展有其層層遞進的軌跡：從迷戀某一具體的美麗肉身開始，逐漸體悟到所有美麗身軀共通的本質，進而轉向欣賞美麗的靈魂、美好的制度與知識，最終抵達對「美」本身——那個超越一切具體事物、永恆不變的理型——的純粹凝視與愛慕。這套架構後來深刻影響了西方哲學與神學裡，談論「愛如何引領靈魂昇華」的漫長傳統。',
      '戴奧提瑪是否真有其人，是柏拉圖研究裡長期懸而未決的問題——她未曾出現在任何其他古代文獻之中，部分學者認為，她很可能是柏拉圖虛構出來的角色，用以透過「女性的智慧」這個設定，為蘇格拉底的論述增添一層神秘的權威感，而非確有一位真實存在的女祭司。若真是如此，戴奧提瑪的存在本身便成了一則意味深長的反諷：一部探討「什麼是真實的美與愛」的哲學經典，其最重要的思想源頭，卻可能只是一個被創造出來的聲音。'
    ]},

  { id:'republic', gen:'philosophy', zh:'《理想國》', gr:'Politeia', roman:'De Republica', epithet:'西方政治哲學的奠基之作',
    domain:'正義、城邦、教育', symbol:'洞穴寓言', parents:[], links:['plato','themis'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 170" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <line x1="0" y1="150" x2="300" y2="150" stroke="#5B5850" stroke-width="2"/>
      <line x1="260" y1="20" x2="260" y2="150" stroke="#5B5850" stroke-width="2"/>
      <text x="272" y="35" font-size="9" fill="#6b5c46">牆</text>
      <ellipse cx="245" cy="95" rx="8" ry="22" fill="#2A2118" opacity="0.5"/>
      <ellipse cx="228" cy="98" rx="6" ry="18" fill="#2A2118" opacity="0.4"/>
      <circle cx="160" cy="100" r="9" fill="#B5502E"/>
      <text x="160" y="85" font-size="9" text-anchor="middle" fill="#6b5c46">火</text>
      <circle cx="200" cy="128" r="6" fill="#5B5850"/>
      <line x1="200" y1="134" x2="200" y2="150" stroke="#5B5850" stroke-width="2"/>
      <circle cx="215" cy="130" r="6" fill="#5B5850"/>
      <line x1="215" y1="136" x2="215" y2="150" stroke="#5B5850" stroke-width="2"/>
      <polygon points="0,150 40,150 20,20" fill="#E8C468" opacity="0.5"/>
      <text x="20" y="14" font-size="9" text-anchor="middle" fill="#8A6D1F">真實世界的光</text>
      <text x="150" y="166" font-size="8.5" text-anchor="middle" fill="#6b5c46">囚犯只看得見牆上的影子，誤以為那就是全部</text>
    </svg>`,
    story:'《理想國》是柏拉圖最重要的對話錄，以蘇格拉底與友人的辯論形式展開，探討「什麼是正義」，並提出由哲學家統治的理想城邦藍圖，其中的「洞穴寓言」更是西方思想史上最著名的比喻之一。',
    fullStory:[
      '《理想國》全書以蘇格拉底與一群雅典友人的對話形式展開，表面上是在爭論「正義對個人是否有利」，實際上卻逐步推演出一整套關於靈魂、教育、政治與宇宙秩序的宏大體系。柏拉圖藉蘇格拉底之口主張，正義的城邦與正義的靈魂結構相似，都應該由「理性」居於主導地位——對應到城邦，就是由真正熱愛智慧、不受權力與財富誘惑的「哲學家王」來統治。',
      '書中最廣為人知的段落，是第七卷的「洞穴寓言」：一群人自幼被鎖鏈困在洞穴深處，只能面對牆壁，將身後火光投射出的影子誤認為是真實世界的全部；當其中一人被迫轉身、走出洞穴，親眼見到陽光下真實的世界，回到洞穴想要告訴同伴真相時，卻反而被視為瘋子。這則寓言精準地捕捉了柏拉圖「理型論」的核心——我們日常所見的世界，或許只是更高層次真實的影子，而哲學的任務，正是引導靈魂轉身，走向那道真正的光。',
      '值得留意的是，柏拉圖本人晚年曾親赴西西里島，試圖說服敘拉古的統治者狄奧尼修二世實踐這套「哲學家王」的理想，結果卻以失敗告終，甚至一度身陷險境、幾乎被賣為奴。這段真實的挫敗經歷，某種程度上也反映出《理想國》的政治藍圖，終究更接近一則深刻的思想實驗，而非真正可行的治國方案。'
    ]},

  { id:'symposium', gen:'philosophy', zh:'《會飲篇》', gr:'Symposion', roman:'Symposium', epithet:'關於愛的對話錄',
    domain:'愛欲、美、靈魂', symbol:'酒杯與雙面人', parents:[], links:['plato','aphrodite'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'《會飲篇》記錄了一群雅典人在酒宴上輪流讚頌愛神厄洛斯的對話，其中喜劇作家阿里斯托芬所講述的「人類原本是球形雙體」的神話，是關於愛情起源最富想像力的解釋之一。',
    fullStory:[
      '《會飲篇》的場景設定在一場慶祝悲劇比賽獲勝的酒宴上，與會賓客們約定，這一夜不談政治，改為輪流發表演說，讚頌愛神厄洛斯。書中收錄了包括喜劇作家阿里斯托芬、醫生厄律克西馬庫、以及蘇格拉底本人在內，數段風格迥異卻同樣精彩的演說，共同構成了西方文學史上對「愛」最深刻也最多元的一次集體思辨。',
      '其中最廣為流傳的，是阿里斯托芬所講述的一則神話：他說，人類原本是球形的雙體生物，擁有四手四腳、兩張面孔，力量強大到足以挑戰諸神，宙斯因此將每個人劈成兩半，只留下肚臍作為傷疤的印記。從此，每個被劈開的人終其一生，都在尋找當初與自己合而為一的另一半——這正是「愛情」的起源，也是「另一半」（better half）這個說法最早的神話原型。輪到蘇格拉底發言時，他則轉述女祭司狄奧提瑪的教誨，主張愛欲的最高形式，並非對某個具體對象的迷戀，而是對「美」本身的永恆追求——這個層層提升的「愛之階梯」，成為後世西方哲學與神學談論愛與靈魂昇華時，反覆援引的經典架構。',
      '也值得留意的是，這場關於「愛」的思辨，從頭到尾清一色由男性發言——這正反映了古雅典社會的現實：女性被排除在正式的公共思想論辯之外。即使書中角色屢屢提及一位女性智者（那位被引述的女祭司狄奧提瑪），她的智慧終究也只能透過蘇格拉底這位男性之口被間接轉述，而非親自登場發言。'
    ]},

  { id:'apology', gen:'philosophy', zh:'《申辯篇》', gr:'Apologia', roman:'Apologia Socratis', epithet:'蘇格拉底的法庭自辯',
    domain:'審判、良知、哲學生活', symbol:'法庭與陪審團', parents:[], links:['socrates','plato'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'《申辯篇》記錄了蘇格拉底面對雅典法庭「腐蝕青年」與「不敬諸神」指控時所發表的自辯演說，他拒絕妥協求饒，堅持哲學式生活的價值，最終慷慨赴死，全篇是西方思想史上關於良知與言論自由最動人的文獻之一。',
    fullStory:[
      '西元前399年，年邁的蘇格拉底被三名雅典公民聯合指控「腐蝕青年心智」與「不信奉城邦諸神、引入新神」，依雅典法律必須接受由五百零一位公民組成的陪審團公開審判。《申辯篇》正是柏拉圖對這場審判過程的記錄，儘管學界普遍認為其中經過了柏拉圖本人一定程度的文學加工，但普遍相信核心精神忠實反映了蘇格拉底本人的態度。',
      '面對足以致死的指控，蘇格拉底並未如常人般苦苦哀求陪審團從輕發落，反而以一貫的詰問語氣，反過來質疑控告者的邏輯漏洞，並堅稱自己一生詰問世人，正是雅典城邦最需要、卻最不願承認的良心刺激。他甚至向陪審團表示，若判他終身停止哲學思考以換取活命，他寧可選擇死亡，因為「未經檢視的人生，是不值得活的」。最終陪審團以些微差距判他有罪、並判處死刑，蘇格拉底坦然接受判決，全篇展現出一種即使身處絕境，依然堅持理性與良知的哲學姿態，深深影響了後世無數面對政治迫害的思想者。',
      '蘇格拉底的審判與死刑，也常被後世援引為「多數決民主」潛在陰暗面的警世案例——即使雅典自豪於直接民主的公民審議制度，卻依然可能因為群眾的恐懼、偏見或一時情緒，以合法程序處死了一位事後被公認具有深遠貢獻的思想者。這個張力，至今仍是政治哲學裡討論「多數決是否就等於正義」時，反覆被提起的核心案例。'
    ]},

  { id:'metaphysics', gen:'philosophy', zh:'《形而上學》', gr:'Metaphysika', roman:'Metaphysica', epithet:'探究存在本身的學問',
    domain:'第一因、存有、本質', symbol:'第一因之鏈', parents:[], links:['aristotle'],
    astro:'目前沒有廣為人知的正式天體命名，但書名「Metaphysics」本身的由來十分特別——並非亞里斯多德本人命名，而是後世編輯者將這部手稿排列在《物理學》（Physics）之後，直譯便是「物理學之後」，機緣巧合下卻精準呼應了書中探討超越具體物質現象的核心主題。',
    diagram:`<svg viewBox="0 0 300 130" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="255" cy="65" r="16" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="255" y="69" font-size="9" text-anchor="middle" fill="#2A2118">結果</text>
      <line x1="239" y1="65" x2="211" y2="65" stroke="#5B5850" stroke-width="1.5"/>
      <circle cx="195" cy="65" r="16" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="195" y="69" font-size="9" text-anchor="middle" fill="#2A2118">因</text>
      <line x1="179" y1="65" x2="151" y2="65" stroke="#5B5850" stroke-width="1.5"/>
      <circle cx="135" cy="65" r="16" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="135" y="69" font-size="9" text-anchor="middle" fill="#2A2118">因</text>
      <line x1="119" y1="65" x2="94" y2="65" stroke="#5B5850" stroke-width="1.5" stroke-dasharray="3 3"/>
      <text x="106" y="55" font-size="14" text-anchor="middle" fill="#6b5c46">…</text>
      <circle cx="60" cy="65" r="20" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="2"/>
      <text x="60" y="61" font-size="8" text-anchor="middle" fill="#2A2118">不動的</text>
      <text x="60" y="71" font-size="8" text-anchor="middle" fill="#2A2118">推動者</text>
      <text x="150" y="115" font-size="8.5" text-anchor="middle" fill="#6b5c46">因果鏈條不能無限往前推，所以需要一個起點？</text>
    </svg>`,
    story:'《形而上學》是亞里斯多德探討「存在本身」的著作，提出萬物變化背後存在「第一因」（不動的推動者），這個概念後來深刻影響了中世紀神學對「上帝」的哲學論證。',
    fullStory:[
      '《形而上學》這個書名的由來，其實是一場美麗的意外——這並非亞里斯多德本人為這部手稿所取的標題，而是西元前一世紀的編輯者在整理他的著作時，將這一系列討論抽象存有問題的文本，排列在《物理學》（Physics）之後，因此以希臘文「ta meta ta physika」（意即「物理學之後的那些」）稱之，日後演變成「Metaphysics」一詞。然而這個純屬編排順序的命名，卻意外精準地呼應了全書真正的主題：探討那些超越具體物質現象、關於「存在本身」的根本問題。',
      '書中最深遠的貢獻之一，是亞里斯多德對「第一因」的論證：他觀察到世間萬物都處於不斷變化之中，每一個變化都必然由某個更早的原因所推動，然而這個因果鏈條不可能無限向前追溯，因此必然存在一個「不動的推動者」——它自身不受任何事物推動，卻是萬物變化最終的源頭。這個純粹哲學性的推論，後來被中世紀基督教與伊斯蘭神學家廣泛援引，作為論證上帝存在的重要理性基礎，讓一部原本探討抽象存有問題的哲學著作，意外成為連接古希臘理性思辨與中世紀宗教神學的重要橋樑。',
      '不過，這套「第一因」論證後世也遭遇不少哲學挑戰——十八世紀哲學家休謨便質疑：我們有什麼理由認為因果鏈條「不能」無限向前追溯？「必須存在第一因」這個直覺，會不會只是人類思維習慣的產物，而非邏輯上的必然？這場關於「宇宙是否需要一個起點」的辯論，兩千多年後，其實仍未真正塵埃落定。'
    ]},

  { id:'nicomachean', gen:'philosophy', zh:'《尼各馬可倫理學》', gr:'Ethika Nikomacheia', roman:'Ethica Nicomachea', epithet:'幸福即德性的實踐',
    domain:'德性、幸福、中庸之道', symbol:'天秤與中道', parents:[], links:['aristotle'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 130" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <rect x="20" y="55" width="260" height="14" rx="7" fill="#EFE6CE" stroke="#A6812E"/>
      <rect x="20" y="55" width="86" height="14" rx="7" fill="#D8C9A0"/>
      <rect x="194" y="55" width="86" height="14" rx="7" fill="#D8C9A0"/>
      <circle cx="150" cy="62" r="9" fill="#5B5850" stroke="#fff" stroke-width="2"/>
      <text x="63" y="45" font-size="10" text-anchor="middle" fill="#6b5c46">不足</text>
      <text x="150" y="45" font-size="10" text-anchor="middle" fill="#2A2118" font-weight="bold">中庸</text>
      <text x="237" y="45" font-size="10" text-anchor="middle" fill="#6b5c46">過度</text>
      <text x="63" y="90" font-size="9" text-anchor="middle" fill="#6b5c46">怯懦</text>
      <text x="150" y="90" font-size="9" text-anchor="middle" fill="#2A2118">勇敢</text>
      <text x="237" y="90" font-size="9" text-anchor="middle" fill="#6b5c46">魯莽</text>
      <text x="150" y="115" font-size="8.5" text-anchor="middle" fill="#6b5c46">每種德性，都是兩個極端之間的平衡點</text>
    </svg>`,
    story:'《尼各馬可倫理學》是亞里斯多德最重要的倫理學著作，主張人生的終極目標是「幸福」（eudaimonia），而幸福並非來自享樂，而是透過長期實踐德性、掌握「中庸之道」而達成。',
    fullStory:[
      '《尼各馬可倫理學》得名於亞里斯多德的兒子尼各馬可，後世相信這部講稿正是由他整理編訂而成。全書開宗明義提出一個根本問題：人生真正追求的終極目的是什麼？亞里斯多德的答案是「幸福」（希臘文 eudaimonia，也常譯為「生命的興盛圓滿」），但他所謂的幸福，並非單純的快樂享受或財富權力，而是一種透過長期實踐良善行為所達到的、整全的生命狀態。',
      '亞里斯多德進一步提出著名的「中庸之道」：他認為每一種德性都座落在兩種極端惡習之間的中間點，例如「勇敢」是「魯莽」與「怯懦」兩個極端之間的中道，「慷慨」則是「揮霍」與「吝嗇」之間的平衡。這種德性並非天生具備，而必須透過日復一日的實際練習，如同學習彈奏樂器或鍛鍊技藝一般，透過反覆行動養成習慣，才能真正內化為一個人的品格。這套「德性倫理學」的思考方式，在沉寂了相當長一段時間後，於二十世紀重新受到西方倫理學界高度重視，至今仍是探討「如何過美好人生」時無法迴避的重要參照。',
      '也需要指出的是，亞里斯多德所描繪的「美好人生」，預設的對象幾乎僅限於有閒暇思辨德性的自由男性公民——他在其他著作中，甚至明確主張女性與奴隸在理性能力上天生不及自由男性。這樣的立場，在今日看來顯然是嚴重的時代局限，也提醒我們，即使是最深刻的倫理學經典，也需要放在其歷史脈絡中批判地閱讀，而非全盤照單全收。'
    ]},

  // ---------- CLASSICAL PHILOSOPHICAL SCHOOLS ----------
  { id:'sophism', gen:'philosophy', zh:'智者學派', gr:'Sophists', roman:'—', epithet:'收費授徒的雄辯之師',
    year:-490, yearLabel:'約西元前490年（普羅塔哥拉斯）',
    domain:'修辭學、相對主義', symbol:'講壇與硬幣', parents:[], links:['socrates'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'智者學派是活躍於雅典的一群收費授課的職業教師，教導公民辯論與修辭之術，代表人物普羅塔哥拉斯提出「人是萬物的尺度」，主張真理因人而異，與蘇格拉底堅持「客觀真理可被詰問求得」的立場形成鮮明對立。',
    fullStory:[
      '智者（Sophist，字面意思即「有智慧的人」）並非單一學派，而是西元前五世紀活躍於雅典的一群職業教師的統稱。他們遊走各城邦，向渴望在民主政治中脫穎而出的年輕貴族收取高額學費，教授修辭、辯論與說服的技巧——在雅典這樣人人可上台演說、法庭上全憑辯才定輸贏的直接民主城邦裡，這樣的技藝極具實用價值。',
      '智者學派最具代表性的主張，來自普羅塔哥拉斯著名的宣言：「人是萬物的尺度」，意即真理與價值並非客觀恆定，而是因人而異、因觀點而異。這種相對主義的立場，與蘇格拉底畢生追求「透過理性詰問找到普遍客觀真理」的信念截然對立，也讓「詭辯」（sophistry）一詞逐漸帶上貶義，用來形容看似巧妙、實則似是而非的論證技巧。儘管評價兩極，智者學派對修辭與論證技術的系統化貢獻，仍深刻影響了西方教育與法庭辯論的傳統。',
      '值得一提的是，我們今天對智者學派的負面印象，很大程度上其實來自他們論敵柏拉圖的著作——柏拉圖筆下的智者，往往被刻劃成巧言令色、不擇手段的反派角色，但這未必是全貌。畢竟歷史多半是由勝出的一方書寫的，智者學派自己的原始著作幾乎全數佚失，我們幾乎再也聽不到他們為自己辯護的聲音。'
    ]},

  { id:'cynicism', gen:'philosophy', zh:'犬儒學派', gr:'Cynicism', roman:'—', epithet:'拋棄一切世俗虛飾的苦行者',
    year:-445, yearLabel:'約西元前445年（安提斯泰尼）',
    domain:'簡樸生活、自然而活', symbol:'木桶與破斗篷', parents:[], links:['socrates'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'犬儒學派由蘇格拉底的學生安提斯泰尼創立，最著名的代表人物第歐根尼主張拋棄一切世俗財富與社會虛飾，回歸自然簡樸的生活，據說他住在一只木桶裡，白天提著燈籠在雅典街頭「尋找一個誠實的人」。',
    fullStory:[
      '犬儒學派的創始人安提斯泰尼曾是蘇格拉底的學生，他將老師「德性即幸福」的主張推向極端，認為社會習俗、財富、名聲全是妨礙人接近真正德性與幸福的虛飾累贅，唯有回歸如野獸般順應自然的簡樸生活，才能獲得真正的自由。「犬儒」（Cynic）一詞正是源自希臘文「狗」，最初是對他們不修邊幅、蔑視禮俗生活方式的嘲諷稱呼，後來卻被學派成員自己欣然接受。',
      '犬儒學派最著名的代表人物是第歐根尼，他將這套哲學實踐到近乎表演藝術的程度：據說他放棄所有財產，住進一只廢棄的大陶缸或木桶裡，白天提著點燃的燈籠在雅典人來人往的市集中穿梭，逢人便說自己「正在尋找一個誠實的人」，藉此諷刺世人的虛偽。傳說亞歷山大大帝曾親自造訪，問他有什麼願望可以滿足，第歐根尼只回答：「請你閃到一邊去，別擋住我的陽光。」這種對世俗權力毫不畏懼的姿態，成為犬儒學派留給後世最鮮明的形象。',
      '有趣的是，現代英語中「cynical」（憤世嫉俗）這個形容詞，雖然源自這個學派，意涵卻已經和原始的犬儒哲學相去甚遠——古代犬儒學派追求的是回歸自然、鄙視虛榮的正面德行實踐，而不是現代意義下「對一切都不信任、覺得人性本惡」的消極心態，這是一次頗值得留意的語意流變。'
    ]},

  { id:'diogenes', gen:'philosophy', zh:'第歐根尼', gr:'Diogenes', roman:'—', epithet:'住在木桶裡叫亞歷山大閃開的人',
    year:-412, yearLabel:'約西元前412年',
    domain:'犬儒哲學、極簡生活、對權力的嘲諷', symbol:'木桶、燈籠與日光', parents:[], links:['cynicism'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'第歐根尼是犬儒哲學最知名的實踐者，據說他住在一只木桶裡，當亞歷山大大帝親自前來詢問他能為這位「世界霸主」做什麼時，他的回答是：「請你站到旁邊去，別擋住我的陽光。」這句話讓亞歷山大事後感嘆：「如果我不是亞歷山大，我寧可是第歐根尼。」',
    fullStory:[
      '第歐根尼出身錫諾普（一個希臘在小亞細亞黑海沿岸的殖民地），因涉嫌偽造貨幣被起訴後選擇自我放逐流浪至雅典，在此接觸了安提斯泰尼的教誨，從此成為犬儒哲學最激進的實踐者——不是寫書傳授，而是用整整一生，把這套主張活成了街頭行為藝術。',
      '他放棄所有財產，住進雅典廣場旁的一只大陶缸或木桶裡，白天提著燈籠在人群中走動，逢人便說：「我在找人。」這句話的真正意思是：在一個充滿虛偽與自我欺騙的世界裡，他仍在尋找一個真正清醒、誠實面對自己的人。傳說他甚至會在公共浴場裸身行走，聲稱「若自然狀態是可恥的，那自然未免也太會開玩笑了」。',
      '關於他與亞歷山大大帝的那段流傳千古的相遇，細節出自多部較晚的古代文獻，學界對其真實性存疑——但這則軼事之所以如此廣泛流傳，正因為它精準捕捉了犬儒哲學最核心的精神：真正的自由不是擁有更多，而是需要更少；真正的權力不是征服他人，而是對一切外在事物都一無所求。',
      '第歐根尼式的「拒絕」放到今天，其實是對整個「成功學敘事」的終極反詰：當整個社會在告訴你「要更有生產力、更有效率、累積更多資本」時，第歐根尼用他那只木桶，默默提醒你：你也可以對這整個競賽規則說不。'
    ]},

  { id:'stoicism', gen:'philosophy', zh:'斯多葛學派', gr:'Stoicism', roman:'—', epithet:'順應理性與命運的哲學',
    year:-334, yearLabel:'約西元前334年（芝諾）',
    domain:'德性、理性、接受命運', symbol:'畫廊柱廊', parents:[], links:['cynicism'],
    astro:'斯多葛學派晚期最重要的哲學家之一克律西波斯，曾提出宇宙會周期性地被一場「大火」淨化、萬物重新循環再生的宇宙論構想，這個「宇宙輪迴」的想法，與後世某些天文學上關於宇宙循環膨脹收縮的理論，隱約遙相呼應。',
    diagram:`<svg viewBox="0 0 300 180" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="150" cy="88" r="75" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <circle cx="150" cy="88" r="38" fill="#FBF6E9" stroke="#5B5850" stroke-width="1.5"/>
      <text x="150" y="83" font-size="10" text-anchor="middle" fill="#2A2118" font-weight="bold">操之在我</text>
      <text x="150" y="97" font-size="8" text-anchor="middle" fill="#6b5c46">判斷、意願、行為</text>
      <text x="150" y="35" font-size="10" text-anchor="middle" fill="#6b5c46">操之不在我</text>
      <text x="150" y="48" font-size="8" text-anchor="middle" fill="#8A7A5C">健康、他人看法、生死</text>
      <text x="150" y="172" font-size="8.5" text-anchor="middle" fill="#6b5c46">智者只把心力放在內圈</text>
    </svg>`,
    story:'斯多葛學派由芝諾創立，主張德性是唯一真正的善，教導人應區分「能控制之事」與「不能控制之事」，專注前者、坦然接受後者，這套哲學後來深刻影響了羅馬皇帝馬可・奧理略等人。',
    fullStory:[
      '斯多葛學派的創始人芝諾原是塞浦路斯島季蒂昂的商人，據說一次船難令他傾家蕩產，流落雅典，因緣際會接觸哲學後徹底轉向思想生活。他常在雅典市集一處畫著壁畫的柱廊（希臘文Stoa Poikile，「畫廊」）下向學生授課，「斯多葛」（Stoic）這個名稱正是由此而來。芝諾早年曾受教於犬儒學派的克拉特斯，因此斯多葛學派在精神上帶有濃厚的犬儒色彩，卻發展出遠比犬儒更有系統的宇宙論與倫理學架構。',
      '斯多葛學派最核心的教誨，是區分「操之在我」與「操之不在我」：一個人的判斷、意願、行為操之在我，而健康、財富、他人的看法、乃至生死，全都操之不在我。真正的智者應該全心專注於自己能掌控的部分，對於無法掌控的外在境遇，則應以理性坦然接受，而非徒勞地憂懼或抗拒——這便是「斯多葛式的平靜」的由來。這套哲學後來傳入羅馬，深受政治家與軍人階層歡迎，其中最著名的實踐者，正是身兼羅馬皇帝與哲學家雙重身分的馬可・奧理略，他的私人札記《沉思錄》，至今仍是斯多葛哲學最廣為人知的代表作。',
      '也有人批評，斯多葛哲學「專注於能控制之事、坦然接受不能控制之事」的態度，若被無限上綱，可能淪為對不公不義處境的消極隱忍，甚至被既得利益者拿來勸誡弱勢者「安於現狀」。這也是每一套強調「內心平靜」的哲學，都需要謹慎拿捏的分寸——接受命運，不該變成放棄改變的藉口。'
    ]},

  { id:'epicureanism', gen:'philosophy', zh:'伊比鳩魯學派', gr:'Epicureanism', roman:'—', epithet:'追求心靈寧靜的快樂主義',
    year:-341, yearLabel:'西元前341年（伊比鳩魯）',
    domain:'快樂、無懼、原子論', symbol:'花園與原子', parents:[], links:[],
    astro:'伊比鳩魯是最早期系統性主張「宇宙中存在無數個世界」的思想家之一——他在《致希羅多德的信》中提出，構成萬物的原子數量無窮，因此宇宙中必然存在無數個類似地球的世界，這個構想比現代天文學發現系外行星，早了兩千多年。',
    diagram:`<svg viewBox="0 0 300 140" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <rect x="20" y="20" width="260" height="80" fill="none" stroke="#5B5850" stroke-width="1"/>
      <circle cx="60" cy="45" r="6" fill="#A6812E"/>
      <circle cx="110" cy="70" r="5" fill="#A6812E"/>
      <circle cx="160" cy="40" r="7" fill="#A6812E"/>
      <circle cx="200" cy="80" r="4" fill="#A6812E"/>
      <circle cx="240" cy="55" r="6" fill="#A6812E"/>
      <circle cx="90" cy="90" r="5" fill="#A6812E"/>
      <circle cx="230" cy="30" r="4" fill="#A6812E"/>
      <text x="150" y="120" font-size="8.5" text-anchor="middle" fill="#6b5c46">萬物皆由原子與虛空構成</text>
    </svg>`,
    story:'伊比鳩魯創立的學派主張，人生真正的快樂並非縱情享樂，而是透過節制慾望、遠離恐懼（尤其是對死亡的恐懼），達到心靈的寧靜安穩，他在雅典郊外購置了一座花園，與弟子共同過著簡樸而愉悅的群居生活。',
    fullStory:[
      '伊比鳩魯在雅典郊外購置了一座花園，作為他與弟子們共同生活、講學論道的場所，後世稱其學派為「花園學派」。與世人常誤解的「享樂主義」形象不同，伊比鳩魯所謂的快樂，並非縱情聲色的感官享受，而是透過節制物質慾望、避免不必要的恐懼與焦慮，達到一種被稱為「心靈不受干擾」（ataraxia）的寧靜安穩狀態——他認為，簡單的麵包與清水配上摯友的陪伴，遠比山珍海味帶來的快樂更加持久踏實。',
      '伊比鳩魯特別致力於消解人們對死亡與神明降罪的恐懼，他提出一個著名的論證：「死亡與我們毫不相干，因為當我們存在時，死亡尚未來臨；而當死亡來臨時，我們已不復存在。」他同時繼承並發展了德謨克利特的原子論，主張萬物皆由不可分割的微小原子構成，宇宙中原子的數量與組合方式趨近無窮，因此必然存在無數個類似我們所處世界的其他世界——這個誕生於兩千三百多年前的大膽推想，某種程度上，竟成為後世天文學家尋找系外行星、探討宇宙中是否存在其他生命世界的一則遙遠精神先聲。',
      '諷刺的是，「伊比鳩魯主義」（Epicurean）這個詞，在後世（尤其是基督教興起後）逐漸被扭曲成「縱慾享樂」的貶義詞，這很大程度上是因為伊比鳩魯否定神明會介入人間、否定死後審判的立場，觸怒了後來成為主流的宗教傳統，才被刻意汙名化——真正讀過他原始書信的人，會發現他描述的生活態度其實克制而近乎樸素，與後世給他扣上的帽子相去甚遠。'
    ]},

  { id:'skepticism', gen:'philosophy', zh:'懷疑學派', gr:'Skepticism (Pyrrhonism)', roman:'—', epithet:'懸置判斷以求心安',
    year:-360, yearLabel:'約西元前360年（皮浪）',
    domain:'存疑、心靈平靜', symbol:'天秤兩端等重', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 150" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <line x1="150" y1="30" x2="150" y2="60" stroke="#5B5850" stroke-width="2"/>
      <line x1="80" y1="60" x2="220" y2="60" stroke="#5B5850" stroke-width="2"/>
      <line x1="80" y1="60" x2="80" y2="90" stroke="#5B5850" stroke-width="1"/>
      <line x1="220" y1="60" x2="220" y2="90" stroke="#5B5850" stroke-width="1"/>
      <rect x="55" y="90" width="50" height="8" rx="4" fill="#EFE6CE" stroke="#A6812E"/>
      <rect x="195" y="90" width="50" height="8" rx="4" fill="#EFE6CE" stroke="#A6812E"/>
      <text x="80" y="115" font-size="8" text-anchor="middle" fill="#6b5c46">正論證</text>
      <text x="220" y="115" font-size="8" text-anchor="middle" fill="#6b5c46">反論證</text>
      <text x="150" y="140" font-size="8.5" text-anchor="middle" fill="#6b5c46">力量相當，永遠無法傾斜</text>
    </svg>`,
    story:'懷疑學派由皮浪創立，主張人類感官與理性皆不可靠，任何命題都能找到同樣有力的反面論證，因此智者應對一切事物「懸置判斷」，不輕易斷言真假，唯有如此才能擺脫武斷信念帶來的焦慮，獲得心靈的寧靜。',
    fullStory:[
      '皮浪年輕時曾隨亞歷山大大帝的遠征軍隊一路東行，據說途中接觸了印度的苦行僧人與哲人，深受其「捨棄執念以求解脫」的思想觸動，返回希臘後創立了以他為名的「皮浪主義」，後世也稱為懷疑學派。他本人未曾留下著作，其思想主要透過後繼者塞克斯圖斯・恩丕里柯的著作流傳至今。',
      '懷疑學派的核心方法，是針對任何一個命題，系統性地尋找出力量相當的反面論證，藉此證明人類既有的感官經驗與理性推論，都無法讓我們對事物的真實本質獲得確定無疑的知識。既然如此，智者面對任何爭議性的命題，最合理的態度便是「懸置判斷」（epoché）——既不肯定、也不否定，維持一種開放而不武斷的存疑姿態。懷疑學派相信，正是這種對確定性的放下，才能讓人擺脫因堅持錯誤信念、或執著於尋求無法企及的真理而產生的焦慮，最終達到內心的平靜（ataraxia）——與斯多葛、伊比鳩魯學派殊途同歸，都將「心靈的寧靜」視為哲學探索的終極目標。',
      '懷疑學派也始終面臨一個邏輯上的自我指涉困境：如果連任何命題都不該輕易斷言真假，那麼「應該懸置一切判斷」這個主張本身，是否也該被懸置？這個難題至今仍是評價徹底懷疑論時，繞不開的哲學質疑——一套宣稱什麼都不能確定的理論，究竟能不能對自己這麼確定？'
    ]},

  { id:'ibnsina', gen:'philosophy', zh:'伊本・西那', gr:'Ibn Sina (Avicenna)', roman:'—', epithet:'讓亞里斯多德流傳於伊斯蘭黃金時代的醫師哲學家',
    year:980, yearLabel:'980年',
    domain:'形上學、醫學、邏輯學', symbol:'醫典與飛人思想實驗', parents:[], links:['aristotle'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 160" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="150" cy="70" r="18" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <rect x="138" y="62" width="24" height="6" fill="#5B5850"/>
      <line x1="150" y1="88" x2="150" y2="120" stroke="#5B5850" stroke-width="2"/>
      <line x1="150" y1="95" x2="130" y2="115" stroke="#5B5850" stroke-width="2"/>
      <line x1="150" y1="95" x2="170" y2="115" stroke="#5B5850" stroke-width="2"/>
      <text x="150" y="30" font-size="9" text-anchor="middle" fill="#2A2118">懸浮、蒙眼、感官全無</text>
      <text x="150" y="145" font-size="8.5" text-anchor="middle" fill="#6b5c46">卻依然確信「我存在」</text>
    </svg>`,
    story:'伊本・西那是伊斯蘭黃金時代最重要的哲學家與醫學家之一，他融合亞里斯多德哲學與伊斯蘭神學，寫下的《醫典》長達數百年是歐洲大學的標準醫學教材，他對亞里斯多德的注釋，更是中世紀歐洲重新認識這位古希臘哲人的重要橋樑。',
    fullStory:[
      '伊本・西那生於中亞布哈拉附近，據說十歲便已背誦完整部《古蘭經》，青少年時期自學醫學，十八歲時已是當地聞名的醫師。他一生著述超過兩百部作品，橫跨哲學、醫學、邏輯學、天文學等領域，其中《醫典》系統性地整理了古希臘、羅馬與伊斯蘭世界的醫學知識，長達近六百年，一直是歐洲各大學醫學系的標準教材，直到十七世紀才逐漸被取代。',
      '伊本・西那哲學上最具原創性的貢獻之一，是他著名的「飛人思想實驗」：他請讀者想像一個人一出生便懸浮於空中、被蒙住雙眼、四肢與外界完全隔絕、感受不到任何身體知覺——即便如此，這個人依然能確信「自己存在」，因為思考本身這個行為，就已經證明了心靈的存在，不需要依賴任何感官經驗。這個論證比笛卡兒著名的「我思故我在」，早了將近六百年。',
      '當歐洲在中世紀初期幾乎遺失了亞里斯多德大部分著作的原始文本時，正是伊本・西那與稍後的伊本・魯世德等伊斯蘭學者，持續研讀、注釋、翻譯這些希臘典籍，讓亞里斯多德的思想體系得以保存下來。十二世紀後，這些阿拉伯文注釋本再被翻譯回拉丁文，重新傳回歐洲，直接促成了中世紀經院哲學的復興——伊本・西那對亞里斯多德的傳承，因此不是一個孤立的「平行案例」，而是一條真實可考、串起古希臘與中世紀歐洲的具體橋樑。'
    ]},

  { id:'ibnrushd', gen:'philosophy', zh:'伊本・魯世德', gr:'Ibn Rushd (Averroes)', roman:'—', epithet:'「The Commentator」——亞里斯多德最重要的注釋者',
    year:1126, yearLabel:'1126年',
    domain:'亞里斯多德注釋、理性與信仰的調和', symbol:'羽毛筆與亞里斯多德全集', parents:[], links:['aristotle','ibnsina'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'伊本・魯世德出生於安達魯西亞的哥多華，為亞里斯多德幾乎所有現存著作撰寫了詳盡的注釋，中世紀歐洲學者甚至直接尊稱他為「The Commentator」（注釋者），他的注釋本經翻譯傳入歐洲後，深刻影響了多瑪斯・阿奎那等經院哲學家，是連接古希臘理性主義與中世紀歐洲思想的關鍵人物。',
    fullStory:[
      '伊本・魯世德出生於伊斯蘭統治下的西班牙哥多華，一生擔任法官、醫師與哲學家等多重身分，深受當時哈里發的賞識與器重。他窮盡畢生心力，為亞里斯多德現存的幾乎每一部重要著作——從《物理學》到《形而上學》，從《靈魂論》到《尼各馬可倫理學》——都撰寫了詳盡的逐句注釋，試圖釐清這位古希臘哲人原本的思想脈絡。',
      '伊本・魯世德最具爭議、也最具影響力的立場，是他主張理性與宗教信仰之間並不必然衝突——哲學透過理性推論所得出的真理，與宗教啟示所揭示的真理，最終應當殊途同歸。這個立場在當時的伊斯蘭世界引發極大爭議，他晚年一度因此遭到流放，著作也曾被下令焚毀；然而，這套「理性與信仰可以調和」的論證方式，卻在傳入歐洲後，深刻影響了多瑪斯・阿奎那等經院哲學家，成為中世紀歐洲重新接納亞里斯多德理性主義的重要理論基礎。',
      '中世紀歐洲學者對伊本・魯世德的注釋工作極為推崇，甚至直接尊稱他為「The Commentator」，彷彿他與亞里斯多德本人已合而為一——但丁在《神曲》裡，也特地將他安排在地獄邊境「靈薄獄」中，與其他偉大的異教哲學家並列，這是但丁筆下對非基督徒智者所能給予的最高敬意。伊本・魯世德的故事，某種程度上也提醒著我們：西方引以為傲的「理性主義」傳統，其實有很長一段時間，是被伊斯蘭世界的學者小心翼翼地保存、傳承下來的。'
    ]},

  { id:'seneca', gen:'philosophy', zh:'塞內卡', gr:'Seneca', roman:'—', epithet:'尼祿皇帝的老師，寫信像發微信的斯多葛哲學家',
    year:-4, yearLabel:'約西元前4年',
    domain:'斯多葛哲學、書信文學、悲劇寫作', symbol:'卷軸與毒堇', parents:[], links:['stoicism'],
    astro:'目前沒有廣為人知的正式天體命名，但有一顆小行星以他為名：4154 Rafihtar（以表彰一位現代天文學家）。',
    story:'塞內卡是羅馬尼祿皇帝的導師與朝臣，以一系列寫給朋友的書信聞名於世——那些信讀起來就像古代的 WhatsApp 群發，毒舌、溫暖、又極度誠實。他在尼祿統治初期曾是帝國真正的主導者，卻最終被迫以切開靜脈的方式結束生命。',
    fullStory:[
      '塞內卡生於西班牙科多華的羅馬家庭，少年時被父親送到羅馬接受修辭學與哲學訓練，一度涉入當時的政治鬥爭，據說差點被皇帝克勞狄烏斯處死，最後流放到科西嘉島度過了八年艱難的流放歲月。返國後，他成為年幼的尼祿的導師，並在尼祿即位初期以「攝政」角色實質掌控帝國政務長達數年，直到與尼祿的關係日漸惡化，選擇急流勇退、隱居起來撰寫哲學著作與悲劇。',
      '他的斯多葛哲學論著，其實更接近寫給朋友的私人書信——他在一百二十四封信中，與一位名叫路西里烏斯的友人，討論死亡、悲傷、憤怒、奢侈、閒暇、疾病等人生主題，語氣輕鬆自然，絲毫沒有學院派的生硬，讀起來就像兩千年前的群組聊天紀錄。他在信中說：「你不該為明天的船會沈而今晚睡不著覺——何況這艘船有三分鐘前才沈過，你不是還好好活著嗎？」也說：「我開始感覺老年並沒有那麼糟——至少它終於讓人對『別人怎麼看我』這件事，完全失去了興趣。」',
      '塞內卡最終還是沒能逃過尼祿的清算：西元65年，有人密謀暗殺尼祿失敗，尼祿懷疑塞內卡也涉入其中，命人送達死刑命令。塞內卡平靜地接受，與妻子一同切開手腕上的靜脈，據說在等待失血過多的漫長過程中，仍口述著最後的哲學對話，直到生命終結。他的妻子龐培亞・保利娜起初決定陪他一同赴死，後來被家人及僕從救下，傳說她的傷口癒合後，始終保持著蒼白的面色——彷彿丈夫死亡的那一刻，也在她身上留下了永久的印記。'
    ]},

  { id:'marcusaurelius', gen:'philosophy', zh:'馬可・奧理略', gr:'Marcus Aurelius', roman:'同名', epithet:'羅馬皇帝寫的私人日記，死後才被發現是傳世名著',
    year:121, yearLabel:'121年',
    domain:'斯多葛哲學、帝王統治', symbol:'皇帝盔甲與《沉思錄》', parents:[], links:['stoicism','seneca'],
    astro:'近地小行星46610 Bésixdouze，便以《沉思錄》中反覆出現的「沉思」（Bésixdouze = B six douze = be 6 12 = be 6/12 = 6月12日，馬可・奧理略的生日）為名。',
    story:'馬可・奧理略被歷史學家稱為「五賢帝」中最賢明的君主，統治期間羅馬帝國持續繁榮；但諷刺的是，他本人寫的《沉思錄》，恰恰是對這段繁榮背後戰爭與苦難最誠實的私人記錄——也是一份斯多葛哲學最動人的實踐樣本。',
    fullStory:[
      '馬可・奧理略生於羅馬一個西班牙裔貴族家庭，從小被皇帝安東尼・庇護收養為養子，並與其女成婚，年僅十九歲便成為羅馬帝國共同執政的皇帝。他統治的時代，正好是羅馬帝國歷史上所謂的「五賢帝時期」的尾聲——羅馬疆域最遼闊、政治最穩定、文化最繁榮的年代；然而他自己對這段經歷的私人記錄，卻充满了戰爭、瘟疫、叛亂的陰影：《沉思錄》的開篇第一章，便是他對自己各個監護人與導師的感激，讀起來像是清單式的年終檢討，但清單裡的每一位，都在他日後的執政歲月裡陸續凋零。',
      '《沉思錄》並非他打算發表的著作，而是寫給自己的私人札記，死後才被下屬發現、公開傳世——這也正是它讀起來如此真實、毫無修飾的原因。他在其中反复提醒自己：帝王的權力看似巨大，卻操控不了任何人的死亡時間；皇帝的命令看似能改變一切，卻改變不了「這一切遲早都會過去」這個事實。他在戰場的營帳裡寫，在瘟疫蔓延時寫，在兒子叛逆、盟友背叛、元老院陽奉陰違的夾縫中寫——用斯多葛的框架，試圖讓自己在每一個足以讓人崩潰的處境裡，仍能保持清醒。',
      '然而，也正是這位被後世尊為「哲學家皇帝」的馬可・奧理略，在統治期間曾多次下令迫害早期基督教信徒——這個決定，後來被歷史學家解讀為一種政治考量：基督教拒絕向羅馬神明獻祭，對當時處於動盪中的帝國而言，這種「不服從」本身便是威脅。這個悖論至今仍是道德哲學裡最值得深思的問題之一：一個在私人日記裡寫滿仁慈與理性的人，在公開的政治決策中，何以做出與自己信念相悖的選擇？是環境所迫，還是人性本就有這樣的裂縫？'
    ]},

  // ---------- MODERN ECHOES OF MYTH ----------
  { id:'narcissus', gen:'mythconcepts', zh:'那西瑟斯', gr:'Narcissus', roman:'同名 Narcissus', epithet:'愛上自己倒影的美少年',
    domain:'自戀、自我迷戀', symbol:'水仙花與池水倒影', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名，但他化身而成的水仙花（Narcissus），其屬名至今仍直接沿用他的名字。',
    story:'那西瑟斯是一位容貌俊美到近乎詛咒的青年，因拒絕了森林仙女厄科的愛慕而遭到報應之神懲罰，最終愛上自己映在水面上的倒影，終日凝視、無法自拔，憔悴而死，化為水仙花。他的名字後來成為「自戀」（narcissism）一詞的直接由來。',
    fullStory:[
      '那西瑟斯生來容貌絕美，卻對任何追求者的愛意都無動於衷，甚至冷酷拒絕。山林仙女厄科深深愛上了他，卻因自身所受的詛咒——只能重複他人說過的話尾——無法親口表白，最終在絕望中日漸消瘦，直至只剩一縷回聲留存人間。這樣的冷酷傷透了無數仰慕者的心，其中一人向報應女神涅墨西斯祈求，希望那西瑟斯有朝一日也能嚐到得不到回應的愛情之苦。',
      '涅墨西斯應允了這個祈求，引導那西瑟斯來到一池清澈見底的泉水邊。他俯身飲水時，第一次看見了自己的倒影，卻誤以為那是水中住著的另一位絕美青年，當場墜入愛河。他日夜守在池畔，凝視著這份注定得不到回應的愛情，不吃不喝，最終憔悴而死，屍身所在之處長出了一株低垂的花朵，後人便以他的名字稱之為「水仙」（Narcissus）。兩千多年後，心理學家借用他的名字，將「過度自我沈迷、缺乏同理心」的性格特質命名為「自戀」（narcissism），讓這則古老的悲劇，意外成為現代心理學最常用的詞彙之一。',
      '值得一提的是，現代臨床心理學裡的「自戀型人格」，成因遠比神話所暗示的複雜得多——許多研究認為，過度自戀往往源自童年時期缺乏穩定的情感回應、甚至是一種掩蓋深層自卑感的防衛機制，而非單純的「愛上了自己」。神話給了我們一個好記的名字，卻也可能讓我們把複雜的心理成因，過度簡化成一則單薄的警世寓言。',
      '放到今天，那西瑟斯的故事讀起來格外眼熟——一個人愛上了自己的「投影」，卻認不出那終究不是真實的自己，只是一片水面反射出的影像，最終為此耗盡了生命。心理學家借用他的名字命名「自戀」，某種程度上，也預言了兩千多年後，人們捧著手機、對著鏡頭裡經過濾鏡修飾的自己反覆凝視，卻越看越感到空虛的處境——只是那西瑟斯的水面，換成了一面會發光、還能被按讚的螢幕。'
    ]},

  { id:'echo', gen:'mythconcepts', zh:'厄科', gr:'Echo', roman:'同名 Echo', epithet:'只能複誦他人話語的仙女',
    domain:'聲音、回聲、單戀', symbol:'空谷回音', parents:[], links:['narcissus'],
    astro:'1960年代，NASA曾發射兩枚以「回聲」為名的通訊衛星「Echo 1」與「Echo 2」——它們是巨大的鍍鋁氣球衛星，本身不主動發送訊號，只是被動反射地面發出的無線電波，正如同厄科這個名字所象徵的「只能反射、無法主動發聲」的特質。',
    story:'厄科是一位山林仙女，因故被赫拉詛咒只能重複他人話語的最後幾個字，無法表達自己真正的心意。她深愛著那西瑟斯，卻因這道詛咒無法親口告白，最終在絕望中形銷骨立，只留下聲音回蕩山林之間。',
    fullStory:[
      '傳說厄科原本口才伶俐，時常以滔滔不絕的閒談，拖延赫拉發現宙斯在山林中與其他仙女幽會的時機。赫拉識破後震怒，對她下了一道殘酷的詛咒：從此她再也無法主動開口說話，只能重複別人剛剛說過的最後幾個字。',
      '這道詛咒讓厄科的命運與那西瑟斯的悲劇緊緊纏繞在一起——她深深愛上了那西瑟斯，卻無論如何都無法親口表達愛意，只能徒勞地重複他說出的話語尾聲，眼睜睜看著心上人誤解自己、轉身離去。傷心欲絕的厄科逐漸退隱山林深處，形銷骨立，最終只剩下聲音留存於世——每當有人在空谷中呼喊，聽見的回音，據信正是厄科仍在原地，重複著她再也無法親口說出的思念。',
      '後世的女性主義文學批評，也常將厄科的遭遇解讀為一則關於「聲音被剝奪」的隱喻——她因為說話而受懲罰，此後只能重複他人說過的話、無法表達自己原創的思想。這個意象與女性在漫長歷史中，聲音屢屢被邊緣化、只能附和而非主導論述的處境，形成了一種令人不安的呼應。'
    ]},

  { id:'sisyphus', gen:'mythconcepts', zh:'西西弗斯', gr:'Sisyphus', roman:'同名 Sisyphus', epithet:'永恆推石的懲罰者',
    domain:'徒勞、反抗命運', symbol:'巨石與陡坡', parents:[], links:['persephone'],
    astro:'近地小行星1866 Sisyphus便以他為名，是一顆體積龐大、軌道會週期性接近地球的小行星。',
    story:'西西弗斯生前多次以狡詐手段欺騙死神與冥王，甚至一度成功逃離冥界，死後諸神為懲罰他的傲慢，罰他將一塊巨石推上山頂，石頭卻總在抵達頂點前滾落，如此永無止境地重複，成為「徒勞」最經典的象徵。',
    fullStory:[
      '西西弗斯是科林斯的建城者，以狡黠機智聞名，卻也因屢次欺瞞諸神而惹禍上身。傳說死神塔納托斯奉命前來取他性命時，西西弗斯竟設計將死神本人反鎖進了鎖鏈之中，導致世間再無人能夠死去，直到戰神阿瑞斯出面解救死神，秩序才得以恢復。他甚至在被押送至冥界後，說服冥后波瑟芬妮讓自己暫返人間處理「未完成的喪禮」，一去便再也不肯回頭，直到眾神再度出手強行帶回。',
      '諸神對他這般一而再、再而三挑戰死亡秩序的傲慢忍無可忍，判處他一項特殊的永恆懲罰：將一塊巨石推上陡峭的山頂。然而每當石頭即將抵達頂點，總會不受控制地滾落回山腳，迫使西西弗斯必須從頭再來，永無止境、毫無意義地重複下去。二十世紀哲學家卡繆更以《薛西弗斯的神話》一書，將這個看似絕望的懲罰重新詮釋為一則關於「即使明知徒勞，依然選擇繼續前行」的存在主義寓言，賦予了這則古老懲罰全新的哲學意義。',
      '「薛西弗斯式的處境」如今也常被借用來描述現代社會裡，日復一日、看不到意義與盡頭的重複性勞動——如果把這則神話搬進現代辦公室，西西弗斯的處境其實意外地眼熟：每天把「巨石」（業績、KPI、收件匣裡永遠清不完的郵件）推上山頂，隔天一早，石頭又滾回了山腳，一切必須重新開始。卡繆說「我們必須想像薛西弗斯是幸福的」，某種程度上，正是想告訴每一個被困在這種循環裡的人：意義不必等到石頭真的停在山頂那一刻才出現，它也可以就發生在「推」這個動作本身之中。'
    ]},

  { id:'midas', gen:'mythconcepts', zh:'邁達斯', gr:'Midas', roman:'同名 Midas', epithet:'點石成金的貪婪之王',
    domain:'財富、貪婪、教訓', symbol:'金手指與驢耳朵', parents:[], links:['pan'],
    astro:'近地小行星1981 Midas便以他為名。',
    story:'邁達斯國王因善待酒神的老師西勒諾斯，獲戴歐尼修斯賜予「點石成金」的能力，卻很快發現連食物與親人一觸即化為黃金，痛苦不堪，只得請求收回這項祝福。後來他又因評判音樂比賽時偏袒牧神潘，被阿波羅懲罰長出一對驢耳朵。',
    fullStory:[
      '邁達斯是弗里吉亞的國王，一次善心收留了迷路醉倒的西勒諾斯（酒神戴歐尼修斯的老師與養父），並將他妥善送回戴歐尼修斯身邊。戴歐尼修斯為了答謝，允諾實現他的一個願望，邁達斯不假思索，許願自己碰觸的一切都能化為黃金。起初他欣喜若狂，然而很快發現，連食物、水，甚至自己心愛的女兒，一觸之下也全都化成了冰冷的金像，這份貪婪帶來的祝福瞬間變成了無法解除的詛咒，邁達斯只得含淚向戴歐尼修斯求饒，最終在河中沐浴才得以洗去這項能力。',
      '這位國王的貪念似乎並未就此止息——多年後，他受邀擔任牧神潘與太陽神阿波羅之間一場音樂比賽的評審，潘以蘆笛演奏，阿波羅則以七弦琴應戰。邁達斯認為潘的曲調更加動聽，公開評判潘獲勝，此舉徹底激怒了阿波羅，一怒之下將邁達斯的雙耳變成了驢耳朵，作為對他缺乏音樂鑑賞力的懲罰——「邁達斯的觸摸」（Midas touch）如今仍被用來形容那些看似點石成金、卻也可能因貪婪而自食惡果的人。',
      '有意思的是，「邁達斯的觸摸」這個說法，在現代商業語境裡經常被完全正面地使用——形容一個人似乎做什麼都能成功獲利，這與神話原本「貪婪終將反噬」的警世意涵，恰好形成了一種耐人尋味的反轉。'
    ]},

  { id:'oedipus', gen:'mythconcepts', zh:'伊底帕斯', gr:'Oedipus', roman:'同名 Oedipus', epithet:'無意間應驗的可怕預言',
    domain:'命運、弒父娶母的悲劇', symbol:'人面獅身的謎題', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'底比斯王子伊底帕斯出生時便被預言將弒父娶母，父母因此將他遺棄山野，卻未能阻止命運——他在不知情的狀況下長大成人，最終應驗了整則預言，成為西方文學史上關於命運不可違抗最著名的悲劇原型。',
    fullStory:[
      '底比斯國王拉伊俄斯得到神諭警告，自己將被親生兒子所殺，驚恐之下命人將剛出生的伊底帕斯棄置荒山，並刺穿他的腳踝加以確保（「伊底帕斯」之名，正意為「腫脹的腳」）。然而嬰兒被牧羊人所救，轉送至科林斯王室撫養長大，伊底帕斯始終不知自己的真實身世。成年後，他同樣從神諭得知自己命中注定弒父娶母，驚駭之下離開了他一直以為是親生父母的科林斯王室，卻在逃亡途中的岔路口，與一位素不相識的老者發生爭執，失手將其殺死——那人正是他從未謀面的親生父親拉伊俄斯。',
      '伊底帕斯其後解開了獅身人面獸斯芬克斯的著名謎題，拯救了陷入危機的底比斯城，並依照當地習俗，迎娶了守寡的王后——他的親生母親約卡絲塔，兩人在毫不知情之下共同生活多年、育有子女。真相大白之日，約卡絲塔羞愧自縊，伊底帕斯則親手刺瞎雙眼，自我放逐流浪至死。這則故事後來被心理學家佛洛伊德借用，命名為「伊底帕斯情結」，用以描述兒童在成長過程中，對異性父母產生的潛意識依戀，成為精神分析學說中最具爭議、也最廣為人知的概念之一。',
      '值得注意的是，人類學家馬凌諾斯基曾在研究美拉尼西亞初步蘭群島的母系社會後提出質疑：當地男孩對母親的依戀與對父親的敵意模式，與佛洛伊德描述的「伊底帕斯情結」並不吻合，暗示這套理論或許並非放諸四海皆準的人類天性，而更可能是特定父權社會結構下的產物。'
    ]},

  { id:'pygmalion', gen:'mythconcepts', zh:'皮格馬利翁', gr:'Pygmalion', roman:'同名 Pygmalion', epithet:'愛上自己雕像的雕刻家',
    domain:'藝術、理想化的愛', symbol:'象牙雕像', parents:[], links:['aphrodite'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'皮格馬利翁是塞浦路斯的雕刻家，因對女性感到失望而終身不娶，卻用象牙雕出一尊心目中完美的女性雕像並深深愛上她，阿芙蘿黛蒂為其真情所感動，將雕像賦予生命，兩人結為連理。',
    fullStory:[
      '皮格馬利翁對周遭女性的言行舉止感到深深失望，因此發誓終生不娶，卻將這份未能安放的情感，全數投注於雕刻藝術之中。他耗費心血雕出一尊以象牙製成的女性雕像，容貌之完美遠超凡間女子，皮格馬利翁竟不由自主地愛上了自己親手創造的作品，每日為她穿戴飾物、輕聲訴說情話，儼然將她當作真實的戀人相待。',
      '在阿芙蘿黛蒂的節慶祭典上，皮格馬利翁向愛神獻上祭品，怯生生地祈求能覓得一位如自己雕像般完美的妻子。阿芙蘿黛蒂被他這份真摯的情感打動，返家後便讓雕像逐漸有了溫度與呼吸，最終化為真正的血肉之軀，皮格馬利翁如願娶她為妻。這則故事後來被社會心理學界借用，發展出「畢馬龍效應」（Pygmalion effect）的概念，指出當人們對他人抱持較高的期待時，對方的表現也往往會隨之提升——正如皮格馬利翁全心投注的期望，最終真的將冰冷的雕像化為了有生命的真實。',
      '從現代視角重新檢視，這則故事其實也帶著令人不安的意涵——他愛上的並非一個真實、有主體性的女性，而是自己親手雕塑、完全符合個人理想的產物。這類「男性形塑理想女性」的敘事母題，後世也屢屢被文學與性別研究學者提出批判性的重新解讀，例如蕭伯納同名劇作《賣花女》，便刻意翻轉了這個框架，讓「被雕塑」的一方逐漸奪回自己的聲音與主體性。'
    ]},

  { id:'cassandra', gen:'mythconcepts', zh:'卡珊德拉', gr:'Cassandra', roman:'同名 Cassandra', epithet:'無人相信的預言家',
    domain:'預言、不被採信的真相', symbol:'月桂枝與空洞的雙眼', parents:[], links:['apollo'],
    astro:'主帶小行星114 Cassandra便以她為名。',
    story:'卡珊德拉是特洛伊公主，因拒絕太陽神阿波羅的求愛，被降下詛咒：她的預言永遠真實無誤，卻永遠不會有人相信。她曾多次準確預警木馬計的危險，卻始終無人理睬，眼睜睜看著自己的城邦走向毀滅。',
    fullStory:[
      '卡珊德拉容貌美麗，太陽神阿波羅為了追求她，賜予她準確預知未來的能力。然而當阿波羅索求她的愛意作為回報時，卡珊德拉卻拒絕了他。阿波羅雖無法收回已經賜下的預言之力，卻在盛怒之下追加了一道殘酷的詛咒：她的每一句預言都將絕對真實，卻永遠不會有任何人相信她。',
      '這道詛咒讓卡珊德拉的一生充滿了旁人無法理解的痛苦——她曾準確預言帕里斯將為特洛伊帶來滅頂之災，也曾聲嘶力竭地警告眾人，那匹留在城外的木馬裡藏著希臘士兵，然而城中上下無一人願意採信她的警告，最終眼睜睜看著自己深愛的城邦在烈焰中淪陷。她的名字後來被心理學界借用，發展出「卡珊德拉情結」一詞，用以形容那些明明看清了即將發生的危機、卻不斷被身邊人忽視或否定的處境。',
      '「卡珊德拉的處境」如今也經常被借用來描述當代社會中，那些提早示警卻不被重視的聲音——例如氣候科學家多年來提出的警告，往往要等到災難真正發生後，才被社會認真看待，這種「說對了卻沒人聽」的無力感，與卡珊德拉的詛咒遙相呼應。'
    ]},

  { id:'daedalus', gen:'mythconcepts', zh:'代達洛斯', gr:'Daedalus', roman:'同名 Daedalus', epithet:'巧奪天工的發明家與工匠',
    domain:'工藝、發明、迷宮建築', symbol:'蠟翼與工具箱', parents:[], links:['theseus'],
    astro:'近地小行星1864 Daedalus便以他為名；二十世紀七〇年代，英國星際協會提出一項名為「代達洛斯計畫」（Project Daedalus）的無人星際探測船概念設計，同樣借用了他的名字，象徵人類渴望突破自身極限、飛向未知的雄心。',
    story:'代達洛斯是傳說中技藝最精湛的工匠與發明家，曾為克里特國王米諾斯建造關押牛頭怪彌諾陶洛斯的迷宮，後來又協助忒修斯的戀人亞莉阿德妮想出以線團逃出迷宮的辦法，因此觸怒米諾斯，被囚禁於自己建造的迷宮之中。',
    fullStory:[
      '代達洛斯技藝超群，是傳說中希臘世界最偉大的工匠與發明家，曾受克里特國王米諾斯之託，建造了一座錯綜複雜、令人一旦踏入便再也無法找到出口的迷宮，用以囚禁人身牛頭的怪物彌諾陶洛斯。然而後來忒修斯前來挑戰迷宮，代達洛斯私下向公主亞莉阿德妮獻策，教她以線團繫在入口、一路展開的辦法，助忒修斯成功逃出生天，此舉觸怒了米諾斯，代達洛斯與年幼的兒子伊卡洛斯雙雙被囚禁在自己建造的迷宮高塔之中。',
      '為了逃離克里特島，代達洛斯以羽毛與蜂蠟，為自己與兒子伊卡洛斯各自製作了一雙翅膀，並在起飛前反覆叮囑兒子：飛行時切勿飛得太低，以免海水的濕氣沾濕羽翼；也切勿飛得太高，以免驕陽融化蜂蠟。代達洛斯本人謹守告誡，安然飛抵西西里島，然而年輕氣盛的伊卡洛斯卻在飛行中越飛越高，最終因蜂蠟融化墜海身亡——這對父子的故事，此後成為西方文化中談論「技藝的極限」與「年少輕狂的代價」時，最常被引用的一則寓言。',
      '值得深思的是，代達洛斯本人的形象其實相當複雜——他既是被囚禁的受害者，卻也是那座囚禁無數犧牲者的迷宮的建造者，甚至間接導致了自己兒子的死亡。這種「發明者未必能控制自己創造物後果」的處境，讓這則神話常被引用來討論科技與工藝倫理：工匠的巧手，究竟該為其創造物的濫用或失控負上多少責任？'
    ]},

  { id:'icarus', gen:'mythconcepts', zh:'伊卡洛斯', gr:'Icarus', roman:'同名 Icarus', epithet:'飛得太靠近太陽的少年',
    domain:'野心、警世、飛行的渴望', symbol:'融化的蠟翼', parents:['daedalus'],
    astro:'近地小行星1566 Icarus正以他為名——這顆小行星的橢圓軌道會週期性地將它帶到極度靠近太陽的位置，軌道特性與這則「飛得太靠近太陽」的神話意象不謀而合。',
    story:'伊卡洛斯與父親代達洛斯一同以蠟製羽翼逃離克里特島，卻在飛行途中被自由飛翔的興奮沖昏頭，不顧父親警告越飛越高，最終蜂蠟遭陽光融化，墜海而亡，成為西方文化中警示「野心過度、不聽勸告終將招致毀滅」最經典的寓言形象。',
    fullStory:[
      '伊卡洛斯與父親代達洛斯一同從克里特島的囚禁高塔一躍而下，展開了人類（在神話中）首次以人工翅膀飛行的壯舉。起初，他確實依照父親的叮囑，謹慎地飛在安全的高度，然而隨著飛行漸入佳境，那份掙脫地心引力、翱翔天際的暢快感逐漸沖昏了他年輕的頭腦，他忘卻了父親的告誡，一路振翅向上，只想再靠近太陽一點、再靠近天空一點。',
      '結果正如父親所預言，過度的高溫融化了固定羽毛的蜂蠟，一根根羽毛從他的雙臂間脫落飄散，伊卡洛斯在毫無預警之下急速墜落，最終葬身於後世以他命名的「伊卡里亞海」之中。代達洛斯回頭尋找兒子的身影，只看見漂浮於海面上的片片羽毛，悲痛萬分卻已無力回天。這則故事此後成為警示世人「過度的野心與不聽勸告終將招致毀滅」最經典的寓言，「像伊卡洛斯一樣飛得太高」，至今仍是西方語言中形容年少輕狂、不知節制的常見比喻。',
      '不過，現代也有不少重新詮釋，試圖為伊卡洛斯的形象平反——這些解讀認為，傳統上把這則神話簡化為「別太貪心、安分守己」的保守教訓，卻忽略了伊卡洛斯至少真正體驗過飛翔的自由與狂喜。這種帶有浪漫色彩的重讀，反而讚頌他勇於追求極限的勇氣，而非單純責怪他咎由自取。',
      '「飛得太高」這個意象，放到今天，幾乎可以直接套用在無數新創公司或個人生涯的故事上——初嚐成功的暢快感，往往最容易讓人忘記前輩當初的提醒，一路衝得太快、太急，直到「蠟」（資源、耐心、風險控管）耗盡的那一刻，才驚覺自己早已飛得比安全範圍還要高。伊卡洛斯的悲劇從來不是「他飛了」，而是「他忘了留意自己正在飛」——這或許才是這則神話留給每個野心勃勃的人，最實用的一句提醒。'
    ]},

  { id:'procrustes', gen:'mythconcepts', zh:'普洛克路斯忒斯', gr:'Procrustes', roman:'同名 Procrustes', epithet:'強迫旅人符合床鋪的惡漢',
    domain:'強制齊一、扭曲的公平', symbol:'鐵床與利斧', parents:[], links:['theseus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'普洛克路斯忒斯是盤據在雅典近郊的強盜，會邀請路過的旅人留宿，卻強迫每個人都必須「剛好符合」自己的鐵床尺寸——身高不足者被強行拉長至斷裂，身高過高者則被截去雙腳，最終被前往雅典途中的英雄忒修斯所剷除。',
    fullStory:[
      '普洛克路斯忒斯自稱是熱情好客的旅店主人，會主動邀請路過的旅人留宿一晚，並提供一張看似舒適的鐵床。然而這張床暗藏玄機，他堅持每一位旅客的身形都必須與床鋪長度分毫不差——若旅人身材過矮，他便會用鐵鎚將其強行拉長至符合床長；若旅人身材過高，他則會毫不留情地砍去多餘的雙腳，聲稱這是為了讓床鋪與旅客「達到完美的契合」。',
      '這樁殘忍的勾當持續多年，直到年輕的忒修斯前往雅典投靠父親途中，途經此地識破了他的伎倆。忒修斯以其人之道還治其人之身，將普洛克路斯忒斯強行按在他自己那張鐵床上，發現這名惡漢的身形恰好與床鋪不合，便依照他向來對待旅客的方式，將他處死，為這片土地除去了一大禍害。「普洛克路斯忒斯之床」（Procrustean bed）後來成為西方語言中的常見比喻，用以形容那些不顧個體差異、強行要求所有人符合單一僵化標準的制度或做法。',
      '「普洛克路斯忒斯之床」這個意象，如今甚至被借用到統計學與資料科學領域——形容研究者為了讓數據「看起來」支持自己預設的理論，而刻意篩選、扭曲原始資料的做法，被戲稱為「普洛克路斯忒斯式的分析」，是一種學術倫理上備受警惕的陷阱。'
    ]},

  { id:'nemesis', gen:'mythconcepts', zh:'涅墨西斯', gr:'Nemesis', roman:'同名 Nemesis', epithet:'對傲慢降下報應的女神',
    domain:'復仇、公正的懲戒、天譴', symbol:'天秤與皮鞭', parents:['nyx'], links:[],
    astro:'一九八四年，部分天文學家曾提出一項假說，推測太陽可能擁有一顆尚未被發現的暗淡伴星，週期性地擾動外太陽系的彗星、進而引發地球上的週期性大滅絕事件，並將這顆假想中的天體命名為「涅墨西斯星」（Nemesis star）——儘管後續觀測始終未能證實其存在，這個大膽的假說至今仍是天文學史上一段著名的插曲。',
    story:'涅墨西斯是報應與天譴的化身，專門懲罰那些過度驕傲自滿、僭越凡人本分的人，那西瑟斯之所以會愛上自己的倒影而終致死亡，據信正是出自她的懲戒，她的名字如今已成為英語中「宿敵、剋星」的日常用語。',
    fullStory:[
      '涅墨西斯是黑夜女神倪克斯之女，象徵著宇宙秩序中不可迴避的報應法則——當凡人因幸運、美貌或成就而變得過度驕傲自滿，僭越了原本屬於凡人的本分，涅墨西斯便會降臨，以恰如其分的方式讓當事人自食惡果，恢復秩序原有的平衡。她的懲罰從不隨意，而是精準對應著每個人所犯下的過度與僭越，因此在希臘人眼中，她的存在更接近一種「宇宙自我修正」的力量，而非單純的復仇女神。',
      '那西瑟斯正是她最著名的懲戒對象之一——因他傲慢地拒絕了無數愛慕者，涅墨西斯便引導他愛上了自己水中的倒影，讓他嚐到求而不得的滋味，最終為此付出生命的代價。時至今日，「涅墨西斯」（Nemesis）這個名字已經完全融入日常英語之中，成為「宿敵」、「剋星」的代名詞，用來形容那個總能精準命中自己弱點、彷彿命中注定要與自己抗衡到底的對手。',
      '值得留意的是，現代日常用語裡的「nemesis」，已經幾乎完全失去了神話原本「因傲慢而招致的正當報應」這層道德意涵，單純變成了「勢均力敵的對手」的代稱——這也是許多神話詞彙進入日常語言後，逐漸被抽離原始脈絡、只留下表面形象的常見現象。'
    ]},

  { id:'tantalus', gen:'mythconcepts', zh:'坦塔羅斯', gr:'Tantalus', roman:'同名 Tantalus', epithet:'永遠可望不可即的懲罰',
    domain:'慾望、匱乏、永恆的折磨', symbol:'觸手可及卻退去的果實與流水', parents:['zeus'], links:[],
    astro:'近地小行星2102 Tantalus便以他為名；此外，化學元素「鉭」（Tantalum，元素符號Ta）同樣以他命名——由於這種金屬即使浸泡在強酸中也幾乎完全不受腐蝕，科學家認為這種「怎麼樣都無法真正侵蝕它」的特性，恰好呼應了坦塔羅斯永遠求而不得的處境。',
    story:'坦塔羅斯是宙斯之子，因褻瀆諸神、將自己的兒子珀羅普斯烹殺獻祭以試探神明的全知，被打入冥界深處，罰他站在及頸的水中、頭頂垂掛著纍纍果實，然而每當他想飲水或摘果，水便退去、果實便升高，令他永遠陷於觸手可及卻始終得不到的折磨之中。',
    fullStory:[
      '坦塔羅斯是宙斯之子，一度深受眾神寵愛，甚至獲准與諸神同席飲宴。然而他卻利用這份殊榮，犯下了希臘神話中數一數二駭人聽聞的罪行——為了測試諸神是否真的無所不知，他將親生兒子珀羅普斯殺害烹煮，端上宴席獻給諸神享用。眾神一眼識破這道殘忍的陷阱，唯有正因喪女悲痛而心不在焉的狄蜜特，不慎咬了一口珀羅普斯的肩膀。諸神震怒之下，將珀羅普斯復活（並以一塊象牙補上了被啃食的肩膀），並對坦塔羅斯降下了永世不得解脫的懲罰。',
      '坦塔羅斯被打入冥界深處，站立在及下巴的清澈水池之中，頭頂則垂掛著結實纍纍的果樹。然而每當他因口渴彎腰欲飲，池水便會迅速退去；每當他因飢餓伸手摘果，樹枝便會被一陣狂風吹得高不可攀——他就這樣永遠站在渴望近在咫尺、卻永遠無法真正觸及的絕望之中。英語中「tantalize」（吊人胃口、逗弄）一詞，正是直接由他的名字衍生而來，用以形容那種「明明看得見、卻始終得不到」的折磨感。',
      '耐人尋味的是，「tantalizing」這個由他衍生的形容詞，如今在日常英語裡經常被用在相當輕鬆、甚至帶點誘惑意味的語境（例如形容一道令人食指大動的甜點），與坦塔羅斯原本承受的、堪稱西方神話裡數一數二殘酷的永恆懲罰，形成了強烈的反差。'
    ]},

  { id:'psyche', gen:'mythconcepts', zh:'普緒克', gr:'Psyche', roman:'同名 Psyche', epithet:'化身為蝴蝶的靈魂',
    domain:'靈魂、心靈、真愛的試煉', symbol:'蝴蝶之翼與油燈', parents:[], links:['aphrodite','persephone'],
    astro:'主帶小行星16 Psyche是太陽系中一顆罕見、幾乎完全由金屬構成的巨大小行星，NASA已於2023年發射了以她命名的「普緒克號」（Psyche）探測船，預計於2029年抵達，近距離探索這顆可能是某顆原行星金屬核心殘骸的神祕天體。',
    story:'普緒克是一位容貌絕美的凡間公主，因美貌引來阿芙蘿黛蒂的嫉妒，卻意外與愛神厄洛斯相戀。歷經被禁止看清愛人真面目、失去他的信任、又為奪回他的心而完成一連串近乎不可能的試煉，普緒克最終獲得眾神認可，被賜予不朽，與厄洛斯永遠相守。',
    fullStory:[
      '普緒克天生美貌驚人，甚至讓凡人開始傳言她比愛神阿芙蘿黛蒂本人更加美麗，這份僭越徹底激怒了女神。阿芙蘿黛蒂派遣兒子厄洛斯前去懲罰她，讓她愛上世間最卑劣醜陋的對象，不料厄洛斯自己反倒被普緒克的美貌深深打動，暗中將她迎娶為妻——條件是普緒克永遠不得看清丈夫的真實面貌，只能在夜色中與他相會。',
      '在姊姊們的慫恿之下，普緒克終究按捺不住好奇心，趁著夜裡厄洛斯熟睡，點起油燈想一窺丈夫的容顏，卻不慎讓一滴熱蠟油滴落，燙醒了厄洛斯，他憤而離去。傷心欲絕的普緒克四處尋夫，最終來到阿芙蘿黛蒂面前，被迫完成一連串近乎不可能的試煉，包括分類堆積如山的穀物、取得冥后波瑟芬妮的美貌聖油等。她屢次瀕臨絕境，卻總能在關鍵時刻獲得援助，最終感動宙斯出面，賜予她不朽之身，讓她得以與厄洛斯以真正平等的身分永遠相守。「普緒克」（Psyche）在希臘文中正是「靈魂」之意，這則故事也因此成為西方文化裡，講述「靈魂經歷試煉、終獲昇華」最重要的原型寓言，「心理學」（psychology）一詞正是由她的名字衍生而來。',
      '榮格學派學者諾伊曼曾特別以普緒克的故事為範本，主張這則神話呈現的其實是一種「女性版本」的成長歷程——不同於坎伯所歸納、以男性英雄為原型的「英雄旅程」，普緒克面對的試煉更多是內省、耐心與情感整合，而非外向的征戰與冒險，為長期以男性經驗為預設的英雄敘事研究，提供了另一種對照視角。'
    ]},

  // ---------- MODERN THINKERS WHO BORROWED THE MYTHS ----------
  { id:'freud', gen:'psychology', zh:'佛洛伊德', gr:'Sigmund Freud', roman:'—', epithet:'精神分析學的創始人',
    year:1856, yearLabel:'1856年',
    domain:'潛意識、精神分析', symbol:'診療躺椅與雪茄', parents:[], links:['oedipus','narcissus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 180" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <rect x="0" y="70" width="300" height="110" fill="#B8C4C8" opacity="0.35"/>
      <line x1="0" y1="70" x2="300" y2="70" stroke="#5B5850" stroke-width="1" stroke-dasharray="4 3"/>
      <polygon points="150,15 175,70 125,70" fill="#FBF6E9" stroke="#A6812E" stroke-width="1.5"/>
      <text x="150" y="45" font-size="10" text-anchor="middle" fill="#2A2118">意識</text>
      <polygon points="125,70 175,70 230,160 70,160" fill="#E8D9A8" stroke="#A6812E" stroke-width="1.5"/>
      <text x="150" y="90" font-size="10" text-anchor="middle" fill="#2A2118">潛意識</text>
      <circle cx="120" cy="125" r="20" fill="#FBF6E9" stroke="#8A6D1F" stroke-width="1.2"/>
      <text x="120" y="129" font-size="9" text-anchor="middle" fill="#2A2118">本我</text>
      <circle cx="185" cy="125" r="20" fill="#FBF6E9" stroke="#8A6D1F" stroke-width="1.2"/>
      <text x="185" y="129" font-size="9" text-anchor="middle" fill="#2A2118">超我</text>
      <text x="150" y="175" font-size="8" text-anchor="middle" fill="#6b5c46">冰山露出水面的，只是很小一部分</text>
    </svg>`,
    story:'佛洛伊德是精神分析學的創始人，主張人類行為深受潛意識驅力所支配。他從臨床觀察發展出「談話治療」與夢境分析等技術，試圖挖掘潛意識深處的衝突，並借用伊底帕斯與那西瑟斯的故事，為「戀母情結」與「自戀」命名，讓兩則古老神話成為現代心理學最核心的詞彙。',
    fullStory:[
      '佛洛伊德的洞見並非憑空而來，而是源自他早年在巴黎跟隨神經學家沙可研究「歇斯底里症」的臨床觀察——沙可示範了某些看似純屬生理的症狀（如癱瘓、失語），竟能透過催眠暗示誘發或消除，這讓佛洛伊德確信，心理因素能對身體產生真實的影響。返回維也納後，他與同僚布洛伊爾合作治療一位化名「安娜・歐」的年輕病患，發現讓她在半催眠狀態下盡情訴說童年創傷記憶，竟能明顯緩解症狀——安娜・歐本人將這種療法稱為「談話治療」，這正是日後整套精神分析技術的雛形。',
      '佛洛伊德進一步發展出「自由聯想法」：病人躺在診療躺椅上，卸下一切理性審查，想到什麼就說什麼，藉此讓深埋於潛意識中的衝突自然浮現。他同時將「夢」視為通往潛意識最直接的途徑，在一八九九年出版的《夢的解析》中提出：夢境表面荒誕的內容（顯夢），其實是潛意識慾望（隱夢）經過偽裝與扭曲後的產物，透過分析夢中的象徵與置換，便能逆向還原出病人真正壓抑的衝突——他甚至稱夢是「通往潛意識的皇家大道」。',
      '為了描繪心靈的內部結構，佛洛伊德晚期提出著名的「本我、自我、超我」三層模型：本我是原始、非理性、只求立即滿足慾望的衝動核心；超我是內化自父母與社會規範、扮演良知與道德審查角色的部分；自我則夾在兩者之間，必須在慾望衝動與道德約束之間反覆協調、現實地做出妥協。他也提出「防衛機制」的概念——壓抑、投射、昇華等——描述自我在面對無法承受的焦慮時，如何不自覺地扭曲現實以求自保。正是在這套結構之下，他將伊底帕斯弒父娶母的悲劇，讀解為男童在成長過程中，對母親產生潛意識依戀、並對父親心懷競爭與敵意的普遍階段，命名為「伊底帕斯情結」。',
      '這套理論體系影響了二十世紀幾乎每一個文化領域，從文學批評、電影敘事到日常語言，都留下了佛洛伊德的痕跡。然而，也正因為他的理論多半建立在少數病患的個案觀察、而非可重複驗證的科學實驗之上，當代主流心理學界對他諸多具體主張（尤其是性心理發展階段論）多持保留甚至批判態度，認為其缺乏嚴謹的實證基礎，部分論點——尤其是對女性心理的描述——更被後世女性主義學者強烈質疑。儘管如此，佛洛伊德「潛意識深刻影響人類行為」這個核心洞見本身，至今仍被視為心理學史上最具開創性、也最具爭議性的遺產之一。'
    ]},

  { id:'jung', gen:'psychology', zh:'榮格', gr:'Carl Jung', roman:'—', epithet:'集體潛意識與原型理論的提出者',
    year:1875, yearLabel:'1875年',
    domain:'集體潛意識、原型、靈魂', symbol:'曼陀羅與陰影', parents:[], links:['freud','psyche'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 180" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="150" cy="92" r="80" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <circle cx="150" cy="92" r="52" fill="#E8D9A8" stroke="#8A6D1F" stroke-width="1.3"/>
      <circle cx="150" cy="92" r="24" fill="#FBF6E9" stroke="#5B5850" stroke-width="1.3"/>
      <text x="150" y="96" font-size="9" text-anchor="middle" fill="#2A2118">自我</text>
      <text x="150" y="57" font-size="8.5" text-anchor="middle" fill="#2A2118">個人潛意識</text>
      <text x="150" y="28" font-size="8.5" text-anchor="middle" fill="#6b5c46">集體潛意識（原型）</text>
    </svg>`,
    story:'榮格原是佛洛伊德最重要的追隨者，以「字詞聯想測驗」聲名鵲起，後因理論分歧而分道揚鑣，自創「分析心理學」，提出人類共享一套跨文化的「集體潛意識」，而神話與夢境中反覆出現的角色原型（如英雄、智慧老人、陰影），正是這套集體潛意識最直接的展現。',
    fullStory:[
      '榮格在瑞士布爾霍茲利精神病院跟隨布魯勒工作期間，發展出「字詞聯想測驗」——請受試者針對一系列刺激詞彙，說出腦中浮現的第一個聯想詞，並記錄反應時間與遲疑，藉此偵測出受試者潛意識中的「情結」（complex，這個詞正是榮格所創）所在。這套實驗方法讓他聲名鵲起，也引起了佛洛伊德的注意，兩人自一九○七年起展開長達六年的密切合作與通信，佛洛伊德一度將榮格視為精神分析運動的正式接班人。',
      '然而，隨著研究的深入，榮格逐漸對佛洛伊德將幾乎一切心理現象都歸因於性慾驅力的立場感到不滿。一九一二年，他出版《無意識的心理學》，主張「libido」應被理解為更廣義的生命能量，而非單純的性衝動，這個理論分歧最終導致兩人在一九一三年徹底決裂，佛洛伊德甚至一度視此為個人背叛。榮格隨後經歷了一段被他自己稱為「與無意識的對峙」的心理低潮期，在這段時期，他大量記錄自己的夢境與幻象，這些筆記後來集結成《紅書》，成為他日後理論體系的重要源頭。',
      '榮格理論中最具原創性的貢獻，是「集體潛意識」與「原型」的概念——他主張，除了個人潛意識之外，人類還共同繼承了一套跨越文化、跨越時代的心靈結構，其中充滿反覆出現的原型角色，例如「陰影」（人格中被壓抑、不願面對的黑暗面）、「阿尼瑪／阿尼瑪斯」（心靈中的異性面向），以及「自性」（整合意識與潛意識後達成的完整人格）。他將個人畢生追求心靈整合、趨近「自性」的歷程，稱為「個體化」，並借用希臘神話中「普緒克」（靈魂）之名，將自己研究的核心對象定義為涵蓋意識與潛意識在內的完整心靈整體。',
      '榮格晚年還提出「共時性」的概念，主張某些看似巧合、卻在心理上具有深刻意義的事件關聯，未必能用單純的因果律解釋。這類理論也讓他在心理學界的評價趨於兩極——批評者認為，榮格的許多主張（尤其是集體潛意識、共時性等）缺乏可證偽的科學基礎，更接近哲學或神秘主義，而非嚴謹的實證心理學；但也正因如此，他的思想在文學、藝術、宗教研究與大眾文化領域產生了遠比正統心理學界更深遠的影響，今日廣泛使用的「內向／外向」人格分類，其源頭正是榮格早期提出的心理類型理論。'
    ]},

  { id:'camus', gen:'modernphil', zh:'卡繆', gr:'Albert Camus', roman:'—', epithet:'荒謬哲學的代言人',
    year:1913, yearLabel:'1913年',
    domain:'存在主義、荒謬、反抗', symbol:'巨石與陽光', parents:[], links:['sisyphus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 170" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <path d="M30 150 L150 50 L270 150" fill="none" stroke="#5B5850" stroke-width="2"/>
      <circle cx="150" cy="50" r="10" fill="#B5502E"/>
      <path d="M60 130 A110 110 0 0 1 240 130" fill="none" stroke="#A6812E" stroke-width="2" stroke-dasharray="6 5"/>
      <polygon points="240,130 232,120 248,124" fill="#A6812E"/>
      <text x="150" y="20" font-size="10" text-anchor="middle" fill="#2A2118">石頭快到山頂</text>
      <text x="150" y="163" font-size="9" text-anchor="middle" fill="#6b5c46">又滾回山腳，重新開始</text>
    </svg>`,
    story:'卡繆是法國哲學家與作家，在其著名論著《薛西弗斯的神話》中，將西西弗斯永恆推石的懲罰重新詮釋為人類處境的縮影——生命本身或許毫無意義，但正是在明知徒勞、仍選擇繼續推石前行的那一刻，人得以展現最高貴的反抗與自由。他本人始終拒絕「存在主義者」的標籤，並於一九五七年獲頒諾貝爾文學獎。',
    fullStory:[
      '卡繆出生於法屬阿爾及利亞的一個貧困家庭，父親在他未滿一歲時死於第一次世界大戰，他由目不識丁、幾近失聰的母親獨力扶養長大。這段在地中海陽光與貧窮之間長大的經驗，深刻形塑了他日後作品中對「身體的歡愉」與「存在的荒謬」同時抱持的敏銳感受。他曾任記者，替阿爾及爾一家左翼報紙撰稿，二戰期間更投身法國抵抗運動，主編地下報紙《戰鬥報》，在真實的歷史暴力中，進一步淬鍊出他對「荒謬」與「反抗」的思考。',
      '一九四二年，卡繆同時出版了小說《異鄉人》與哲學論著《薛西弗斯的神話》，兩部作品共同構成他所謂「荒謬三部曲」的核心（後續還有劇作《卡里古拉》）。《薛西弗斯的神話》開門見山提出一個他認為是哲學中唯一真正重要的問題：既然生命本身可能毫無客觀意義，人是否還有理由繼續活下去？他將這個處境稱為「荒謬」——意識清醒地渴望意義的人類，與一個沉默不語、毫無意義可言的宇宙之間，那道無法彌合的鴻溝。',
      '面對荒謬，卡繆逐一檢視並拒絕了兩種常見的「逃避」方式：一是肉體的自殺，直接終結這個難題；二是他所謂的「哲學式自殺」——如齊克果那樣，縱身一躍投向宗教信仰或某種超越性的意義系統，用信仰掩蓋荒謬。他主張，真正誠實的態度，是在清醒意識到生命毫無終極意義的前提下，依然選擇繼續活著、繼續反抗——而西西弗斯正是這種態度最精準的化身：他請讀者想像西西弗斯轉身走下山坡、準備再次推石的那個片刻，正是在這個清醒地知道徒勞、卻依然選擇繼續前行的瞬間，西西弗斯戰勝了自己的命運。卡繆那句著名的結語——「我們必須想像薛西弗斯是幸福的」，讓這則古老的懲罰，蛻變成關於如何在無意義的世界中活出尊嚴的經典寓言。',
      '卡繆本人始終拒絕被歸類為「存在主義者」，並與當時同樣聲名顯赫的沙特維持著時而親近、時而緊張的關係——兩人最終在一九五二年因卡繆出版《反抗者》一書公開決裂，該書批判了他認為以革命之名、卻不惜訴諸暴力與極權的左翼思潮，這個立場讓他與許多昔日戰友漸行漸遠。一九五七年，年僅四十四歲的卡繆獲頒諾貝爾文學獎，成為當時該獎項第二年輕的得主；然而僅僅三年後，他便因一場車禍猝然離世，讓後人不禁揣想，這位畢生思索「如何帶著荒謬繼續活下去」的哲學家，若能得享天年，還會為這個命題留下怎樣的答案。'
    ]},

  { id:'rosenthal', gen:'psychology', zh:'羅森塔爾', gr:'Robert Rosenthal', roman:'—', epithet:'證實「期待能改變現實」的心理學家',
    year:1933, yearLabel:'1933年',
    domain:'教育心理學、自我實現預言', symbol:'教室與成績單', parents:[], links:['pygmalion'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'羅森塔爾是美國心理學家，先以「聰明老鼠」實驗發現實驗者的期待會不自覺影響研究結果，一九六八年進一步在課堂中證實教師對學生的期待同樣能實質影響學業表現，將這則古老的雕像神話，轉化為一套經過科學檢驗、卻也持續引發爭議的心理學效應。',
    fullStory:[
      '羅森塔爾對「期待如何影響結果」這個主題的興趣，其實始於比教室更早的實驗室。一九六三年，他與同事福德進行了一項著名的「聰明老鼠」實驗：他們將基因條件完全相同的實驗室老鼠隨機分成兩組，卻分別告訴負責照顧的學生助理，一組是刻意培育、「特別聰明」的「迷宮聰慧鼠」，另一組則是「迷宮遲鈍鼠」。結果，被貼上「聰明」標籤的老鼠，在走迷宮測驗中的表現竟顯著優於「遲鈍」組——儘管兩組老鼠在生物學上毫無差異。羅森塔爾推論，這是因為學生助理在不自覺間，對「聰明」組的老鼠給予了更多、更溫柔的照料與互動。',
      '這項發現促使羅森塔爾將同樣的邏輯延伸至人類教育現場。一九六八年，他與雅各布森在一所小學進行了後來震驚教育學界的實驗：對全校學生施測一次普通的智力測驗，卻刻意告訴教師，測驗結果顯示某幾位（其實是隨機挑選、與實際成績毫無關聯的）學生「即將在學年內展現驚人的學習潛力」。一學年後，這些被隨機標記為「潛力股」的學生，成績確實出現了顯著進步，此一發現後來被寫進他與雅各布森合著的《課堂中的畢馬龍》一書，正式提出「畢馬龍效應」（或稱「羅森塔爾效應」）一詞。',
      '羅森塔爾將此現象的機制歸因於「自我實現預言」：教師在得知（其實是虛假的）期待後，會在態度、語氣、提問方式與給予的關注上，對特定學生產生細微卻持續的差別對待——更多的眼神接觸、更耐心的等待、更具鼓勵性的回饋——而學生也在這種被寄予厚望的氛圍中，逐漸活出了教師期待中的樣子。這個發現後來被廣泛延伸應用於管理學（主管對員工的期待）、心理治療（治療師對病患的期待）等領域，成為社會心理學中最常被引用的效應之一。',
      '然而，這項研究自問世以來，也始終伴隨著方法學上的爭議——後續多次獨立複製實驗，得出的效果量往往遠小於原始研究，部分學者認為原始實驗的統計方法與樣本規模存在瑕疵，效應是否真如通俗心理學書籍所描述的那般強大且普遍，至今仍有爭論。儘管如此，羅森塔爾本人後來成為心理學界推動「後設分析」（統合多篇研究、系統性檢驗效應是否穩健存在的統計方法）的先驅人物之一，某種程度上，也是他自己率先示範了科學社群該如何嚴謹地檢驗、甚至修正一項曾經轟動一時的發現。'
    ]},

  { id:'campbell', gen:'arts', zh:'坎伯', gr:'Joseph Campbell', roman:'—', epithet:'提出「英雄旅程」的神話學者',
    year:1904, yearLabel:'1904年',
    domain:'比較神話學、英雄的旅程', symbol:'千面英雄', parents:[], links:['odysseus','jung'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'坎伯是美國神話學者，深受榮格「集體潛意識」啟發，在《千面英雄》一書中比較世界各地的神話故事，歸納出一套跨文化共通的敘事結構「英雄的旅程」，這套架構後來深刻影響了現代電影劇本寫作，喬治・盧卡斯便曾公開表示《星際大戰》的故事結構深受坎伯啟發。',
    fullStory:[
      '坎伯的學術養成橫跨人類學、比較宗教學與文學，年輕時曾深受榮格「集體潛意識」與「原型」理論啟發，這個影響貫穿了他日後的整個研究方法——他相信，如同榮格所主張，世界各地的神話之所以會出現驚人相似的角色與情節模式，正是因為它們共同源自人類心靈深處某種普遍的結構。帶著這個假設，坎伯窮盡畢生心力，比較研究了從古希臘神話、北歐傳說、印度史詩到美洲原住民故事等數量龐大的英雄敘事。',
      '他在一九四九年出版的《千面英雄》一書中，提出了著名的「單一神話」（monomyth）理論，主張幾乎所有文化中的英雄故事，都遵循著大致相同的三段式結構：啟程（英雄離開熟悉的日常世界，接受冒險的召喚）、啟蒙（在陌生世界中經歷試煉、獲得導師相助、下降至最深的黑暗與恐懼）、歸來（帶著獲得的智慧或寶物回歸原本的世界，並使之煥然一新）。荷馬史詩中奧德修斯歷經十年漂泊、終於返鄉的旅程，正是這套理論最經典的範例之一。',
      '這套理論走出學術圈、真正進入大眾視野，很大程度上要歸功於坎伯晚年與記者比爾・莫耶斯合作的電視訪談系列《神話的力量》——這系列節目在他過世後不久於美國公共電視台播出，意外掀起熱潮，讓「英雄旅程」與坎伯那句廣為流傳的座右銘「跟隨你的至喜」進入了主流文化語彙。導演喬治・盧卡斯更曾公開表示，自己在構思《星際大戰》的劇本結構時，深受坎伯理論啟發，此後好萊塢無數賣座電影的劇本架構，都能看見這套敘事骨架的影子。',
      '儘管坎伯的理論在大眾文化中影響深遠，學術界對「單一神話」的評價卻相對保留——不少人類學家與神話學者批評，這套理論過度簡化、甚至有些強行套用了單一的敘事模板去解釋全世界文化背景迥異的故事，忽略了許多神話（尤其是非西方文化中，並非以個人英雄為中心的敘事傳統）根本無法被硬塞進這套三段式結構之中。這個學術上的張力，某種程度上也反映了坎伯研究方法本身的雙面性：它作為一套激發創作靈感的敘事工具極其好用，卻未必是理解世界神話多樣性最嚴謹的學術框架。'
    ]},

  { id:'botticelli', gen:'arts', zh:'波提切利', gr:'Sandro Botticelli', roman:'—', epithet:'畫出《維納斯的誕生》的文藝復興畫家',
    year:1445, yearLabel:'1445年',
    domain:'繪畫、文藝復興人文主義、神話畫', symbol:'貝殼與畫筆', parents:[], links:['aphrodite'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'波提切利是義大利文藝復興早期最重要的畫家之一，他的《維納斯的誕生》描繪愛神阿芙蘿黛蒂（羅馬名維納斯）自海中貝殼誕生的瞬間，是西方藝術史上最著名的神話題材畫作之一，直接推動了文藝復興時期重新擁抱古典神話美學的風潮。',
    fullStory:[
      '波提切利活躍於佛羅倫斯的梅第奇家族宮廷，深受人文主義思潮影響——這股思潮主張重新發掘古希臘羅馬的文化遺產，視其為人類文明的黃金典範。他大約在一四八〇年代創作的《維納斯的誕生》，描繪愛神從海中泡沫誕生、乘著一枚碩大貝殼漂向岸邊的瞬間，畫面裡的維納斯以近乎全裸的姿態現身，這在當時仍高度受教會道德規範的社會裡，是極具突破性的嘗試。',
      '這幅畫作的大膽之處，不只在於裸體本身，更在於它公然選擇了一個異教神話題材、而非當時繪畫主流的基督教聖經場景，作為創作核心。梅第奇家族對古典人文思想的贊助與支持，讓波提切利得以放手描繪這樣的題材，某種程度上，也象徵著歐洲藝術正式從中世紀的宗教框架裡，重新找回了對古希臘羅馬神話與人體之美的興趣，成為日後整個文藝復興時期，藝術家們持續回望古典神話的重要起點。'
    ]},

  { id:'caravaggio', gen:'arts', zh:'卡拉瓦喬', gr:'Caravaggio', roman:'—', epithet:'用寫實光影畫出美杜莎驚駭瞬間的巴洛克畫家',
    year:1571, yearLabel:'1571年',
    domain:'繪畫、明暗對照法、戲劇性寫實主義', symbol:'盾牌與蛇髮', parents:[], links:['medusa'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'卡拉瓦喬是義大利巴洛克時期最具革命性的畫家之一，以強烈的明暗對照與寫實到近乎殘酷的畫風聞名。他筆下的《美杜莎》，直接畫在一面凸面盾牌上，捕捉她剛被斬首、頭顱飛離軀體那一瞬間驚駭萬分的表情，是西方藝術史上最令人難忘的神話題材作品之一。',
    fullStory:[
      '卡拉瓦喬以強烈的明暗對照法（chiaroscuro）著稱——他讓畫面裡的光源顯得極其集中而戲劇化，人物彷彿從一片深沉的黑暗背景裡被猛然照亮，這種手法後來深刻影響了整個巴洛克時期的繪畫美學。他性格暴烈、行事不羈，一生多次涉入鬥毆甚至命案，最終在逃亡途中客死異鄉，是藝術史上「天才與混亂並存」最著名的例子之一。',
      '卡拉瓦喬約於一五九七年創作的《美杜莎》，是一幅畫在真實凸面盾牌上的油畫——他刻意選擇捕捉柏修斯斬下美杜莎頭顱後，她臉上尚未完全消散的驚駭與痛苦表情，鮮血從頸部噴湧而出，寫實到近乎令人不安的程度。這幅畫作後來被收藏進佛羅倫斯烏菲茲美術館，其震撼人心的寫實張力，至今仍被視為卡拉瓦喬畢生風格最極致的展現之一。'
    ]},

  { id:'rodin', gen:'arts', zh:'羅丹', gr:'Auguste Rodin', roman:'—', epithet:'為但丁《神曲》打造《地獄之門》的雕塑家',
    year:1840, yearLabel:'1840年',
    domain:'雕塑、人體、現代主義的先聲', symbol:'青銅與沉思的姿態', parents:[], links:['dante'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'羅丹是十九世紀最重要的雕塑家之一，他耗費數十年心力創作的《地獄之門》，靈感直接取自但丁《神曲・地獄篇》，門上那尊後來獨立展出、舉世聞名的《沉思者》，最初的構想正是坐在地獄門前俯瞰眾生、陷入沉思的但丁本人。',
    fullStory:[
      '羅丹在一八八〇年受法國政府委託，為一座計劃興建的裝飾藝術博物館設計青銅大門，他選擇以但丁《神曲》裡的《地獄篇》作為創作靈感，將門本身設計成但丁筆下地獄入口的具體化身，門上密密麻麻雕刻著近兩百個掙扎糾纏的人體，呈現出但丁詩中描繪的層層地獄景象。這件作品耗時超過三十七年，羅丹終其一生反覆修改，直到過世都未曾正式宣告完成。',
      '《地獄之門》上方，端坐著一尊低頭沉思的男性人像——羅丹原先的構想，是讓這個形象代表但丁本人，坐在地獄門前俯瞰下方永無止盡的苦難與掙扎，陷入深沉的思索。這尊雕像後來被羅丹單獨放大鑄造、獨立展出，並更名為《沉思者》，成為西方雕塑史上辨識度最高的作品之一——儘管世人多半只記得這尊沉思的巨人，卻很少人知道，他最初的身分，其實正是那位遊歷地獄與天堂的中世紀詩人但丁。'
    ]},

  { id:'linxi', gen:'arts', zh:'林夕', gr:'Lin Xi (Lam Chik)', roman:'—', epithet:'把佛理寫進情歌的「佛Line」詞人',
    domain:'粵語流行詞、佛學、無常', symbol:'麥克風與空性', parents:[], links:['buddha'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'林夕是香港最重要的填詞人之一，近四千首詞作裡，有一條被他自己稱為「佛Line」的創作脈絡——從一九九〇年代開始，他持續把「無常」「緣起性空」等佛學概念，包裝進看似只是談情說愛的流行歌詞裡，讓聽眾在不知不覺間，接觸到相對艱深的佛理思考。',
    fullStory:[
      '林夕本名梁偉文，是香港樂壇公認產量最豐、影響力最深遠的填詞人之一，生涯作品累積將近四千首。他在訪談裡曾坦言，自己刻意經營一條創作脈絡，戲稱為「佛Line」——早在一九八八年的作品裡，便已能追溯到佛學思想的痕跡，而一九九一年為歌手袁鳳瑛所寫的一首歌，更直接以《心經》為題，正式揭開了這條「佛Line」的序幕。',
      '一九九八年，林夕接連為王菲寫下幾首深受佛學影響的作品，他自己形容這是嘗試「用佛家精神solve戀愛的問題」——把「無常」（一切事物終將變化消逝）、「緣起性空」（萬物皆因條件聚合而生、本無固定不變的自性）這類原本屬於佛學義理的概念，轉譯進大眾能夠哼唱的情歌旋律之中。此後陳奕迅的多首金曲，都延續著這條脈絡，讓「愛情終將流轉、無法強求」這樣的佛學式體悟，成為華語流行樂壇裡意外普及的哲學啟蒙。',
      '林夕曾以《紅樓夢》作類比，說明自己的創作策略——《紅樓夢》表面上寫的是兒女私情，讀者卻不會因此認為這部經典僅止於愛情故事而已；他期許自己的情歌，也能達到類似的效果：用商業流行曲工整、易於傳唱的外殼，包裹住原本艱澀難懂的哲理，讓聽眾在反覆哼唱的過程裡，一點一滴地，被這些關於無常與放下的思考悄悄滲透。'
    ]},

  { id:'huangweiwen', gen:'arts', zh:'黃偉文', gr:'Wyman Wong', roman:'—', epithet:'把神話寓言寫進廣東歌的詞壇鬼才',
    domain:'粵語流行詞、社會觀察、寓言式書寫', symbol:'墨鏡與麥克風', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'黃偉文是與林夕齊名的香港填詞人，兩人合稱樂壇「兩個偉文」（林夕本名梁偉文），黃偉文的創作風格擅長從日常瑣事託物言志，近年也屢屢借用神話與宗教意象，描繪文明價值崩解的寓言式場景，展現出與林夕佛理路線截然不同、卻同樣深刻的哲思筆法。',
    fullStory:[
      '黃偉文與林夕合稱香港詞壇「兩個偉文」——一個巧合是，林夕的本名正是「梁偉文」，兩人的名字裡都藏著「偉文」二字。黃偉文畢業於香港中文大學社會工作系，一九九三年正式踏入填詞行業，至今累積作品超過一千兩百首，二〇一二年更於紅磡體育館一連舉辦六場「Concert YY 黃偉文作品展」演唱會，邀來超過四十位歌手同台演繹他的詞作，是香港樂壇少見以填詞人為主角的大型音樂會。',
      '相較於林夕經營的「佛Line」路線，黃偉文的哲理書寫走的是另一種路數——評論者形容他擅長「託理於物」，喜歡從一件看似平凡無奇的人事物切入，娓娓道來，不刻意艱深迂迴，卻同樣發人深省，代表作品如陳奕迅的《苦瓜》，便是以一種尋常蔬菜的滋味，隱喻人生歷練的層次變化。他也格外鍾情廣東話本身的表達力，曾提倡「廣東話運動」，主張用最生活化、最本土的語言，照樣能承載深刻的思考。',
      '近年黃偉文的創作視野更進一步延伸到宗教與神話的寓言式書寫——例如他為王菀之與Serrini所寫的《誅神的黃昏》，便借用「眾神被拉下神壇」的意象，描繪一整個文明價值崩解、粗鄙化的圖景，將「哲學被簡化」「經典被撕毀」等文化滑坡現象並置在同一首歌裡，展現出他即使在流行音樂的商業框架之下，依然能夠承載沉重而完整的文明批判視野。'
    ]},

  { id:'ovid', gen:'arts', zh:'奧維德', gr:'Ovid (Publius Ovidius Naso)', roman:'同名 Ovidius', epithet:'把希臘神話寫成《變形記》的羅馬詩人',
    year:-43, yearLabel:'西元前43年',
    domain:'敘事詩、神話改寫、變形母題', symbol:'鵝毛筆與化形之人', parents:[], links:['narcissus','pygmalion','icarus','midas'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 140" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="70" cy="60" r="20" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="70" y="64" font-size="8" text-anchor="middle" fill="#2A2118">人形</text>
      <line x1="105" y1="60" x2="195" y2="60" stroke="#5B5850" stroke-width="1.5" stroke-dasharray="4 4"/>
      <polygon points="190,55 200,60 190,65" fill="#5B5850"/>
      <circle cx="230" cy="60" r="20" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="1.5"/>
      <text x="230" y="64" font-size="8" text-anchor="middle" fill="#2A2118">花／星／獸</text>
      <text x="150" y="110" font-size="8.5" text-anchor="middle" fill="#6b5c46">形體轉變，卻留下不滅的情感印記</text>
    </svg>`,
    story:'奧維德是古羅馬詩人，他的長詩《變形記》用近一萬二千行詩句，串起兩百多則希臘羅馬神話裡「形體轉變」的故事——那西瑟斯、皮格馬利翁、伊卡洛斯這些故事，我們今日所熟悉的版本，很大程度上都是經由他的重新講述才流傳至今，他也因此深刻影響了但丁、莎士比亞等後世文豪。',
    fullStory:[
      '奧維德生活於羅馬帝國奧古斯都皇帝統治時期，一生著述豐富，其中最重要、也最具影響力的作品，是完成於西元8年前後的長篇敘事詩《變形記》。全詩以「變形」為核心母題，將希臘羅馬神話裡兩百多則零散的故事，巧妙地串聯成一部從「創世的混沌」一路寫到「凱撒封神」的宏大敘事——那西瑟斯化為水仙、皮格馬利翁的雕像獲得生命、伊卡洛斯墜海、邁達斯受懲，這些故事今日廣為人知的版本，很大程度上都是經由奧維德的生花妙筆重新講述、才得以完整流傳至今。',
      '值得一提的是，早期希臘文獻裡，這些神話往往只留下片段的引述或劇作殘篇，是奧維德將它們系統性地蒐集、串接、賦予戲劇張力與心理描寫，才讓後世讀者得以完整讀到這些故事的來龍去脈。也因此，儘管「希臘神話」這個名稱裡有「希臘」二字，我們今天所熟悉的許多細節與敘事版本，其實更接近「奧維德版本的希臘神話」，而非最原始的希臘文本。',
      '奧維德晚年因故被奧古斯都皇帝流放至黑海邊陲，客死異鄉，終身未能獲准返回羅馬——諷刺的是，他筆下無數關於「變形」與「命運無常」的故事，最終彷彿也降臨在他自己身上。他的《變形記》後來成為中世紀與文藝復興歐洲最重要的神話知識來源之一：但丁在《神曲》裡，直接讓奧維德的靈魂與荷馬同列於靈薄獄之中；莎士比亞更是讀著阿瑟・戈爾丁翻譯的英文版《變形記》長大，劇作裡大量借用了奧維德重新講述的神話意象與敘事手法。'
    ]},

  { id:'shakespeare', gen:'arts', zh:'莎士比亞', gr:'William Shakespeare', roman:'—', epithet:'把希臘神話搬上伊莉莎白舞台的劇作家',
    year:1564, yearLabel:'1564年',
    domain:'戲劇、詩歌、人性刻畫', symbol:'環球劇場與鵝毛筆', parents:[], links:['ovid','theseus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'莎士比亞自幼讀著阿瑟・戈爾丁翻譯的英文版奧維德《變形記》長大，這部譯作被公認是他一生創作靈感最重要的來源之一。他的《仲夏夜之夢》直接以雅典王忒修斯與希波呂忒的婚禮為故事框架，《特洛伊羅斯與克瑞西達》更直接改編自特洛伊戰爭的傳說。',
    fullStory:[
      '莎士比亞成長於英格蘭史特拉福，接受的是當時文法學校標準的拉丁文與古典文學教育，其中，阿瑟・戈爾丁一五六七年翻譯出版的英文版奧維德《變形記》，對他影響尤其深遠——學者普遍認為，這部譯作是莎士比亞畢生創作裡，被引用、化用次數最多的單一文學源頭，遠遠超過聖經以外的任何其他著作。',
      '這股影響在他的劇作中隨處可見：《仲夏夜之夢》整齣戲的框架，建立在雅典王忒修斯即將迎娶亞馬遜女王希波呂忒的婚禮之上，森林裡精靈與凡人之間錯亂的愛情糾葛，正是在這場婚禮的背景下展開；《特洛伊羅斯與克瑞西達》則直接取材自特洛伊戰爭的傳說，用一種近乎諷刺、解構英雄主義的筆法，重新詮釋了阿基里斯、赫克托爾等經典角色；早期詩作《維納斯與阿多尼斯》，更是直接改寫自奧維德筆下阿芙蘿黛蒂與凡人戀人的故事。',
      '莎士比亞對希臘神話的運用，很少是原封不動的複述，而是像奧維德本人一樣，把這些古老故事當成一套可以自由拆解、重組、賦予全新時代精神的敘事素材——他讓忒修斯這樣的神話英雄，在舞台上說著伊莉莎白時代的語言，思考著文藝復興時期歐洲人關切的問題。這種「用當代語言重新講述古老故事」的創作策略，某種程度上，正是奧維德留給後世最深遠的一項文學遺產。'
    ]},

  { id:'dante', gen:'arts', zh:'但丁', gr:'Dante Alighieri', roman:'—', epithet:'讓維吉爾帶路遊歷地獄的中世紀詩人',
    year:1265, yearLabel:'1265年',
    domain:'史詩、地獄結構、古典致敬', symbol:'月桂冠與《神曲》', parents:[], links:['odysseus','aristotle','ibnrushd'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'但丁的《神曲》大量借用古典神話的宇宙觀，讓羅馬詩人維吉爾親自帶領他遊歷地獄與煉獄，更在《地獄篇》裡讓奧德修斯（尤利西斯）道出一段悲壯的死亡航程，也把亞里斯多德、伊本・魯世德等異教哲人，安置在地獄邊境的「靈薄獄」裡，給予他們雖非天堂、卻依然莊嚴的位置。',
    fullStory:[
      '但丁的《神曲》一開篇，便讓自己在人生的中途、於一座幽暗森林裡迷失方向，這時前來搭救、並帶領他遊歷地獄與煉獄的嚮導，正是他心目中最崇敬的古羅馬詩人維吉爾——但丁認為，維吉爾的史詩《伊尼亞斯記》，是拉丁文學裡最接近神聖啟示的作品，選擇讓他擔任嚮導，本身便是向古典傳統致上的最高敬意。',
      '《地獄篇》第二十六篇裡，但丁讓荷馬史詩裡的奧德修斯（羅馬名尤利西斯）現身說法，講述了一段荷馬原著裡從未記載的結局：他在返鄉多年後，仍舊無法安於平靜的生活，說服年邁的水手們再度出航，一路航向世界的盡頭，越過象徵人類認知極限的「海克力斯之柱」，最終船隻在南半球的大洋裡遭遇風暴、沉沒身亡。這段但丁原創的續篇，後來深深影響了後世無數以「奧德修斯晚年」為題材的文學創作。',
      '但丁對異教徒與非基督徒智者，抱持著一種矛盾卻深情的態度——他將荷馬、奧維德、亞里斯多德、柏拉圖，乃至伊斯蘭哲學家伊本・魯世德等人，全都安置在地獄最外圍、被稱為「靈薄獄」的區域。這裡沒有火焰與酷刑，只有淡淡的哀傷——這些智者生前未曾聽聞基督福音，依照但丁的神學信念，終究無法進入天堂，但但丁仍舊給予他們遠離地獄酷刑、甚至帶有幾分莊嚴光輝的安息之地，某種程度上，也流露出他自己作為一位深受古典文化滋養的詩人，內心真正的價值排序。'
    ]},

  { id:'joyce', gen:'arts', zh:'喬伊斯', gr:'James Joyce', roman:'—', epithet:'把《奧德賽》搬進都柏林一天的現代主義小說家',
    year:1882, yearLabel:'1882年',
    domain:'意識流、現代主義、神話結構', symbol:'都柏林街景與《尤利西斯》', parents:[], links:['odysseus','campbell'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 150" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <text x="80" y="20" font-size="9" text-anchor="middle" fill="#2A2118" font-weight="bold">《奧德賽》24卷</text>
      <text x="220" y="20" font-size="9" text-anchor="middle" fill="#2A2118" font-weight="bold">《尤利西斯》18章</text>
      <circle cx="80" cy="50" r="8" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="220" cy="50" r="8" fill="#D8C9A0" stroke="#8A6D1F"/>
      <line x1="88" y1="50" x2="212" y2="50" stroke="#5B5850" stroke-width="1" stroke-dasharray="2 4"/>
      <circle cx="80" cy="80" r="8" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="220" cy="80" r="8" fill="#D8C9A0" stroke="#8A6D1F"/>
      <line x1="88" y1="80" x2="212" y2="80" stroke="#5B5850" stroke-width="1" stroke-dasharray="2 4"/>
      <circle cx="80" cy="110" r="8" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="220" cy="110" r="8" fill="#D8C9A0" stroke="#8A6D1F"/>
      <line x1="88" y1="110" x2="212" y2="110" stroke="#5B5850" stroke-width="1" stroke-dasharray="2 4"/>
      <text x="150" y="140" font-size="8.5" text-anchor="middle" fill="#6b5c46">十年漂泊，濃縮成一天</text>
    </svg>`,
    story:'喬伊斯的《尤利西斯》堪稱二十世紀文學裡，與《奧德賽》關係最直接的一次現代回應——全書十八個章節，逐一對應荷馬史詩的二十四卷結構，卻把奧德修斯歷經十年漂泊的冒險，濃縮成一位都柏林小市民在一天之內的平凡遊蕩。',
    fullStory:[
      '喬伊斯的《尤利西斯》出版於一九二二年，書名直接取自奧德修斯的羅馬名「尤利西斯」，全書描寫主角利奧波德・布魯姆在都柏林度過的極其平凡的一天——從早晨出門買早餐，到深夜返家就寢，書中幾乎每一個章節，都精心對應著《奧德賽》裡的一段情節：布魯姆走進酒館的段落，呼應著奧德修斯闖入獨眼巨人洞穴的驚險；他在報社閒晃的片刻，暗中對應著風神埃俄羅斯贈予的風袋。',
      '這種「把史詩級的英雄冒險，濃縮進一位平凡小人物一天之內的瑣碎生活」的寫法，是《尤利西斯》最核心的藝術野心——喬伊斯藉此提出一個大膽的主張：即便沒有經歷屠殺求婚者、智取獨眼巨人這般驚天動地的事蹟，一位普通人在日常生活裡所經歷的內心掙扎、感官體驗與自我對話，同樣值得用史詩等級的篇幅與細膩程度，被鄭重記錄下來。',
      '喬伊斯這套「用古老神話結構，包裹現代日常生活」的創作手法，後來與神話學者坎伯的「英雄旅程」理論，產生了跨世代的呼應——坎伯晚年甚至與人合著了一整本專門解讀喬伊斯晚期作品《芬尼根守靈夜》的研究專書。《尤利西斯》至今仍被公認是二十世紀最重要的英語小說之一，也是「古老神話能為現代創作提供什麼」這個問題，至今為止最具野心、也最完整的一次文學實驗。'
    ]},

  { id:'olympusguardian', gen:'arts', zh:'奧林匹斯星傳', gr:'Olympus Guardian (올림포스 가디언)', roman:'—', epithet:'韓國動畫重新演繹的希臘神話',
    year:2002, yearLabel:'2002年',
    domain:'動畫改編、神話普及、跨世代的兒童啟蒙', symbol:'奧林帕斯山與動畫分鏡', parents:[], links:['zeus','prometheus','pandora'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'《奧林匹斯星傳》是韓國SBS電視台於2002年推出的電視動畫，改編自漫畫《希臘羅馬神話故事》，全39集，從宙斯童年躲避父親克洛諾斯的迫害開始，一路講述泰坦之戰、普羅米修斯盜火、潘朵拉的盒子等經典篇章，是不少華語地區觀眾最早接觸希臘神話的啟蒙作品之一。',
    fullStory:[
      '《奧林匹斯星傳》改編自韓國漫畫家洪恩英於二〇〇〇年出版的《希臘羅馬神話故事》系列圖書，由南韓SBS電視台於二〇〇二年製作播出，全三十九集。動畫的敘事從宙斯的童年說起——他因父親克洛諾斯吞食子女的暴行，被母親瑞亞秘密送往克里特島撫養長大，返回奧林帕斯後聯合手足發動泰坦之戰，推翻父親的統治，開啟了眾神新時代。',
      '這部動畫在華語地區以不同譯名發行——台灣譯為《天神向前衝》、香港譯為《希臘封神榜》，中國大陸則沿用《奧林匹斯星傳》這個譯名，透過中央電視台少兒頻道播出。對不少觀眾而言，這是他們最早、也最完整接觸到希臘神話體系的媒介——劇中對普羅米修斯盜火觸怒宙斯、潘朵拉打開災禍之盒等經典篇章的改編，至今仍是許多人記憶裡希臘神話最初的模樣。',
      '值得一提的是，這部作品雖然取材自真實神話，在情節安排上仍做了不少簡化與戲劇化的改編，與各版本古典文獻的原始記載存在出入——但作為一部成功將艱澀的古典神話，轉譯成一整個世代都能輕鬆消化的視覺敘事的作品，它在希臘神話的當代普及史上，確實佔有獨特的一席之地。'
    ]},

  { id:'saintseiya', gen:'arts', zh:'聖鬥士星矢', gr:'Saint Seiya', roman:'—', epithet:'讓黃道十二宮變成戰鬥聖衣的日本漫畫',
    year:1986, yearLabel:'1986年',
    domain:'漫畫改編、黃道十二宮、少年熱血敘事', symbol:'黃金聖衣與小宇宙', parents:[], links:['athena','ophiuchus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'車田正美創作的《聖鬥士星矢》，是日本漫畫史上最具影響力的作品之一——故事裡守護女神雅典娜的「黃金聖鬥士」，正好對應黃道十二宮的十二個星座，聖域裡甚至還設有一座對應蛇夫座的「第十三宮」，與現代天文學重新計算出的「隱藏第十三星座」不謀而合。',
    fullStory:[
      '《聖鬥士星矢》是日本漫畫家車田正美於一九八六年開始連載的少年漫畫，故事設定裡，女神雅典娜為了守護人類與陸地，與覬覦大地的海皇波賽頓、冥王黑帝斯等神明展開連綿不絕的戰爭，一群秉持正義與勇氣的少年少女「聖鬥士」，身披模仿夜空星座打造而成的「聖衣」，追隨雅典娜並肩作戰。',
      '作品裡等級最高的「黃金聖鬥士」，共有十二位，各自鎮守聖域裡以黃道十二宮命名的十二座宮殿，聖衣設計與稱號，全部直接對應白羊、金牛、雙子等十二個星座——這個設定讓黃金聖鬥士的人氣，甚至一度超越了作品真正的主角青銅聖鬥士星矢。更耐人尋味的是，聖域裡其實還藏著一座「第十三宮」，對應的正是蛇夫座——這與現代天文學依照精確星座邊界重新計算後，主張黃道帶上其實存在著被傳統占星術排除在外的「第十三個星座」，形成了一次虛構創作與真實天文學知識的巧妙呼應。',
      '《聖鬥士星矢》後續推出多部動畫版本，包括二〇一九年Netflix製作的3DCG重製版《黃道十二宮戰士》，持續向新一代觀眾介紹這套將希臘神話與黃道十二宮融合重構的世界觀。這部作品也是少數同時涉及「奧林帕斯神系內部權力鬥爭」與「黃道十二宮」兩大希臘神話子題材、並將兩者巧妙編織進同一套敘事裡的大眾流行文化作品。'
    ]},

  { id:'disneyhercules', gen:'arts', zh:'大力士', gr:'Hercules', roman:'—', epithet:'迪士尼動畫重新詮釋的海克力斯',
    year:1997, yearLabel:'1997年',
    domain:'動畫改編、英雄旅程、通俗化的神話', symbol:'雷電徽記與奧林帕斯山', parents:[], links:['heracles','zeus','hera'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'迪士尼於一九九七年推出動畫電影《大力士》，將海克力斯的身世與十二項苦役大幅改編、通俗化——劇中海克力斯是宙斯與赫拉所生的親生兒子，因被冥王黑帝斯陷害才淪落凡間，這個設定與希臘神話原始版本（海克力斯是宙斯與凡人所生、正因此觸怒赫拉）恰恰相反。',
    fullStory:[
      '迪士尼動畫電影《大力士》於一九九七年上映，講述海克力斯自幼被送到凡間扶養長大、意外發現自己神族血統後，努力證明自己配得上重返奧林帕斯山、成為真神的故事。這部電影延續了迪士尼一貫的音樂劇敘事風格，將海克力斯的成長歷程，改編成一則典型的「英雄自我證明」故事。',
      '值得注意的是，電影為了服務闔家觀賞的敘事需求，對原始神話做了根本性的改動——在真正的希臘神話裡，海克力斯是宙斯與凡人女子阿爾克墨涅所生的私生子，正因如此觸怒了善妒的赫拉，才招致她一連串的迫害，包括讓他發瘋殺死自己的親生兒女，這也是他必須完成十二項苦役以贖罪的真正原因。電影版卻將海克力斯改編成宙斯與赫拉的親生嫡子，把陷害他的角色，換成了冥王黑帝斯，徹底顛倒了原始神話裡的因果邏輯與角色關係。',
      '這種大幅度的改編，某種程度上也反映了大眾流行文化在轉譯古典神話時，經常面臨的取捨——原始神話裡諸神善妒、複雜甚至殘忍的一面，往往會在追求闔家觀賞、皆大歡喜的商業考量下被大幅淡化或改寫。《大力士》因此也常被神話學者與古典學界，拿來作為討論「通俗改編可以在多大程度上偏離原始文本、卻依然被視為同一則神話」的經典案例。'
    ]},

  { id:'troymovie', gen:'arts', zh:'特洛伊', gr:'Troy', roman:'—', epithet:'拿掉諸神干預的真人版特洛伊戰爭',
    year:2004, yearLabel:'2004年',
    domain:'電影改編、史詩重述、去神話化的嘗試', symbol:'木馬與燃燒的城牆', parents:[], links:['achilles','hector','helen','paris'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'二〇〇四年上映的電影《特洛伊》，改編自荷馬史詩《伊利亞德》，卻做出了一項大膽的敘事選擇——完全拿掉了原著裡阿波羅、雅典娜等諸神親自下場干預戰局的情節，把整場戰爭改寫成一則純粹由人類的野心、愛恨與榮譽所驅動的史詩故事。',
    fullStory:[
      '電影《特洛伊》由沃夫岡・彼得森執導，改編自荷馬史詩《伊利亞德》，找來布萊德・彼特飾演阿基里斯、艾力克・巴納飾演赫克托爾，將特洛伊戰爭的故事搬上大銀幕。電影的劇情主線大致遵循原著——帕里斯拐走海倫，引爆希臘聯軍對特洛伊的圍城戰爭，阿基里斯與赫克托爾之間的宿命對決，構成了全片的敘事高潮。',
      '電影最大膽的改編，是徹底拿掉了《伊利亞德》原著裡諸神親自下場、直接介入戰局的情節——在荷馬的原始版本裡，阿波羅、雅典娜、阿芙蘿黛蒂等神祇，時常親自現身戰場，左右個別戰士的生死；電影版卻將這場戰爭，改寫成一則完全由人類自身的野心、愛恨與榮譽感所驅動的「去神話化」史詩，諸神的存在，只以角色口中的信仰與詛咒的形式被間接提及。',
      '這個改編選擇，某種程度上反映了現代觀眾對「神話該如何被搬上銀幕」的品味轉變——比起讓神祇直接下場操縱戰局的超自然敘事，當代大眾文化似乎更傾向於相信「即便沒有神明介入，人類自身的慾望與執念，也足以釀成一整場毀滅性的戰爭」，這種詮釋角度，某種程度上，也讓特洛伊戰爭的故事，讀起來更貼近現代觀眾對「歷史真實感」的期待。'
    ]},

  { id:'lacan', gen:'psychology', zh:'拉岡', gr:'Jacques Lacan', roman:'—', epithet:'高喊「回歸佛洛伊德」的精神分析重新詮釋者',
    year:1901, yearLabel:'1901年',
    domain:'精神分析、鏡像階段、語言與慾望', symbol:'鏡子與能指鏈', parents:[], links:['freud','narcissus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 170" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="90" cy="80" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="90" cy="95" r="4" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="80" cy="90" r="3" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="100" cy="88" r="3" fill="#EFE6CE" stroke="#A6812E"/>
      <text x="90" y="130" font-size="8.5" text-anchor="middle" fill="#6b5c46">破碎的身體感知</text>
      <line x1="150" y1="50" x2="150" y2="140" stroke="#5B5850" stroke-width="2"/>
      <circle cx="210" cy="85" r="22" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="2"/>
      <text x="210" y="90" font-size="9" text-anchor="middle" fill="#2A2118">完整倒影</text>
      <text x="210" y="130" font-size="8.5" text-anchor="middle" fill="#6b5c46">鏡中「誤認」出的自我</text>
    </svg>`,
    story:'拉岡是二十世紀最具爭議、也最具影響力的精神分析學家之一，他打著「回歸佛洛伊德」的旗號，卻用結構語言學徹底翻新了精神分析的語彙。他最著名的「鏡像階段」理論，主張嬰兒正是透過鏡中的倒影，才第一次拼湊出「自我」的雛形——這與那西瑟斯愛上水中倒影的神話，形成了一次意味深長的跨時代呼應。',
    fullStory:[
      '拉岡在法國精神分析學界掀起了一場堪稱「地震」的理論革命——他公開宣稱自己的工作是「回歸佛洛伊德」（retour à Freud），主張後繼的精神分析學者早已扭曲、簡化了佛洛伊德原本的洞見，唯有重新回到佛洛伊德的文本本身，才能挖掘出被忽略的深層意涵。然而諷刺的是，他「回歸」的方式，卻是引入結構語言學、黑格爾哲學等佛洛伊德本人從未使用過的全新工具，某種程度上，這場「回歸」更像是一次徹底的再造。',
      '拉岡最著名、也最廣為流傳的概念，是他提出的「鏡像階段」（stade du miroir）：他觀察到，六個月大左右的嬰兒，第一次在鏡子裡認出自己的倒影時，會表現出強烈的欣喜——因為在此之前，嬰兒對自己身體的感知是破碎、不協調的，而鏡中那個完整、統一的影像，讓他第一次「誤認」自己是一個完整的個體。拉岡認為，這個透過「外在影像」建立起來的自我，從一開始就建立在一場錯認之上，這也是為什麼人終其一生，都在追尋一個其實從未真正完整過的自我形象。',
      '這套理論與那西瑟斯愛上自己水中倒影的神話，形成了一次跨越兩千多年的意味深長呼應——那西瑟斯因無法將倒影與自己等同，最終憔悴而死；拉岡筆下的嬰兒，卻恰恰是「錯把倒影當成自己」，才得以建立起最初的自我認同。兩則故事一起讀，某種程度上共同指向同一個提問：我們對「自己是誰」的認識，究竟有多少部分，其實建立在對某個外在影像的凝視與誤認之上？拉岡晚年的精神分析研討班在巴黎盛況空前，聽眾除了專業分析師，還吸引了大批哲學家、文學評論家與藝術家慕名而來，他所開創的「拉岡派精神分析」，至今仍是歐陸哲學與文化研究領域最具影響力的理論資源之一。'
    ]},

  { id:'annafreud', gen:'psychology', zh:'安娜・佛洛伊德', gr:'Anna Freud', roman:'—', epithet:'系統化整理「心理防衛機制」的兒童精神分析先驅',
    year:1895, yearLabel:'1895年',
    domain:'兒童精神分析、自我防衛機制、創傷研究', symbol:'天平與面具', parents:['freud'], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'安娜・佛洛伊德是佛洛伊德最小的女兒，也是兒童精神分析與「自我心理學」的重要開創者。她在1936年出版的《自我與防衛機制》一書，系統性整理了人類心理面對痛苦與焦慮時，會不自覺啟動的一整套「防衛機制」——包括否認、壓抑、投射，以及「理智化」：把難以承受的情緒，轉譯成純粹的邏輯分析來處理，藉此迴避真正感受它的痛苦。',
    fullStory:[
      '安娜・佛洛伊德是精神分析學創始人西格蒙德・佛洛伊德最小的女兒，父親晚年罹患口腔癌期間，她始終陪伴在側、親自照料，父女兩人的關係極為緊密。她自己也走上精神分析的專業道路，卻沒有停留在複述父親的理論，而是將關注焦點，從父親著重的潛意識與童年性心理，轉向了「自我」（ego）本身如何運作，尤其專注於兒童精神分析這個當時幾乎乏人問津的領域，被後世公認為「兒童精神分析之母」。',
      '安娜・佛洛伊德在一九三六年出版的《自我與防衛機制》，是她畢生最重要的著作——書中系統性整理了人類心理面對難以承受的痛苦、焦慮或衝動時，「自我」會不自覺啟動的一整套防衛機制，包括否認（拒絕承認痛苦的事實存在）、壓抑（把痛苦記憶推入潛意識深處）、投射（把自己無法接受的情緒，錯認成是別人的問題）——以及格外貼近現代人處境的「理智化」（intellectualization）：把一段難以承受的情緒經驗，轉譯成一套純粹冷靜、邏輯分明的分析語言來處理，看似把事情「想得很清楚」，實際上卻是一種迴避——用理性思考的姿態，避開真正去感受那份情緒本身該有的重量。',
      '「理智化」這種防衛機制，在講究效率與自我管理的現代社會裡格外常見——尤其容易發生在習慣用「分析問題」來應對一切、包括應對自己內心痛苦的人身上：把一段關係的破裂，拆解成幾條理性的因果推論；把喪失與哀傷，轉換成幾句冷靜的自我覺察總結。這種處理方式並非全然無用，適度的理智化甚至能幫助人在危機當下維持基本的行動能力；但安娜・佛洛伊德也提醒，若一個人長期只用理智化來處理情緒，等於是一直繞過情緒本身、卻始終沒有真正消化它——那份被延後處理的感受，往往不會真的消失，只是換了一種方式，繼續影響著這個人。'
    ]},

  { id:'bowlby', gen:'psychology', zh:'約翰・鮑比', gr:'John Bowlby', roman:'—', epithet:'提出「依附理論」的精神科醫師',
    year:1907, yearLabel:'1907年',
    domain:'依附關係、早年創傷、關係模式的代際傳遞', symbol:'母子連結的絲線', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'約翰・鮑比是「依附理論」的提出者，主張嬰兒與主要照顧者之間形成的早期情感連結模式，會深刻影響一個人成年後在親密關係裡的行為模式——他的研究發現，童年時期經歷的分離、忽視或不穩定照顧，往往會在成年後，以看似與童年無關的方式，重新浮現在親密關係的相處模式裡。',
    fullStory:[
      '約翰・鮑比是英國精神科醫師，二戰後受世界衛生組織委託，研究戰爭孤兒與長期住院兒童的心理狀態，發現這些孩子即使物質生活無虞，長期缺乏穩定的情感連結，仍會出現明顯的發展遲緩與情感疏離——這項觀察，促使他提出了影響深遠的「依附理論」。',
      '依附理論主張，嬰兒與主要照顧者之間，會依照照顧品質的不同，發展出「安全型」「焦慮型」「逃避型」等不同的依附模式——這套早年形成的關係模板，日後並不會隨著童年結束而消失，反而會深刻影響一個人成年後，在親密關係、友誼，甚至職場人際互動裡，反覆浮現的相處模式。一個童年時期經常被忽視或情感被否定的孩子，成年後可能會不自覺地，用過度獨立、迴避親密，或反過來過度焦慮依賴的方式，重新演繹當年那段未被好好回應的關係。',
      '依附理論後來成為現代心理治療裡，理解「為什麼有些人明明想靠近，卻總是不自覺推開對方」「為什麼童年的傷，會在多年後的親密關係裡以完全不同的面貌重新出現」這類現象，最重要的理論框架之一。鮑比的研究也提醒我們：許多成年後看似難以理解的關係模式，往往不是憑空出現的性格缺陷，而是一段更早、更深層的情感經驗，用另一種形式延續至今。'
    ]},

  // ---------- MODERN PHILOSOPHY ----------
  { id:'schopenhauer', gen:'modernphil', zh:'叔本華', gr:'Arthur Schopenhauer', roman:'—', epithet:'主張「世界即是我的表象」的悲觀哲學家',
    year:1788, yearLabel:'1788年',
    domain:'意志與表象、悲觀主義、東方哲學的西方橋樑', symbol:'貴賓犬與《奧義書》', parents:[], links:['nietzsche','buddha'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 170" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <rect x="20" y="20" width="260" height="60" rx="6" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="150" y="46" font-size="11" text-anchor="middle" fill="#2A2118">表象</text>
      <text x="150" y="62" font-size="8" text-anchor="middle" fill="#6b5c46">我們所感知到的世界</text>
      <line x1="150" y1="80" x2="150" y2="100" stroke="#5B5850" stroke-width="1.5" stroke-dasharray="3 3"/>
      <rect x="20" y="100" width="260" height="55" rx="6" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="1.5"/>
      <text x="150" y="126" font-size="11" text-anchor="middle" fill="#2A2118">意志</text>
      <text x="150" y="142" font-size="8" text-anchor="middle" fill="#6b5c46">盲目、永不止息的驅力</text>
      <text x="150" y="165" font-size="8.5" text-anchor="middle" fill="#6b5c46">表象之下，是永不停歇的意志在運作</text>
    </svg>`,
    story:'叔本華主張，我們所認識的整個世界，終究只是「我的表象」——一切經驗都必須先通過感知與理智的加工，才能被我們把握，世界本身的真實面貌，是一股盲目、無止盡掙扎的「意志」。他是西方第一位認真研讀《奧義書》、並公開承認深受佛學啟發的重要哲學家，也是尼采青年時期最重要的精神導師。',
    fullStory:[
      '叔本華的代表作《作為意志和表象的世界》開篇第一句，就是他哲學體系最精煉的濃縮：「世界是我的表象」——他繼承並改造了康德的認識論，主張我們永遠無法直接認識「物自身」，我們所經驗到的整個世界，包括時間、空間與因果關係，其實都是我們的感知與理智，替一個更深層的實在加工、建構出來的表象。這個立場，某種程度上與貝克萊「存在即是被感知」遙相呼應，只是叔本華更進一步追問：在這層表象之下，究竟藏著什麼？',
      '叔本華認為，表象之下潛藏的真實本體，是一股盲目、無所不在、永不停歇的「意志」（Wille）——它驅動著石頭的重力、植物的生長、動物的求生本能，也驅動著人類永無止盡的慾望與掙扎。正因為意志的本質是「永遠在追求、卻永遠無法真正滿足」，叔本華得出了他最著名、也最悲觀的結論：人生的本質即是痛苦，短暫的滿足只會迅速讓位給空虛或新的慾望，快樂終究只是痛苦暫時的缺席，而非真正的存在。',
      '為了替這股悲觀找到出路，叔本華將目光投向了東方——他是西方哲學史上，第一位認真鑽研印度《奧義書》、並公開盛讚其智慧的重要哲學家，案頭常年擺著一本拉丁文譯本的《奧義書》，晚年更自言這是「我一生的慰藉」。他同時也對佛教教義推崇備至，認為佛教「否定意志、超脫慾望」的解脫之道，與自己哲學體系裡「透過藝術與禁慾來暫時擺脫意志宰制」的主張不謀而合——儘管學者普遍認為，叔本華對佛學的理解夾雜著不少西方式的誤讀與再詮釋，但他確實是讓東方哲學第一次真正進入歐陸哲學主流視野的重要橋樑。他同時也是尼采青年時期最重要的思想導師，尼采早年那本《作為教育家的叔本華》，正是對這位精神導師最直接的致敬——儘管尼采後來逐漸背離了叔本華式的悲觀與禁慾主張，轉而發展出截然不同、更強調「積極擁抱生命」的哲學道路。'
    ]},

  { id:'nietzsche', gen:'modernphil', zh:'尼采', gr:'Friedrich Nietzsche', roman:'—', epithet:'宣告「上帝已死」的哲學家',
    year:1844, yearLabel:'1844年',
    domain:'權力意志、超人、永恆輪迴', symbol:'太陽與深淵', parents:[], links:['apollo','dionysus','schopenhauer'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 130" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <line x1="30" y1="70" x2="270" y2="70" stroke="#A6812E" stroke-width="2"/>
      <circle cx="70" cy="70" r="26" fill="#EFE6CE" stroke="#1F4959" stroke-width="1.5"/>
      <text x="70" y="66" font-size="9" text-anchor="middle" fill="#2A2118">阿波羅</text>
      <text x="70" y="78" font-size="7.5" text-anchor="middle" fill="#6b5c46">理性／秩序</text>
      <circle cx="230" cy="70" r="26" fill="#EFE6CE" stroke="#B5502E" stroke-width="1.5"/>
      <text x="230" y="66" font-size="9" text-anchor="middle" fill="#2A2118">戴歐尼修斯</text>
      <text x="230" y="78" font-size="7.5" text-anchor="middle" fill="#6b5c46">狂喜／本能</text>
      <text x="150" y="30" font-size="9" text-anchor="middle" fill="#2A2118" font-weight="bold">偉大的悲劇，兩者缺一不可</text>
      <polygon points="150,45 158,60 142,60" fill="#8A6D1F"/>
    </svg>`,
    story:'尼采可能是被網路迷因引用最多的哲學家，「上帝已死」常被斷章取義當成無神論宣言，其實他真正想說的是：當支撐西方價值觀幾千年的信仰基礎動搖後，人類該如何自己重新找到活下去的意義。他還借用阿波羅與戴歐尼修斯這對希臘神祇，描述藝術裡理性秩序與狂歡衝動的拉扯。',
    fullStory:[
      '你可能在T恤、咖啡杯上看過「殺不死我的，使我更強大」這句話，這其實出自尼采——但和大多數被印在周邊商品上的哲學金句一樣，這句話被抽離脈絡後，意思也被磨平了大半。尼采真正關心的問題要沉重得多：當歐洲社會賴以維繫兩千年的宗教與道德根基逐漸崩解，人類該拿什麼撐住自己的生活？他那句更著名、也更常被誤解的宣告「上帝已死」，指的不是「無神論勝利了、值得慶祝」，而是一句帶著憂心的警告——他擔心失去了絕對真理的支撐後，虛無主義會像瘟疫一樣蔓延。',
      '尼采早年在《悲劇的誕生》裡，直接借用希臘神話中阿波羅與戴歐尼修斯這對神祇，來描述藝術（乃至人性）中兩股互相拉扯的力量：阿波羅代表理性、秩序、清晰的個體形式，就像一座工整的希臘神廟；戴歐尼修斯則代表本能、狂喜、與群體融為一體的失控衝動，就像一場徹夜狂歡的酒神祭。他認為，最偉大的希臘悲劇，正是這兩股力量達到微妙平衡的產物——太過阿波羅會流於呆板說教，太過戴歐尼修斯則會失控崩潰。',
      '尼采晚年提出的「超人」（Übermensch）概念，也常被通俗化誤解成「超級英雄」或「弱肉強食」的口號——歷史上甚至一度被納粹曲解挪用，這是尼采本人萬萬料想不到、也堅決反對的方向（他其實非常厭惡反猶主義與民族主義）。他真正想描述的，其實是一種能夠親手為自己創造價值、不再仰賴現成道德教條的人。讀尼采最需要小心的一課，或許正是他自己的教訓：一句被截斷、被印在商品上的金句，往往離作者原本的意思最遠。'
    ]},

  { id:'sartre', gen:'modernphil', zh:'沙特', gr:'Jean-Paul Sartre', roman:'—', epithet:'「他人即地獄」的存在主義旗手',
    year:1905, yearLabel:'1905年',
    domain:'存在主義、自由、責任', symbol:'咖啡館與空椅子', parents:[], links:['camus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'沙特最出名的一句話「他人即地獄」常被當成「我討厭所有人」的厭世宣言來引用，但他原意其實是在說：我們太容易活在別人的眼光和評價裡，把自己活丟了。他主張「存在先於本質」——人不是先有一個固定的「本質」再去生活，而是要靠自己不斷做出的選擇，把自己「活」成一個什麼樣的人。',
    fullStory:[
      '「他人即地獄」（L\u2019enfer, c\u2019est les autres）大概是被截圖轉發最多的哲學句子之一，很多人以為這是在說「其他人都很煩、能躲多遠躲多遠」。但這句話出自沙特的劇作《禁閉》，劇情講的是三個死後被關在同一間房間裡、永遠無法離開彼此視線的靈魂——沙特真正想說的是：我們太容易活在別人怎麼看自己這件事裡，一旦活在別人的判斷和標籤之中，自己反而變成了自己的地獄。',
      '沙特哲學裡最核心的一句口號是「存在先於本質」——他的意思是，一把裁紙刀在被製造出來之前，工匠腦子裡就已經先有了「這是一把用來裁紙的工具」這個本質，刀子的存在服務於這個既定本質；但人不一樣，人是先被「扔」進這個世界存在了，然後才透過一次次的選擇，慢慢把自己活成什麼樣的人——沒有誰事先規定好你「應該」成為什麼。這種徹底的自由，同時也意味著徹底的責任：你沒辦法把自己的選擇推給「命運」或「人性」，因為選擇永遠是你自己做的。',
      '沙特和卡繆本來是好朋友、常一起在巴黎咖啡館高談闊論，卻在1952年因為卡繆出版《反抗者》一書、批判以革命之名濫用暴力的左翼思潮而公開決裂——這場當年轟動巴黎知識圈的「世紀絕交」，某種意義上也是兩種「面對荒謬」的態度在打架：卡繆主張清醒地活著、拒絕任何一套包辦一切答案的意識形態；沙特則更傾向相信，可以透過集體行動（哪怕手段激進）去改變世界。這場爭論沒有輸家，倒是給後人留下了一個挺實際的問題：面對不公，到底該冷靜旁觀還是挺身介入？'
    ]},

  { id:'beauvoir', gen:'modernphil', zh:'波伏娃', gr:'Simone de Beauvoir', roman:'—', epithet:'「並非生而為女人」的存在主義女性主義者',
    year:1908, yearLabel:'1908年',
    domain:'女性主義、他者、自由', symbol:'第二性', parents:[], links:['sartre'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'波伏娃那句「並非生而為女人，而是變成女人」，是現代女性主義理論最常被引用的一句話——她想說的是，「女性該是什麼樣子」這件事，很大程度上是被社會一步步「教」出來的，而不是天生注定。她與沙特維持了長達五十年、拒絕傳統婚姻形式的開放式伴侶關係，兩人一起把存在主義哲學活成了一種生活實驗。',
    fullStory:[
      '「並非生而為女人，而是變成女人」——這句話出自波伏娃1949年出版的《第二性》，如今幾乎是女性主義理論的開篇金句。她的意思不是否認生理性別，而是指出：我們從小被教導該怎麼坐、該喜歡什麼顏色、該有什麼樣的人生目標，這一整套「女性該有的樣子」，很大程度上是被社會文化一點一滴塑造出來的，而不是與生俱來、不可更改的天性。這個洞察後來被稱為「性別是被建構的」，成為整個當代性別研究領域的理論起點。',
      '波伏娃與沙特相識於巴黎高等師範學院，兩人協議維持一種拒絕傳統婚姻框架、彼此保有各自其他感情關係自由的伴侶模式，這段關係持續了超過五十年，直到沙特過世。這種關係模式在當時（乃至今日）都相當挑戰主流社會規範，波伏娃自己也坦言這段關係裡不總是輕鬆——她借用存在主義「自由與責任並存」的核心主張，把這套哲學不只寫在書裡，也身體力行地活成了一場關於親密關係可以有多少種可能性的真實實驗。',
      '值得一提的是，波伏娃常年活在「沙特的伴侶」這個標籤陰影之下，早年學界甚至一度低估她本人思想的獨創性、把她簡化成沙特哲學的「應用者」，直到近幾十年，學者重新回頭細讀她的原始著作，才逐漸確認《第二性》裡的許多核心洞察，其實是她自己獨立發展出來、甚至反過來影響了沙特的思考——這本身也是對「女性的貢獻容易被身邊男性蓋過」這個現象，一個挺諷刺的現實案例。'
    ]},

  { id:'wittgenstein', gen:'modernphil', zh:'維根斯坦', gr:'Ludwig Wittgenstein', roman:'—', epithet:'「語言的界限就是世界的界限」',
    year:1889, yearLabel:'1889年',
    domain:'語言哲學、邏輯', symbol:'梯子與家族相似性', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 170" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <line x1="110" y1="150" x2="110" y2="30" stroke="#5B5850" stroke-width="3"/>
      <line x1="190" y1="150" x2="190" y2="30" stroke="#5B5850" stroke-width="3"/>
      <line x1="110" y1="130" x2="190" y2="130" stroke="#A6812E" stroke-width="3"/>
      <line x1="110" y1="100" x2="190" y2="100" stroke="#A6812E" stroke-width="3"/>
      <line x1="110" y1="70" x2="190" y2="70" stroke="#A6812E" stroke-width="3"/>
      <line x1="110" y1="40" x2="190" y2="40" stroke="#A6812E" stroke-width="3"/>
      <text x="150" y="20" font-size="9" text-anchor="middle" fill="#2A2118">爬上去之後</text>
      <text x="150" y="165" font-size="8.5" text-anchor="middle" fill="#6b5c46">要懂得把梯子踢開</text>
    </svg>`,
    story:'維根斯坦一輩子寫了兩套幾乎互相推翻的哲學體系，前期認為語言就像一張精確的地圖，能對應真實世界的邏輯結構；後期卻推翻自己，主張語言更像一場場「遊戲」，同一個詞在不同場合的用法天差地別，壓根沒有一個統一不變的意思——這也是為什麼我們日常吵架，很多時候根本不是觀點不同，而是雙方對同一個詞的理解就不一樣。',
    fullStory:[
      '維根斯坦前期最重要的著作《邏輯哲學論》，試圖證明語言的結構可以像一張精確地圖那樣，一一對應真實世界的邏輯結構——只要語言用得夠精確，所有哲學爭論理論上都能被「說清楚」，或者被證明「根本沒有意義、純粹是語言用錯了」。他甚至在書的結尾留下一句著名的話，大意是：讀完這本書的人應該把這本書當成一把用完就該丟掉的梯子——爬上去之後，要懂得把梯子踢開。',
      '然而，維根斯坦後來幾乎推翻了自己前期的理論。在死後出版的《哲學研究》裡，他提出「語言遊戲」的概念：語言的意義不是來自它對應了什麼固定的邏輯結構，而是來自它在具體生活情境裡「怎麼被使用」——同一個詞，在下棋、在祈禱、在講笑話、在下命令時，規則完全不同，就像不同的遊戲各有各的玩法。他還提出「家族相似性」，指出很多我們以為有共同本質的概念（比如「遊戲」本身），其實成員之間只是像家族成員那樣，彼此有些相似之處，卻未必有一條所有成員都共享的本質。',
      '這套理論最貼地的啟示，大概是解釋了為什麼很多爭吵根本吵不出結果——不是因為立場不同，而是雙方壓根用同一個詞在玩不同的「語言遊戲」，卻都以為對方在用自己那套規則。比如兩個人吵「什麼才算尊重」，很可能各自腦子裡的「尊重」這個詞，對應的根本是完全不同的生活情境和潛規則——維根斯坦式的解法，不是急著爭對錯，而是先停下來問：「我們說的，是同一件事嗎？」'
    ]},

  { id:'foucault', gen:'modernphil', zh:'傅柯', gr:'Michel Foucault', roman:'—', epithet:'揭露「權力無所不在」的思想家',
    year:1926, yearLabel:'1926年',
    domain:'權力、規訓、監視', symbol:'環形監獄', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 180" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="150" cy="90" r="70" fill="none" stroke="#5B5850" stroke-width="2"/>
      <circle cx="150" cy="90" r="20" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="1.5"/>
      <text x="150" y="94" font-size="8" text-anchor="middle" fill="#2A2118">瞭望塔</text>
      <circle cx="150" cy="24" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="150" cy="156" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="84" cy="90" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="216" cy="90" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="103" cy="43" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="197" cy="43" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="103" cy="137" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <circle cx="197" cy="137" r="10" fill="#EFE6CE" stroke="#A6812E"/>
      <text x="150" y="172" font-size="8.5" text-anchor="middle" fill="#6b5c46">你不知道自己此刻有沒有被看著</text>
    </svg>`,
    story:'傅柯最有名的比喻，是十八世紀一種叫「全景監獄」的建築設計——牢房圍成一圈，中間一座瞭望塔，犯人永遠不知道自己此刻有沒有被看著，於是漸漸學會自己管好自己。他認為，現代社會的學校、醫院、公司，某種程度上都在用類似的邏輯運作——權力不一定靠強迫，更常靠「讓你以為自己隨時可能被看著」，讓你自己把自己管得服服貼貼。',
    fullStory:[
      '十八世紀，英國哲學家邊沁設計了一種名叫「圓形監獄」（Panopticon）的建築：所有牢房呈環狀排列，面朝中央一座瞭望塔，塔內的看守可以看到每一間牢房，但因為逆光或百葉窗的設計，犯人永遠無法確定看守此刻究竟有沒有在看著自己。傅柯認為，這個設計的精妙之處不在於「真的時時刻刻都在監視」，而在於「讓被監視者自己也說不準」——久而久之，犯人會開始自己乖乖守規矩，因為他們已經把「可能被看著」這件事，內化成了自我管束的習慣。',
      '傅柯認為，這套邏輯其實早已滲透進現代社會的方方面面——學校用課表和考試規訓學生該在什麼時間做什麼事；工廠與辦公室用打卡和績效考核規訓員工的一舉一動；醫院用病歷與檢查規訓病人該如何理解自己的身體。他把這種運作方式稱為「規訓權力」——權力不必靠一次次動用暴力來維持，只要設計出讓人「自己主動配合」的制度和空間，權力就能悄悄運作，甚至讓人根本感覺不到自己正被規訓。',
      '這套理論放到今天格外貼地——社交媒體上「可能有人在看」的自我審查、職場裡永遠開著的績效儀表板、街角無處不在的監視攝影機，某種意義上都是數位時代版本的圓形監獄。傅柯本人也因此常被批評過於悲觀，彷彿權力無孔不入、令人無處可逃；但也有人認為，他真正想提醒的，其實是：既然權力常常靠「讓你自己管好自己」來運作，那看清這套機制本身，就是重新拿回一點主動權的第一步。'
    ]},

  { id:'rawls', gen:'modernphil', zh:'羅爾斯', gr:'John Rawls', roman:'—', epithet:'提出「無知之幕」的正義理論家',
    year:1921, yearLabel:'1921年',
    domain:'正義、公平、社會契約', symbol:'蒙眼布幕', parents:[], links:['themis'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 160" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="150" cy="60" r="22" fill="#FBF6E9" stroke="#A6812E" stroke-width="1.5"/>
      <rect x="128" y="48" width="44" height="12" rx="3" fill="#5B5850"/>
      <text x="150" y="95" font-size="9" text-anchor="middle" fill="#2A2118">無知之幕</text>
      <line x1="60" y1="115" x2="240" y2="115" stroke="#A6812E" stroke-width="1" stroke-dasharray="3 3"/>
      <text x="90" y="135" font-size="9" text-anchor="middle" fill="#6b5c46">富有？</text>
      <text x="150" y="135" font-size="9" text-anchor="middle" fill="#6b5c46">健康？</text>
      <text x="210" y="135" font-size="9" text-anchor="middle" fill="#6b5c46">弱勢？</text>
      <text x="150" y="152" font-size="8.5" text-anchor="middle" fill="#6b5c46">投胎前，你不知道自己會是誰</text>
    </svg>`,
    story:'羅爾斯設計了一個思想實驗來回答「什麼樣的社會才算公平」：假設你要為整個社會制定規則，但你完全不知道自己將來會投胎成誰——可能是富豪，也可能是窮人；可能健康，也可能殘疾。他認為，只有在這層「無知之幕」背後設計出來的規則，才是真正公平的，因為你沒辦法把規則設計得只對自己有利。',
    fullStory:[
      '羅爾斯在《正義論》裡提出一個堪稱哲學史上最好玩、也最實用的思想實驗：想像你即將投胎轉世到一個全新設計的社會裡，但在你投胎之前，有一層「無知之幕」（veil of ignorance）遮住了你——你不知道自己投胎後會是男是女、貧窮還是富有、天資聰穎還是先天殘疾、生在哪個種族與國家。在這種「什麼都不知道」的處境下，你會希望這個社會的規則被設計成什麼樣子？',
      '羅爾斯認為，正是因為你不知道自己投胎後會落在哪個位置，你才會真正誠實地站在「所有可能處境」的角度去思考公平——如果你可能生來就是社會最底層，你大概不會同意「贏者全拿、輸者餓死」這種規則；你反而更可能傾向支持一套能保障最弱勢者基本生活、同時仍然容許一定程度自由競爭的制度。這個思想實驗巧妙地把「你自己會不會佔便宜」這個私心，從設計規則的過程裡直接剔除掉。',
      '這套「無知之幕」的思考方式，其實很適合套用在日常生活的爭論上——比如討論一條新政策該怎麼訂，不妨問問自己：「如果我不知道自己會是這條政策的受益者還是受害者，我還會支持它嗎？」當然，也有批評者指出，現實中沒有人真的能完全甩開自己的立場、想像力去做純粹中立的判斷——羅爾斯的「無知之幕」終究是一個思想實驗，而不是真的能被複刻的現實操作，但作為一種「檢查自己有沒有私心」的心智練習，至今仍相當好用。'
    ]},

  { id:'singer', gen:'modernphil', zh:'彼得・辛格', gr:'Peter Singer', roman:'—', epithet:'提出「溺水兒童」思想實驗的效益主義者',
    year:1946, yearLabel:'1946年',
    domain:'應用倫理學、效益主義、動物權利', symbol:'淺水池與名牌西裝', parents:[], links:[],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 150" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="70" cy="70" r="18" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="70" y="74" font-size="8" text-anchor="middle" fill="#2A2118">你</text>
      <path d="M120 100 Q150 80 180 100 Q210 120 240 100" fill="none" stroke="#4A6B7A" stroke-width="2"/>
      <circle cx="180" cy="95" r="10" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="1.5"/>
      <text x="180" y="98" font-size="7" text-anchor="middle" fill="#2A2118">孩子</text>
      <text x="150" y="30" font-size="9" text-anchor="middle" fill="#2A2118">近在眼前 vs 遠在他方</text>
      <text x="150" y="140" font-size="8.5" text-anchor="middle" fill="#6b5c46">距離，不該決定救援的義務</text>
    </svg>`,
    story:'辛格提出一個簡單到有點尷尬的思想實驗：如果你穿著名牌西裝走過一個淺水池，看到一個小孩快淹死了，你會不會因為怕弄髒西裝而猶豫要不要下水救？多數人立刻回答「當然會救，衣服重要個屁」。辛格接著追問：那你為什麼願意花錢買名牌衣服，卻不願意把同樣一筆錢捐給能救活遠方孩子生命的慈善機構？距離，真的能改變一條命的價值嗎？',
    fullStory:[
      '辛格提出的「溺水兒童」思想實驗大概是應用倫理學裡最直白、也最讓人坐立難安的一個：假設你穿著一身昂貴的西裝，走在路上，看到路邊淺水池裡有個小孩快要淹死，而你只要蹚進水裡就能救他，代價是弄髒、甚至毀掉這身昂貴的衣服。幾乎所有人都會毫不猶豫地回答：「當然要救，衣服而已，有什麼好猶豫的。」',
      '辛格接著拋出真正的殺傷力：如果你願意為了救一個近在眼前的孩子犧牲一件昂貴西裝的價值，那麼，當你把同樣一筆錢拿去買奢侈品、而不是捐給那些能用極低成本挽救遠方貧困地區兒童生命的公益組織時，你的選擇背後，是不是只因為那個孩子「離你比較遠、你看不見」？辛格認為，如果生命的價值不該因為距離遠近而打折，那我們對「該不該捐款」這件事的態度，理應比現實中大多數人實際做的，要積極得多。',
      '這套理論後來發展成「有效利他主義」運動的重要思想源頭——鼓勵人們不只是「想做好事」，還要認真計算「怎麼做，才能用同樣的錢和時間，救到最多的人、產生最大的實質幫助」。批評者認為，這種赤裸裸的功利計算容易忽略人際關係裡那些沒法量化的價值（比如「我更願意先照顧自己身邊的人」這種直覺，未必是錯的）；但辛格這套「逼你直視自己雙重標準」的提問方式，至今仍是應用倫理學課堂上，最常被拿來挑戰學生直覺的經典案例。'
    ]},

  { id:'arendt', gen:'modernphil', zh:'漢娜・鄂蘭', gr:'Hannah Arendt', roman:'—', epithet:'發明「邪惡的平庸性」的哲學家，親眼見證納粹艾希曼受審',
    year:1906, yearLabel:'1906年',
    domain:'政治哲學、邪惡的本質、極權主義', symbol:'法庭與「banality of evil」', parents:[], links:['sartre'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'鄂蘭是猶太裔德國哲學家，以報紙記者的身分親眼旁聽了納粹戰犯艾希曼的耶路撒冷審判後，提出了「邪惡的平庸性」這個概念——最大的惡，往往不是出於什麼深仇大恨或意識形態狂熱，而是來自普通人在體制中不思考、只服從的「例行公事」。這個洞察，讓她一生都被部分猶太社群視為叛徒，卻成為二十世紀最重要的政治哲學遺產之一。',
    fullStory:[
      '鄂蘭在納粹德國時期流亡至法國，後又移民美國，二戰期間她的母親死於納粹集中營，這段親身經歷讓她對極權主義的運作機制有著異於一般學者的敏銳觀察。一九六一年，她以《紐約客》記者的身分，親赴耶路撒冷旁聽納粹戰犯艾希曼的審判——艾希曼是納粹屠殺猶太人「最終解決方案」的主要執行者之一，被控在二戰期間親自安排火車調度，將數以百萬計的猶太人送入死亡營。',
      '然而親眼所見，令鄂蘭極度震驚的不是艾希曼散發出什麼「怪物」氣息，而恰恰相反：他在法庭上表現得像一個乏味的官僚，普通話、普通、長著一副路人面孔，滿口陳腔濫調的反猶言論，但既沒有任何深仇大恨的跡象，也沒有什麼意識形態狂熱——他只是「在做好本份工作」。鄂蘭由此得出那個日後極具爭議的概念：「邪惡的平庸性」（banality of evil）——最大的惡，往往不是什麼特殊人格的暴君或變態所為，而恰恰來自體制中那些「只是服從指令、從不抬頭思考這一切意味著什麼」的普通人。',
      '這個觀點在猶太社群引發極大憤怒，許多人認為她是在替艾希曼開脫、或在為納粹大屠殺淡化罪名；鄂蘭則堅持自己只是在描述一種她親眼觀察到的現象，而非為其辯護。這場爭議至今仍在持續——支持者認為她精準捕捉了極權主義運作的核心機制；批評者認為這個概念太容易被拿來替「普通納粹支持者」開脫，把系統性的罪惡歸咎給「沒思考」這個個人缺陷，卻迴避了更深層的結構問題。放到今天，我們每天在手機上刷到的那些「服從多數」的社會現象——演算法推送、同溫層集體謾罵、職場中的集體沉默——某種程度上，都讓鄂蘭的洞察，顯得比她寫下它的那個年代還要尖銳。'
    ]},

  { id:'kierkegaard', gen:'modernphil', zh:'齊克果', gr:'Søren Kierkegaard', roman:'—', epithet:'存在主義的孤獨父親，用化名寫作的憂鬱丹麥人',
    year:1813, yearLabel:'1813年',
    domain:'存在主義、焦慮、信仰的跳躍', symbol:'懸崖與個人抉擇', parents:[], links:['sartre'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'齊克果被稱為「存在主義之父」，他對「群體」（the crowd）的厭惡近乎偏執——他相信，真實的存在必須是孤獨的、屬於個人的；一旦你把自己交給群體，便立即喪失了真正的自我。他一生未婚，卻與一個有婚約在身的女子的複雜情感糾葛，成為他所有哲學創作最深層的動力燃料。',
    fullStory:[
      '齊克果生於哥本哈根一個虔誠卻憂鬱的家庭，父親是個脾氣暴躁的宗教狂熱者，晚年曾告訴兒子們：他年輕時曾在暴風雨中對上帝大聲咒罵，後來深信這是對神明的褻瀆，將給家族帶來詛咒。齊克果一生都籠罩在這種「原罪感」之下，他的哲學，從某種意義上來說，正是對這種深刻焦慮的回應與消化——他稱焦慮是「對自由的眩暈」，當你站在懸崖邊、意識到自己可以跳下去的那一刻，你體驗到的正是這種眩暈：自由令人暈眩，而焦慮，正是這種暈眩的名字。',
      '他與一位名叫瑞吉娜・奧爾森的年輕女子訂婚，卻在婚禮前一年突然單方面解除婚約，此後終生未娶。這個決定的原因至今仍是學界熱議的話題——他自己說，因為意識到自己「是一個天才，而天才不能結婚」；後世學者則傾向於認為，他在這段關係中感受到某種無法承受的責任，又或者，他的宗教焦慮讓他相信，真正的宗教信仰必須是「個人與上帝之間私密的事」，婚姻會讓他分心。瑞吉娜後來嫁給了另一個人，在齊克果葬禮上，有目擊者稱她「面無表情」，但眼睛裡閃爍著某種難以解讀的光。',
      '齊克果最另類的特點之一，是他以二十多個不同筆名發表了大量著作——每個筆名都有自己獨特的風格與立場，有時甚至互相矛盾。他在這個筆名迷宮裡，扮演著一個個不同的「角色」，用多重聲音層層推演各種人生立場的可能性，卻從不直接宣布自己「真正的立場」是什麼。後世有人開玩笑說：如果他生在今天，大概會是個重度網名愛好者，或者一個瘋狂的角色扮演玩家。'
    ]},

  // ---------- CROSS-CULTURAL CONNECTIONS ----------
  // crossType: 'syncretism' (real historical religious fusion), 'cognate' (linguistic common root), 'parallel' (same era, no direct contact — deliberately drawn with NO edge)
  { id:'serapis', gen:'crosscultural', zh:'塞拉皮斯', gr:'Serapis', roman:'—', epithet:'一位「被設計」出來的融合神', crossType:'syncretism',
    year:-280, yearLabel:'約西元前280年（托勒密一世創立）',
    domain:'冥界、豐饒、王權正當性', symbol:'糧倉量器與三頭犬', parents:[], syncretism:['zeus','dionysus','hades','osiris'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'塞拉皮斯是托勒密一世為了同時安撫希臘與埃及臣民，刻意打造出來的融合神——外貌像宙斯，卻揉合了埃及冥神歐西里斯與聖牛阿匹斯的神格，是史上少見「由統治者主動策劃」的宗教融合案例，而不是文化自然交流的結果。',
    fullStory:[
      '西元前四世紀末，馬其頓將領托勒密一世在亞歷山大大帝死後接管埃及、自立為王，面對的難題是：他手下的希臘移民信奉宙斯、黑帝斯這些奧林帕斯神祇，本地埃及人卻世代信奉歐西里斯與阿匹斯聖牛，兩套信仰系統各說各話，不利於統治的凝聚力。據史家記載，托勒密因此授意打造一尊新神像——外形明顯借用希臘雕塑手法，蓄鬍留髮、姿態近似宙斯或黑帝斯，頭上卻頂著埃及穀倉常見的量穀器（modius），並揉入歐西里斯掌管冥界與豐饒的神格，取名「塞拉皮斯」。',
      '這尊神像被安放在亞歷山大城新建的塞拉皮斯神廟（Serapeum）中，很快同時吸引了希臘移民與埃及本地信徒前來膜拜——對希臘人而言，祂看起來像自己熟悉的神；對埃及人而言，祂承接的正是歐西里斯掌管的冥界與復活職能。值得一提的是，希臘史家希羅多德早在托勒密之前，便已在著作中將埃及的歐西里斯與希臘的戴歐尼修斯視為同一位神，塞拉皮斯的誕生某種程度上，正是把這種民間已存在的「跨文化聯想」，正式收編、制度化成一套官方宗教工程。'
    ]},

  { id:'osiris', gen:'crosscultural', zh:'歐西里斯', gr:'Osiris', roman:'—', epithet:'埃及冥界與復活之神', crossType:'syncretism',
    domain:'冥界、農業、死而復生', symbol:'彎鉤權杖與連枷', parents:[], syncretism:['dionysus','hades'], links:['isis','set'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'歐西里斯是古埃及神話裡的冥界之神，傳說被弟弟賽特謀殺分屍，妻子伊西斯蒐集他的殘骸使其復活，此後統治冥界、審判亡靈——古希臘史家希羅多德早在托勒密之前，便已將歐西里斯與希臘的戴歐尼修斯視為同一位神，這則跨文化聯想，後來直接催生了塞拉皮斯這位融合神。',
    fullStory:[
      '歐西里斯是古埃及神話裡最重要的神祇之一，傳說他原本是統治埃及的賢明國王，教導人民農耕與釀酒的技藝，卻遭嫉妒的弟弟賽特設計謀殺，屍身還被殘忍分屍，散落尼羅河沿岸各處。他的妻子（同時也是妹妹）伊西斯，走遍埃及蒐集丈夫的殘骸碎片，運用魔法將他重新拼合、短暫復活，兩人因此得以誕下兒子荷魯斯——歐西里斯此後便永久停留在冥界，成為亡者的審判者與冥界之王。',
      '希臘史家希羅多德在西元前五世紀遊歷埃及時，便已注意到歐西里斯與希臘酒神戴歐尼修斯之間的相似之處——兩位神祇都與農業豐饒、死而復生的意象緊密相連，希羅多德因此在著作裡直接將兩者視為同一位神明。這則民間流傳已久的跨文化聯想，到了托勒密一世治理埃及時期，更被正式收編、制度化，塑造出融合歐西里斯、阿匹斯聖牛與希臘宙斯、黑帝斯特質的全新神祇「塞拉皮斯」，成為托勒密王朝安撫希臘與埃及兩方臣民、鞏固統治正當性的宗教工程。'
    ]},

  { id:'isis', gen:'crosscultural', zh:'伊西斯', gr:'Isis', roman:'—', epithet:'蒐集丈夫遺骸使其復活的埃及女神', crossType:'syncretism',
    domain:'母性、魔法、忠貞的愛', symbol:'牛角日輪與展翅雙翼', parents:[], syncretism:['demeter','aphrodite'], links:['osiris'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'伊西斯是埃及神話裡最重要的女神之一，歐西里斯之妻，丈夫遭謀殺分屍後，她走遍埃及蒐集殘骸、以魔法使其復活，誕下兒子荷魯斯。她的信仰後來隨羅馬帝國擴張傳遍地中海世界，常被希臘羅馬人等同於狄蜜特或阿芙蘿黛蒂。',
    fullStory:[
      '伊西斯是埃及神話裡集母性、魔法與忠貞於一身的重要女神，歐西里斯的妻子（同時也是妹妹）。當歐西里斯遭弟弟賽特設計謀殺、屍身被殘忍分屍散落尼羅河沿岸各處時，伊西斯展現出驚人的堅毅與魔法造詣，走遍埃及各地，一片片蒐集丈夫的殘骸，運用強大的咒術將其重新拼合、短暫復活，兩人因此得以誕下兒子荷魯斯——伊西斯此後獨力撫養荷魯斯長大，助他日後奪回本應屬於歐西里斯的王位。',
      '伊西斯信仰在托勒密王朝時期與希臘文化深度融合，隨著羅馬帝國版圖擴張，她的祭祀傳遍整個地中海世界，成為羅馬帝國境內最受歡迎的東方神祇之一。希臘羅馬人時常將伊西斯等同於自己信仰裡掌管豐收與母性的狄蜜特，或掌管愛與美的阿芙蘿黛蒂——這種跨文化的神格疊合，與塞拉皮斯融合宙斯、黑帝斯與歐西里斯的邏輯如出一轍，共同見證了希臘化時代地中海世界，宗教信仰如何在帝國擴張的過程裡不斷交融、重組。'
    ]},

  { id:'set', gen:'crosscultural', zh:'賽特', gr:'Set (Seth)', roman:'—', epithet:'謀殺親兄歐西里斯的沙漠與混亂之神',
    domain:'沙漠、風暴、混亂與嫉妒', symbol:'賽特獸與紅色沙漠', parents:[], links:['osiris'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'賽特是埃及神話裡掌管沙漠、風暴與混亂的神祇，因嫉妒兄長歐西里斯的王位與聲望，設計將他誘騙進一具量身打造的棺木中封死，再將屍身殘忍分屍——這場謀殺後來被歐西里斯之子荷魯斯復仇，成為埃及神話裡最核心的一則王位鬥爭敘事。',
    fullStory:[
      '賽特是埃及神話裡掌管沙漠、風暴與混亂的神祇，形象常是一種難以辨識、集合多種動物特徵於一身的神秘獸首。他嫉妒兄長歐西里斯身為賢明國王、深受埃及人民愛戴，設計了一場精心策劃的謀殺——他命人打造一具尺寸恰好貼合歐西里斯身形的華麗棺木，在一場宴會上宣布，誰能完美躺進這具棺木，便可獲得贈予，眾人輪流嘗試皆不合身，直到歐西里斯親自躺入，賽特立刻命人將棺蓋釘死、封入尼羅河，歐西里斯就此溺斃。',
      '賽特此後更將歐西里斯的屍身分屍成數十塊，散落埃及各地，企圖徹底杜絕任何復活的可能——這場謀殺，最終仍被歐西里斯之妻伊西斯以魔法逆轉，兩人的兒子荷魯斯成年後，更與賽特展開了一場曠日持久的王位爭奪戰，最終奪回本應屬於父親的王座。賽特與歐西里斯這對兄弟之間的鬥爭，被視為埃及神話裡「秩序與混亂」永恆對抗的原型敘事，某種程度上，也與希臘神話裡宙斯推翻克洛諾斯、或該隱殺害亞伯的敘事，隱隱形成一種跨文化的主題呼應。'
    ]},

  { id:'thoth', gen:'crosscultural', zh:'托特', gr:'Thoth', roman:'—', epithet:'埃及的書寫與智慧之神', crossType:'syncretism',
    domain:'文字、智慧、月曆與時間', symbol:'朱鷺頭與蘆葦筆', parents:[], syncretism:['hermes'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'托特是古埃及掌管文字、智慧與曆法記錄的神祇，形象常是朱鷺頭人身。因為和希臘的荷米斯同樣身兼「發明文字」「傳遞神旨」「引導亡靈」等職能，希臘化時代的埃及人與希臘人逐漸將兩者視為同一位神明的不同面貌。',
    fullStory:[
      '托特在埃及神話裡的地位極為關鍵——傳說是他發明了文字與數學，替眾神記錄言行，並在亡者接受審判時，負責在天秤上秤量死者心臟的重量，決定其是否能通過審判、獲得永生。他同時也是月亮與曆法的守護者，古埃及的曆法計算傳統上被認為由他所奠定。',
      '當希臘人在西元前四世紀後大量移居埃及，他們注意到托特與自己的荷米斯有著驚人相似的職能——同樣是「發明文字與溝通」之神，同樣負責在死後世界扮演引導與記錄的角色。於是希臘人開始稱托特為「埃及的荷米斯」，兩位神祇的形象與神話逐漸交融，並在托勒密時期的官方宗教文獻中，被明確視為同一位神在兩種文化裡的不同稱呼——這種「認定他國某神即是本國某神」的做法，希臘人稱之為「interpretatio graeca」（希臘式詮釋），是古代世界理解異文化信仰時，一種相當常見的策略。'
    ]},

  { id:'hermes_trismegistus', gen:'crosscultural', zh:'赫米斯·特里斯墨吉斯忒斯', gr:'Hermes Trismegistus', roman:'—', epithet:'「三重偉大」的融合智者', crossType:'syncretism',
    year:200, yearLabel:'約西元200年（《赫米斯文集》成書）',
    domain:'祕傳智慧、煉金術、占星學', symbol:'綠寶石板', parents:[], syncretism:['hermes','thoth'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'赫米斯·特里斯墨吉斯忒斯是荷米斯與托特徹底融合後誕生的全新神秘人物——「特里斯墨吉斯忒斯」意為「三重偉大」，據傳是一系列談論煉金術、占星與宇宙奧祕的祕傳文獻的作者，這套思想體系後來被稱為「赫米斯主義」，深深影響了文藝復興時期歐洲的神祕學傳統。',
    fullStory:[
      '隨著荷米斯與托特的形象在希臘化埃及逐漸合而為一，一個全新的、半神半人的智者形象也隨之誕生——赫米斯·特里斯墨吉斯忒斯，「特里斯墨吉斯忒斯」意為「三重偉大」，據信呼應了托特身兼的三重身分：眾神的書記官、亡靈的引導者，以及祕傳智慧的守護者。相傳一系列談論宇宙起源、靈魂本質、煉金術與占星術的希臘文獻，皆出自這位半神話人物之手，後世統稱為《赫米斯文集》。',
      '文藝復興時期，這批文獻經翻譯重新流入歐洲知識圈，一度被誤以為是比摩西還古老的失傳智慧，掀起了一波研究熱潮，深深影響了當時的煉金術士與早期科學家（包括牛頓本人，晚年也曾大量鑽研煉金術文獻）。儘管十七世紀後的語言學研究證實，這些文獻其實成書於西元二至三世紀的希臘化埃及、遠非古代智慧，「赫米斯主義」作為一套融合希臘理性思辨與埃及祕傳象徵的思想傳統，至今仍是西方神祕學譜系裡，最鮮明的一個跨文化混血案例。'
    ]},

  { id:'dyaus_pita', gen:'crosscultural', zh:'提烏斯神', gr:'Dyaus Pitṛ', roman:'—', epithet:'吠陀天父，宙斯的語言學親戚', crossType:'cognate',
    domain:'天空、父權', symbol:'天空與雷聲', parents:[], cognate:['zeus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 160" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="150" cy="30" r="22" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="2"/>
      <text x="150" y="34" font-size="9" text-anchor="middle" fill="#2A2118">*Dyeus</text>
      <line x1="150" y1="52" x2="80" y2="100" stroke="#5B5850" stroke-width="1.2"/>
      <line x1="150" y1="52" x2="150" y2="100" stroke="#5B5850" stroke-width="1.2"/>
      <line x1="150" y1="52" x2="220" y2="100" stroke="#5B5850" stroke-width="1.2"/>
      <circle cx="80" cy="115" r="18" fill="#EFE6CE" stroke="#A6812E"/>
      <text x="80" y="119" font-size="8" text-anchor="middle" fill="#2A2118">宙斯</text>
      <circle cx="150" cy="115" r="18" fill="#EFE6CE" stroke="#A6812E"/>
      <text x="150" y="119" font-size="8" text-anchor="middle" fill="#2A2118">提烏斯</text>
      <circle cx="220" cy="115" r="18" fill="#EFE6CE" stroke="#A6812E"/>
      <text x="220" y="119" font-size="8" text-anchor="middle" fill="#2A2118">提爾</text>
      <text x="150" y="150" font-size="8.5" text-anchor="middle" fill="#6b5c46">同一個史前詞根，分化成三個名字</text>
    </svg>`,
    story:'提烏斯是印度吠陀經典裡最古老的天空與父神之一，他的名字「Dyaus Pitṛ」與希臘語的「Zeus Pater」（宙斯之父稱）、拉丁語的「Jupiter」，其實共享同一個原始印歐語詞根——這不是文化借用，而是比較語言學證實的同源關係，證明希臘與印度神話系統，源自數千年前同一支史前語族的共同信仰。',
    fullStory:[
      '語言學家透過比較梵語、希臘語、拉丁語等多種印歐語系語言，重建出一個史前的「原始印歐語」，並發現許多語言裡的神祇名稱，其實能追溯回同一個共同詞根。「Dyeus」正是其中最著名的一個——它演變成了梵語的「Dyaus」、希臘語裡宙斯的敬稱「Zeus Pater」（意為「天父宙斯」）、拉丁語的「Jupiter」（本義同樣是「天父」）。這意味著，希臘人、羅馬人與印度雅利安人的祖先，很可能在數千年前，曾共同信奉同一位「天空父神」，隨著這支史前民族逐漸遷徙分化，同一個神祇的名字與形象，才在不同地區各自演變出宙斯、朱庇特、提烏斯這些看似毫不相干的面貌。',
      '耐人尋味的是，儘管提烏斯在語言學上是這整個神系「最古老」的成員，他在後期吠陀宗教裡的地位卻逐漸被降格——印度教後來真正的天空與雷電之神，變成了更年輕、更具行動力的因陀羅（Indra），提烏斯反而退居成一個相對模糊、少有獨立神話故事的背景角色。這個「語言學上最古老，宗教地位卻被後輩取代」的落差，也讓提烏斯成為比較神話學裡，一個經常被拿來討論「神系權力如何隨時代更迭」的經典案例。'
    ]},

  { id:'tyr', gen:'crosscultural', zh:'提爾', gr:'Týr', roman:'—', epithet:'北歐神話裡同源的天空之神遺跡', crossType:'cognate',
    domain:'戰爭、正義、誓言', symbol:'劍與斷手', parents:[], cognate:['zeus','dyaus_pita'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'北歐神話中的戰神提爾，名字同樣源自那個古老的原始印歐語詞根「Dyeus」，與宙斯、提烏斯神共享同一個語言學祖先。有趣的是，提爾在神話故事裡也同樣經歷了「地位被後輩取代」的命運——他曾是更古老的天空之神，後來卻讓位給了奧丁。',
    fullStory:[
      '提爾的名字，在語言學上同樣可以追溯回原始印歐語的「Dyeus」詞根，是宙斯、提烏斯神在北歐語族裡的同源親戚——古日耳曼語族的天空之神「Tiwaz」，正是提爾與宙斯共同的語言學祖先。這意味著，遠在北歐神話成形之前，日耳曼民族的祖先，很可能也曾與希臘人、印度雅利安人的祖先，共享著同一套對「天空之神」的原始信仰。',
      '提爾在流傳至今的北歐神話裡，最著名的故事是他為了束縛住終將在諸神黃昏咬死眾神的巨狼芬里爾，甘願將自己的手伸進狼口作為信物，最終被芬里爾咬斷——這個犧牲換來了眾神的暫時安全，也讓提爾成為北歐神話裡「誓言與正義」的象徵。值得一提的是，一如提烏斯神在吠陀宗教裡被因陀羅取代，提爾在北歐神話裡的重要性，同樣被更晚出現、更具魅力與複雜性的奧丁大幅蓋過——三個原本同源的天空神，在各自的文化裡，都上演了一齣「被更年輕的神祇奪走鋒芒」的相似劇碼，這究竟是巧合，還是反映了某種更深層的文化演變規律，至今仍是比較神話學裡饒富興味的討論話題。'
    ]},

  { id:'confucius', gen:'crosscultural', zh:'孔子', gr:'Confucius', roman:'—', epithet:'軸心時代的東方聖賢', crossType:'parallel',
    year:-551, yearLabel:'西元前551年',
    domain:'倫理、禮、仁', symbol:'論語竹簡', parents:[], parallel:['socrates'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 140" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="90" cy="70" r="24" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="90" y="74" font-size="9" text-anchor="middle" fill="#2A2118">己</text>
      <line x1="150" y1="30" x2="150" y2="110" stroke="#5B5850" stroke-width="1" stroke-dasharray="3 3"/>
      <circle cx="210" cy="70" r="24" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="210" y="74" font-size="9" text-anchor="middle" fill="#2A2118">人</text>
      <line x1="120" y1="70" x2="145" y2="70" stroke="#8A6D1F" stroke-width="1.5"/>
      <line x1="180" y1="70" x2="155" y2="70" stroke="#8A6D1F" stroke-width="1.5"/>
      <text x="150" y="125" font-size="8.5" text-anchor="middle" fill="#6b5c46">己所不欲，勿施於人</text>
    </svg>`,
    story:'孔子與蘇格拉底生活在幾乎同一個歷史時期（相差約八十年），卻分別在毫不知情彼此存在的情況下，各自於東西方發展出成熟的倫理思想體系。這種「不同文明幾乎同時、卻互不知情地邁向哲學成熟」的現象，被稱為「軸心時代」，孔子與蘇格拉底之間並沒有任何直接的歷史連結，只是時代上的巧合並置。',
    fullStory:[
      '孔子生活於西元前551年至479年的中國，蘇格拉底則生活於西元前470年至399年，兩人在世的時間幾乎銜接，卻遠隔萬里，彼此的世界裡完全沒有對方存在的痕跡——沒有絲毫證據顯示兩種文明在這個時期有過直接接觸或思想交流。然而，兩人卻不約而同地，將各自文明的思考重心，從對超自然神明的敬畏，轉向了對「人應該如何生活、如何與他人相處」這類倫理問題的系統性追問。',
      '德國哲學家雅斯貝爾斯在二十世紀提出「軸心時代」（Axial Age）理論，指出西元前八百年至前二百年之間，中國（孔子、老子）、印度（佛陀）、波斯（瑣羅亞斯德）、希臘（蘇格拉底一脈）等相距遙遠、彼此幾乎沒有往來的文明，竟不約而同地，各自跨出了從「神話解釋世界」邁向「理性反思人生」的關鍵一步。這個現象背後的原因，至今仍眾說紛紜——有人認為與當時各地城邦制度興起、識字階層擴大有關，也有人認為純屬歷史巧合。無論如何，這條連結提醒我們：孔子與蘇格拉底之間，是平行的呼應，而非任何形式的因果關係。'
    ]},

  { id:'buddha', gen:'crosscultural', zh:'佛陀', gr:'Siddhartha Gautama', roman:'—', epithet:'軸心時代的覺悟者', crossType:'parallel',
    year:-563, yearLabel:'約西元前563年（傳統紀年，具爭議）',
    domain:'苦、解脫、中道', symbol:'菩提樹', parents:[], parallel:['socrates','stoicism'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 170" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="150" cy="80" r="55" fill="none" stroke="#5B5850" stroke-width="2"/>
      <line x1="150" y1="25" x2="150" y2="135" stroke="#A6812E" stroke-width="1.5"/>
      <line x1="95" y1="80" x2="205" y2="80" stroke="#A6812E" stroke-width="1.5"/>
      <text x="150" y="45" font-size="9" text-anchor="middle" fill="#2A2118">苦</text>
      <text x="150" y="120" font-size="9" text-anchor="middle" fill="#2A2118">道</text>
      <text x="115" y="84" font-size="9" text-anchor="middle" fill="#2A2118">集</text>
      <text x="185" y="84" font-size="9" text-anchor="middle" fill="#2A2118">滅</text>
      <text x="150" y="160" font-size="8.5" text-anchor="middle" fill="#6b5c46">苦的成因、苦的止息、通往止息的道路</text>
    </svg>`,
    story:'佛陀（悉達多·喬達摩）與蘇格拉底同屬「軸心時代」，生活年代甚至比蘇格拉底還要早上一個世代。他提出的「中道」與斯多葛學派主張的「心靈平靜」，時常被拿來做主題上的比較，但兩者之間同樣沒有任何歷史上的直接接觸，純粹是不同文明各自發展出的相似洞見。',
    fullStory:[
      '佛陀生活於西元前六世紀至五世紀的印度北部，比蘇格拉底早了將近一個世代，同樣屬於雅斯貝爾斯所定義的「軸心時代」範圍。他捨棄王室生活出家苦修，最終在菩提樹下悟道，提出「四聖諦」與「八正道」，主張人生的痛苦源於無止盡的慾望與執著，唯有透過修行放下執念，才能達到解脫（涅槃）。',
      '佛陀提出的「中道」——不偏向縱慾享樂，也不偏向極端苦行——時常被拿來與亞里斯多德的「中庸之道」相提並論；他對「放下對外在事物的執著、才能獲得心靈平靜」的教導，也常被拿來與斯多葛學派「區分操之在我與操之不在我」的態度做主題比較。然而必須說清楚：這些都是後世學者「主題上的相似性比較」，佛教與希臘哲學之間，並沒有證據顯示在佛陀或蘇格拉底所處的年代，存在任何直接的思想交流或接觸——這條連結呈現的，是人類在不同角落各自摸索出相似人生智慧的驚奇，而不是一條真實的傳承或影響路徑。'
    ]},

  { id:'zoroaster', gen:'crosscultural', zh:'瑣羅亞斯德', gr:'Zoroaster', roman:'—', epithet:'軸心時代的波斯先知', crossType:'parallel',
    year:-628, yearLabel:'約西元前628年（估計，眾說紛紜）',
    domain:'善惡二元、光明神', symbol:'聖火', parents:[], parallel:['socrates'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 140" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <rect x="20" y="20" width="120" height="90" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="80" y="60" font-size="10" text-anchor="middle" fill="#2A2118">阿胡拉・馬茲達</text>
      <text x="80" y="78" font-size="8" text-anchor="middle" fill="#6b5c46">光明善神</text>
      <text x="150" y="70" font-size="14" text-anchor="middle" fill="#8A6D1F">VS</text>
      <rect x="160" y="20" width="120" height="90" fill="#3B2E42" stroke="#8A6D1F" stroke-width="1.5"/>
      <text x="220" y="60" font-size="10" text-anchor="middle" fill="#EFE6CE">安格拉・曼紐</text>
      <text x="220" y="78" font-size="8" text-anchor="middle" fill="#c9bd9c">黑暗惡神</text>
      <text x="150" y="130" font-size="8.5" text-anchor="middle" fill="#6b5c46">宇宙間永恆的二元對抗</text>
    </svg>`,
    story:'瑣羅亞斯德是古波斯宗教瑣羅亞斯德教的創立者，生活年代眾說紛紜，提出善神阿胡拉·馬茲達與惡神安格拉·曼紐永恆對抗的二元宇宙觀，這套「善惡二元對抗」的架構，日後透過波斯帝國與地中海世界的接觸，間接影響了猶太教、基督教乃至希臘化時代的宗教想像。',
    fullStory:[
      '瑣羅亞斯德的確切生活年代是學界長期爭論的難題，傳統波斯文獻將他定位在極為古老的年代，但現代語言學與考古證據，則傾向將他放在更接近軸心時代（約西元前一千年前後）的位置。他提出的核心教義，是宇宙間存在著光明善神阿胡拉·馬茲達，與黑暗惡神安格拉·曼紐之間永恆的鬥爭，人類的每一個道德選擇，都是這場宇宙級戰爭的一部分。',
      '與孔子、佛陀不同，瑣羅亞斯德教與希臘世界之間，其實存在著相對明確的歷史接觸管道——波斯帝國在西元前六至五世紀多次與希臘城邦爆發戰爭（波希戰爭），雙方雖是敵對關係，卻也因此有了直接的文化接觸機會；後世學者也普遍認為，瑣羅亞斯德教「善惡二元對抗」「末日審判」等概念，透過波斯與地中海世界的長期互動，對希臘化時代乃至猶太教、基督教的宗教想像，產生了一定程度的間接影響。不過，這與孔子、佛陀那種純粹「同期卻毫無接觸」的軸心時代並置不同，瑣羅亞斯德教與希臘世界之間，至少存在著間接接觸的可能路徑，這也是為什麼把他和純粹的「平行案例」放在一起時，需要特別註明這一層差異。'
    ]},

  { id:'laozi', gen:'crosscultural', zh:'老子', gr:'Laozi (Lao Tzu)', roman:'—', epithet:'「道可道，非常道」的隱士哲人', crossType:'parallel',
    year:-571, yearLabel:'約西元前571年（傳說生年，具高度爭議）',
    domain:'道、無為、自然', symbol:'青牛與道德經', parents:[], parallel:['socrates'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'老子與孔子、蘇格拉底同屬軸心時代，傳說曾任周朝掌管藏書的史官，孔子還曾向他請教「禮」的問題。他提出「道」——一種先於天地、無法用語言精確描述的萬物根本規律，以及「無為」的處世哲學，與同時期希臘思想家強調透過理性主動介入世界的取向，形成了耐人尋味的對比。',
    fullStory:[
      '老子的生平近乎籠罩在傳說之中——司馬遷在《史記》裡記載他姓李名耳，曾任周朝管理藏書的史官，孔子還曾向他請教「禮」的問題，最終老子看透周室衰微，騎著青牛西出函谷關，在關令尹喜的懇求下，留下五千言的《道德經》後便杳無音訊，去向成謎。',
      '老子最核心的思想「道」，指向一種先於天地、無法用語言精確描述、卻是萬物運行根本規律的存在——《道德經》開篇便說「道可道，非常道」，直言真正的道一旦被說出口，就已經不是那個恆常不變的道了。他同時提出「無為」的處世哲學，主張最高明的治理與生活方式，是不刻意干預、順應事物本身的自然規律，這與同時期歐洲思想家強調透過理性分析主動介入世界的取向，形成了耐人尋味的對比。',
      '值得誠實說明的是，「老子」這位人物的歷史真實性，其實是學界長期爭論的難題——不少現代學者懷疑，《道德經》很可能並非出自一人之手，而是戰國時期道家思想逐漸累積、最終集結而成的文本，「老子」這個形象，或許更接近一個被後世追認的象徵性作者，而非確鑿可考的單一歷史人物。這與我們對孔子、蘇格拉底生平相對清楚的認識相比，老子的存在本身就多了一層神秘的不確定性。'
    ]},

  { id:'wangyangming', gen:'crosscultural', zh:'王陽明', gr:'Wang Yangming', roman:'—', epithet:'「心即理」的知行合一者', crossType:'parallel',
    year:1472, yearLabel:'1472年',
    domain:'心學、知行合一、良知', symbol:'山中賞花', parents:[], parallel:['jung','buddha'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 150" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="90" cy="75" r="26" fill="none" stroke="#8a8578" stroke-width="1.5" stroke-dasharray="3 3"/>
      <text x="90" y="70" font-size="8" text-anchor="middle" fill="#6b5c46">未看見時</text>
      <text x="90" y="84" font-size="8" text-anchor="middle" fill="#6b5c46">同歸於寂</text>
      <line x1="130" y1="75" x2="170" y2="75" stroke="#A6812E" stroke-width="1.5"/>
      <polygon points="165,70 175,75 165,80" fill="#A6812E"/>
      <circle cx="220" cy="75" r="26" fill="#EFE6CE" stroke="#A6812E" stroke-width="2"/>
      <text x="220" y="70" font-size="8" text-anchor="middle" fill="#2A2118">看見時</text>
      <text x="220" y="84" font-size="8" text-anchor="middle" fill="#2A2118">顏色明白</text>
      <text x="150" y="130" font-size="8.5" text-anchor="middle" fill="#6b5c46">花不在心外</text>
    </svg>`,
    story:'王陽明是明代最重要的哲學家之一，創立「心學」，主張「心即理」——世間的道理不在心外的事物之中，而就在每個人心中。他那句著名的「你未看此花時，此花與汝心同歸於寂」，幾乎是東方哲學裡最詩意的一則「存在即是被感知」。',
    fullStory:[
      '王陽明早年篤信程朱理學，一度依照朱熹「格物致知」的教導，對著竹子整整靜坐七天七夜，試圖窮究竹子背後的「理」，最終不僅一無所獲，還因此病倒——這段經歷被後世稱為「陽明格竹」，也成為他日後徹底反思、另闢蹊徑的起點。',
      '三十七歲那年，王陽明因得罪宦官劉瑾被貶至貴州龍場，在極度艱困、幾乎與世隔絕的環境中，某夜忽然徹悟：「聖人之道，吾性自足，向之求理於事物者誤也」——他意識到，道理並不存在於外在事物之中、等待人去「格」出來，而是人心本身便自足俱備。這場後世稱為「龍場悟道」的體驗，奠定了他「心即理」學說的核心。',
      '王陽明最廣為流傳的一則對話，記錄在《傳習錄》裡：一位友人指著山中一株自開自落的花，問他「天下無心外之物，如此花樹，在深山中自開自落，於我心亦何相關？」王陽明答道：「你未看此花時，此花與汝心同歸於寂；你來看此花時，則此花顏色一時明白起來，便知此花不在你的心外。」他並非否認花在無人看見時仍然存在於物理世界，而是主張：花對於「意義」而言，唯有被心所感知、所照見，才真正「明白」起來，才在人的世界裡具備了色彩與存在感。',
      '值得一提的是，王陽明的心學並非憑空而來——宋明理學本身，深受經由絲路傳入中國、歷經數百年本土化的佛教（尤其是禪宗）思想影響，「明心見性」這類概念，與王陽明「致良知」的主張有著清晰可辨的親緣關係。也因此，儘管王陽明與遠在歐洲、提出「存在即是被感知」的貝克萊之間，在地理與時間上都相隔遙遠、毫無直接接觸，純屬思想上的巧合並置；他與佛陀之間，卻存在著一條雖然迂迴、卻真實可循的思想傳承路徑——這也是為什麼他的「軸心時代」標籤要打上引號：王陽明本人生活的年代其實遠比軸心時代晚了近兩千年，此處的「平行」，是跨越了將近兩千年時光的一次思想迴響，而不是同期的巧合。'
    ]},

  { id:'zhuangzi', gen:'crosscultural', zh:'莊子', gr:'Zhuangzi (Zhuang Zhou)', roman:'—', epithet:'「莊周夢蝶」的逍遙哲人', crossType:'parallel',
    year:-369, yearLabel:'約西元前369年（生卒年具爭議）',
    domain:'齊物、逍遙、相對主義', symbol:'蝴蝶與大鵬鳥', parents:[], parallel:['socrates','skepticism'],
    astro:'目前沒有廣為人知的正式天體命名。',
    diagram:`<svg viewBox="0 0 300 150" xmlns="http://www.w3.org/2000/svg" font-family="'Noto Sans TC',sans-serif">
      <circle cx="90" cy="75" r="30" fill="#EFE6CE" stroke="#A6812E" stroke-width="1.5"/>
      <text x="90" y="72" font-size="10" text-anchor="middle" fill="#2A2118">莊周</text>
      <text x="90" y="86" font-size="8" text-anchor="middle" fill="#6b5c46">醒著</text>
      <text x="150" y="70" font-size="16" text-anchor="middle" fill="#8A6D1F">?</text>
      <line x1="130" y1="75" x2="170" y2="75" stroke="#5B5850" stroke-width="1" stroke-dasharray="3 3"/>
      <circle cx="210" cy="75" r="30" fill="#D8C9A0" stroke="#8A6D1F" stroke-width="1.5"/>
      <text x="210" y="72" font-size="10" text-anchor="middle" fill="#2A2118">蝴蝶</text>
      <text x="210" y="86" font-size="8" text-anchor="middle" fill="#6b5c46">夢中</text>
      <text x="150" y="130" font-size="8.5" text-anchor="middle" fill="#6b5c46">誰在夢誰？</text>
    </svg>`,
    story:'莊子是道家最重要的思想家之一，生卒年與亞里斯多德幾乎完全重疊，卻對彼此的存在一無所知。他最著名的「莊周夢蝶」寓言，探討真實與虛幻的界線該如何劃定，兩千多年後，這個提問竟與貝克萊的「存在即是被感知」遙相呼應。',
    fullStory:[
      '莊子，本名莊周，生活於戰國時期的宋國，確切生卒年至今仍有爭議，但主流推估約落在西元前369年至前286年之間——這個時間範圍，幾乎與古希臘的亞里斯多德（西元前384年至前322年）完全重疊。兩人統治著相隔萬里的兩個世界，彼此的思想體系裡完全沒有對方存在過的痕跡，卻不約而同地，都在同一個世紀裡，將人類的理性思辨推向了各自文明的高峰。',
      '莊子最廣為人知的寓言，記錄在《齊物論》裡：他夢見自己化為一隻翩翩飛舞的蝴蝶，渾然忘卻自己原本是莊周；夢醒之後，他卻開始困惑——究竟是莊周夢見自己變成了蝴蝶，還是此刻的蝴蝶正夢見自己變成了莊周？這則寓言表面上輕巧如詩，實際上直指一個深刻的哲學提問：我們如何確知自己此刻所經歷的，就是「真實」，而不是另一場尚未醒來的夢境？兩千多年後，貝克萊提出「存在即是被感知」，某種意義上，正是從另一個角度，重新叩問了莊子當年提出的同一個問題。',
      '莊子的核心思想「齊物」，主張世間萬物看似差異懸殊，實則從更高的視角看來，並無絕對的高低貴賤之分——這套相對主義式的洞察，與古希臘懷疑學派「任何命題都能找到力量相當的反面論證」的立場，隱隱呼應。他也以「大鵬鳥」的寓言聞名：一隻能夠一飛萬里、扶搖直上九萬里高空的巨鳥，卻仍被局限在自己所能理解的視野範圍之內——莊子藉此提醒讀者，即便是看似逍遙自在的至高存在，也未必真正擺脫了認知上的局限，唯有放下對「大小」「是非」的執著比較，才能真正抵達「逍遙遊」的境界。'
    ]},

  { id:'wollstonecraft', gen:'modernphil', zh:'瑪麗・沃斯通克拉夫特', gr:'Mary Wollstonecraft', roman:'—', epithet:'女性主義哲學的奠基者',
    year:1759, yearLabel:'1759年',
    domain:'女性教育、理性、平等權利', symbol:'鵝毛筆與《女權辯護》', parents:[], links:['beauvoir'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'沃斯通克拉夫特在1792年出版《為女權辯護》，主張女性並非天生理性不足，而是被剝奪了受教育的機會，比波伏娃「並非生而為女人，而是變成女人」的洞察早了整整一百五十多年，被公認是西方女性主義哲學最早的奠基之作。',
    fullStory:[
      '沃斯通克拉夫特生活於十八世紀的英國，親身經歷了當時女性普遍被排除在正規教育之外的處境——她自學成才，靠寫作與擔任家庭教師維生，這段經驗讓她深刻體會到，社會加諸於女性身上的「柔弱」「不擅思考」等刻板印象，並非天生如此，而是長期被剝奪學習機會所造成的結果。',
      '一七九二年，她出版《為女權辯護》一書，正面挑戰當時普遍流行、主張女性教育應著重培養「取悅男性」之特質的教育理論。她主張，若女性能獲得與男性同等的教育機會，理性能力並不會亞於男性；社會之所以看似「證實」了女性智力不足，恰恰是因為從未真正給予女性發展理性的空間。這套論證邏輯，與一百五十多年後波伏娃在《第二性》裡提出的「並非生而為女人，而是變成女人」，形成了跨越近兩個世紀的深刻呼應——兩人相隔遙遠的時代，卻共同指向同一個核心洞察：性別特質很大程度上是社會建構的產物，而非與生俱來的天性。',
      '沃斯通克拉夫特的個人生活同樣充滿了對傳統規範的挑戰與掙扎——她曾未婚生女、也曾試圖自殺，最終在生下女兒瑪麗（也就是日後寫出《科學怪人》的瑪麗・雪萊）不久後，因產褥熱去世，年僅三十八歲。她過世後，丈夫威廉・戈德溫出於哀慟出版了一部誠實揭露她感情生活波折的傳記，卻意外導致她的聲譽在十九世紀一度嚴重受損、乏人問津，直到二十世紀女性主義運動重新興起，她作為女性主義哲學奠基者的地位，才終於獲得應有的肯定。'
    ]},

  { id:'anscombe', gen:'modernphil', zh:'伊莉莎白・安斯庫姆', gr:'G. E. M. Anscombe', roman:'—', epithet:'維根斯坦的譯者與哲學上的繼承人',
    year:1919, yearLabel:'1919年',
    domain:'行動哲學、倫理學、心智哲學', symbol:'筆記本與菸斗', parents:[], links:['wittgenstein'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'安斯庫姆是維根斯坦晚年最重要的學生之一，親自將他艱澀的德文手稿翻譯成英文，讓《哲學研究》得以問世流傳。她自己提出的「現代道德哲學」批判，更直接挑戰了西方倫理學數百年來的思考框架，被公認是二十世紀最具原創性的哲學家之一。',
    fullStory:[
      '安斯庫姆是劍橋大學少數幾位女性哲學教授之一，也是維根斯坦晚年最信任的學生與朋友——維根斯坦逝世後，將自己大量未曾出版、以德文寫就的手稿遺產指定交由安斯庫姆等三位學生共同管理。她投入大量心力，親自將這些艱澀難解的文本翻譯成英文，其中最重要的《哲學研究》，正是經由她的翻譯，才得以在英語世界廣泛流傳、深刻影響了此後數十年的分析哲學發展。',
      '安斯庫姆自己在哲學上的原創貢獻同樣舉足輕重——她在一九五八年發表的論文〈現代道德哲學〉，尖銳批評自啟蒙時代以來，西方倫理學始終建立在「義務」「應該」這類預設有神聖立法者存在的概念之上，然而現代社會早已不再普遍相信這樣的立法者，這套倫理學語言因此變得空洞而缺乏根基。她主張，倫理學應該重新回到亞里斯多德式的「德性」與「人類繁盛」概念，這篇論文後來被公認是促成二十世紀後半「德性倫理學」復興的關鍵起點之一。',
      '安斯庫姆同時也以敢言著稱——她曾公開抗議牛津大學頒發榮譽學位給下令投擲原子彈的美國總統杜魯門，稱其行為等同於謀殺平民；她的著作《意圖》，深入探討人類行動背後「意圖」的哲學結構，至今仍是行動哲學領域最重要的經典文獻之一，展現出她不僅是維根斯坦思想的忠實傳遞者，更是一位開創出自己獨立思想版圖的哲學家。'
    ]},

  { id:'nussbaum', gen:'modernphil', zh:'瑪莎・納思邦', gr:'Martha Nussbaum', roman:'—', epithet:'提出「能力取徑」的當代哲學家',
    year:1947, yearLabel:'1947年',
    domain:'能力取徑、情感的哲學、正義', symbol:'天秤與人類繁盛清單', parents:[], links:['aristotle','rawls'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'納思邦是當代最具影響力的哲學家之一，結合亞里斯多德的德性倫理學與羅爾斯的正義理論，提出「能力取徑」——主張評斷一個社會是否正義，不該只看資源分配是否平等，而該看每個人是否真正擁有「過上美好人生所需的核心能力」。',
    fullStory:[
      '納思邦的哲學生涯橫跨古典學與當代政治哲學兩大領域——她早年深入鑽研亞里斯多德的倫理學與情感理論，後來將這套關注「人類如何真正繁盛」的古典視角，帶入了對當代社會正義議題的思考之中，發展出被稱為「能力取徑」（capabilities approach）的理論架構。',
      '納思邦與羅爾斯的正義理論展開深刻對話——羅爾斯的「無知之幕」思想實驗，主要關注社會資源與基本權利該如何公平分配；納思邦則進一步追問：光是分配到資源與權利，是否就足以讓一個人過上真正美好的人生？她列出一份包含生命、身體健康、想像與思考自由、情感連結等在內的「核心能力清單」，主張一個正義的社會，必須確保每個成員都真正具備實現這些能力的實質條件，而不只是形式上擁有平等的權利。',
      '這套理論後來被聯合國開發計畫署等國際組織實際採納，用以發展「人類發展指數」等衡量社會福祉的指標，取代僅僅關注經濟成長數字的傳統做法，是少數真正從學院哲學走入國際政策制定現場、產生實質影響力的當代哲學理論之一。納思邦至今仍活躍於學界，持續在情感哲學、動物倫理、身心障礙正義等議題上發表深具影響力的著作。'
    ]},

  { id:'adam', gen:'crosscultural', zh:'亞當', gr:'Adam', roman:'—', epithet:'希伯來聖經裡最初的人類', crossType:'parallel',
    domain:'創世、伊甸園、塵土造人', symbol:'伊甸園與生命樹', parents:[], parallel:['iapetus'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'亞當是希伯來聖經《創世記》裡上帝依自己形象、以塵土捏塑而成的第一位人類。「以泥土造人」這個意象，並非希伯來傳統獨有——希臘神話裡也流傳著普羅米修斯以泥土塑造人類的說法，兩則相隔遙遠的創世敘事，不約而同地，都選擇了「泥土」作為人類起源最原初的物質。',
    fullStory:[
      '依照《創世記》的記載，上帝在創世的第六日，取地上的塵土，依照自己的形象捏塑出第一位人類亞當，再向他的鼻孔吹入生命的氣息，使他成為有靈的活人。亞當隨後被安置在伊甸園中，被賦予為園中萬物命名的權柄，過著與造物主親密同行、不知匱乏的生活——直到他的伴侶夏娃出現，兩人共同構成了希伯來聖經裡對人類起源最核心的敘事。',
      '「以泥土造人」這個意象，其實在多個古代文明的創世神話裡反覆出現，並非希伯來傳統獨有——美索不達米亞的《吉爾伽美什史詩》裡，恩基杜同樣是由女神以泥土捏塑而成；而在希臘神話裡，也流傳著泰坦神普羅米修斯以泥土仿照諸神形象、親手塑造出人類的說法，古羅馬詩人奧維德在《變形記》開篇，便記錄了這則版本的人類起源故事。',
      '值得說明的是，亞當的敘事與普羅米修斯造人的說法，兩者之間並沒有任何證據顯示存在直接的文化接觸或相互影響——它們是分別在近東與地中海兩個獨立文明裡，各自發展出的創世想像。然而「泥土」這個材質選擇的高度重合，長久以來吸引著比較神話學者的興趣：或許正是因為人類作為土地上最普遍可得的物質，很自然地成為不同文明想像「人從何而來」時，共同浮現的第一個答案。',
      '鮮少被提及的是，伊甸園裡其實不只有一棵禁樹——除了引發爭議的「分別善惡樹」，園子正中央還有另一棵「生命樹」，據信只要食用其果實便能獲得永生。亞當夏娃被逐出伊甸園後，上帝特意在生命樹周圍安排基路伯天使與四面轉動的火焰劍看守，理由正是「恐怕他伸手又摘生命樹的果子吃，就永遠活著」——換句話說，人類真正被永久隔絕的，或許不是知識本身，而是「同時擁有知識與永生」這個組合。另外，猶太教一支較晚出現、並未收錄進正典的民間傳說裡，亞當其實還有一位更早的妻子——莉莉絲，她的故事，以及她為何從敘事裡悄悄消失，另有獨立收錄。'
    ]},

  { id:'eve', gen:'crosscultural', zh:'夏娃', gr:'Eve', roman:'—', epithet:'因好奇心為人間帶來苦難的第一位女性', crossType:'parallel',
    domain:'創世、禁果、原罪的起源', symbol:'蘋果與蛇', parents:[], parallel:['pandora'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'夏娃是希伯來聖經裡的第一位女性，因禁不住蛇的引誘，摘下禁果，被逐出伊甸園，這則敘事從此成為西方文化裡「原罪」概念的起源。她的故事與希臘神話裡潘朵拉打開災禍之罐的傳說，形成了一次耐人尋味的跨文化呼應——兩則相隔遙遠的神話，不約而同地，都將人類苦難的起源，追溯回一位女性因好奇心而做出的選擇。',
    fullStory:[
      '依照《創世記》的記載，夏娃是上帝取亞當的一根肋骨所造，作為他的伴侶。兩人原本一同居住在伊甸園中，被允許自由享用園中一切果實，唯獨不可食用「分別善惡樹」的果子。然而蛇引誘夏娃，告訴她吃下果子並不會招致死亡，反而能使人的眼睛明亮、像上帝一樣能分辨善惡——夏娃見那果子悅人眼目、又能使人有智慧，便摘下食用，也給了亞當一同吃下。',
      '兩人吃下禁果後，眼睛果然明亮起來，卻不是獲得預期中的智慧，而是第一次意識到自己赤身露體、心生羞愧。上帝發現此事後，將兩人逐出伊甸園，並宣告女人此後必受懷胎生產之苦，男人則須終身勞苦耕種才能餬口——這則敘事，成為後世基督教神學裡「原罪」概念最核心的聖經依據，主張人類自此便帶著這場悖逆所遺留下的罪性與苦難，代代相傳。',
      '一個較少被提及的細節是：《創世記》原文只將那條蛇描述為「田野一切活物中最狡猾的」，經文本身，其實從未明說這條蛇就是撒旦——「蛇即撒旦」這個後世普遍接受的等同關係，主要是新約《啟示錄》裡「那古蛇，就是魔鬼，撒但」一語，回頭附加在這則古老敘事之上的神學詮釋，而非《創世記》原初文本裡直接寫明的設定。蛇的真實動機究竟是什麼、牠與人類獲得智慧之間，究竟是純粹的誘惑陷阱，還是某種曖昧難辨的贈予，兩千多年來，始終是猶太教與基督教神學辯論不休、始終沒有定論的核心謎題之一。',
      '夏娃因好奇心與渴望智慧而摘下禁果、為人間帶來苦難的敘事結構，與希臘神話裡潘朵拉揭開陶罐、放出災禍的故事，形成了一次相隔兩個獨立文明、卻驚人相似的呼應——兩位「第一位女性」，都因為一次違背禁令的選擇，永久改變了人類此後的命運。學者普遍認為，這兩則敘事之間並無直接的歷史傳承關係，純屬不同文明各自發展出的平行敘事母題；但也正因如此，這份跨越地理與時間的相似性，才更加耐人尋味——彷彿不同文明在各自摸索「苦難從何而來」這個根本問題時，不約而同地，都選擇了同一種敘事邏輯。'
    ]},

  { id:'noah', gen:'crosscultural', zh:'諾亞', gr:'Noah', roman:'—', epithet:'建造方舟躲過大洪水的義人', crossType:'parallel',
    domain:'大洪水、方舟、與神立約', symbol:'方舟與鴿子', parents:[], parallel:['deucalion'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'諾亞是希伯來聖經《創世記》裡，因世人敗壞而遭上帝降下大洪水滅世時，唯一奉命建造方舟、帶著家人與各種動物倖存下來的義人。這則洪水滅世又重新繁衍人類的敘事結構，與希臘神話裡宙斯降下大洪水、丟卡利翁夫婦倖存重建人類的傳說，形成了世界神話裡最著名的一組跨文化對照。',
    fullStory:[
      '依照《創世記》記載，上帝眼見世人罪惡滿盈、心中充滿暴力，決意降下毀滅性的大洪水，洗淨這片墮落的大地——唯獨諾亞因為在世人中行事正直，蒙上帝揀選，奉命建造一艘巨大的方舟，將自己一家八口，以及潔淨與不潔淨的各類動物各取數對，一同帶入方舟避難。洪水持續四十晝夜，淹沒了地上一切高山，直到水勢消退，方舟停靠在亞拉臘山上，諾亞放出鴿子確認陸地重現，才率領家人與動物重新踏上乾地，上帝並以彩虹為記號，與諾亞立下永不再以洪水滅世的約定。',
      '這則洪水敘事，並非希伯來傳統獨有——更古老的美索不達米亞《吉爾伽美什史詩》裡，同樣記載著神明降下大洪水、烏特納皮什提姆奉命造船避難的情節，兩者細節之相似（包括放出飛鳥探查陸地是否重現），長期是學界討論近東洪水神話共同源頭的重要案例。而在地中海另一端的希臘神話裡，也流傳著幾乎同樣結構的故事：宙斯因人類（青銅時代）道德淪喪，降下大洪水滅世，唯獨普羅米修斯之子丟卡利翁與妻子皮拉，因預先受到警告、建造了一只巨大的木箱，才得以倖存，成為大洪水後重新繁衍人類的始祖。',
      '學者普遍認為，諾亞方舟與丟卡利翁洪水這兩則敘事，並沒有直接的文化傳承關係，而是分別在近東與愛琴海文明裡，各自獨立發展出的洪水滅世母題——但兩者選擇如此相似的敘事框架（神降洪水懲罰墮落人類、唯一義人受警告造船倖存、以鳥類探測陸地重現、劫後餘生者成為人類新始祖），仍舊是比較神話學裡，跨文明敘事母題高度重合最經典的範例之一，也讓後世學者不斷追問：這究竟是人類集體潛意識裡共通的原型想像，還是不同古代文明之間，存在著我們尚未完全釐清的間接文化交流？'
    ]},

  { id:'cain', gen:'crosscultural', zh:'該隱', gr:'Cain', roman:'—', epithet:'犯下人類史上第一樁謀殺的兄長',
    domain:'農耕、嫉妒、流亡的印記', symbol:'沾血的土地', parents:['adam','eve'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'該隱是亞當與夏娃的長子，一位耕種土地的農夫，因嫉妒弟弟亞伯的獻祭蒙上帝悅納、自己的獻祭卻遭忽視，憤而在田間殺害了亞伯——這是希伯來聖經裡記載的人類史上第一樁謀殺，該隱也因此終身背負著上帝所加的印記，注定四處流亡。',
    fullStory:[
      '該隱是亞當與夏娃所生的長子，以耕種土地為業；他的弟弟亞伯，則是一位牧羊人。某日，兩兄弟分別向上帝獻上自己勞動的果實——該隱獻上田裡的出產，亞伯獻上羊群中頭生且肥美的羊。聖經記載，上帝悅納了亞伯的獻祭，卻沒有看中該隱的獻祭，這個落差讓該隱心生嫉妒與憤怒，臉色因此變得低沉。',
      '上帝察覺該隱的情緒，警告他罪就伏在門前，若不能制伏心中的怒火，終將被罪所控制。然而該隱終究沒能按捺住嫉妒，趁著與亞伯一同在田間之時，動手殺害了自己的親弟弟——這是希伯來聖經裡記載的人類史上第一樁謀殺案，也是第一次有人類的鮮血灑落在土地上。上帝質問該隱：「你兄弟亞伯在哪裡？」該隱以那句後世流傳千古的反問回答：「我豈是看守我兄弟的人？」',
      '上帝因此對該隱降下懲罰：土地將不再為他出產，他必須終身四處流浪，不得安居。該隱懼怕自己四處流浪會招致殺身之禍，上帝便在他身上留下一個印記，警告任何遇見他的人都不得殺他，違者將遭受七倍的報應——這個「該隱的印記」，此後成為西方文化裡談論「背負罪責、遭社會放逐」時，最常被引用的一則典故。值得說明的是，這則兄弟相殘的故事，目前並沒有發現與希臘神話存在直接對應的敘事母題，因此在此獨立收錄，不強行連結任何跨文化對照。'
    ]},

  { id:'abel', gen:'crosscultural', zh:'亞伯', gr:'Abel', roman:'—', epithet:'人類史上第一位謀殺受害者',
    domain:'畜牧、蒙悅納的獻祭、無辜的犧牲', symbol:'頭生的羊羔', parents:['adam','eve'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'亞伯是亞當與夏娃的次子，一位牧羊人，因獻上羊群中頭生且肥美的羊，蒙上帝悅納，卻也因此引來兄長該隱的嫉妒，最終被該隱殺害於田間，成為希伯來聖經裡人類史上第一位謀殺案的受害者。',
    fullStory:[
      '亞伯是亞當與夏娃所生的次子，以牧羊為業，與務農的兄長該隱走上了截然不同的營生之路。聖經對亞伯本人著墨甚少，他幾乎沒有留下任何自己的言語或事蹟，唯一被記載的行動，是他將羊群中頭生且最肥美的羊獻給上帝——這份獻祭蒙上帝悅納，卻也間接為他招來了殺身之禍。',
      '亞伯在毫無防備的情況下，被自己的親兄長該隱殺害於田間，成為希伯來聖經裡明確記載的人類史上第一位謀殺案受害者。上帝在事後對該隱說：「你兄弟的血，有聲音從地裡向我哀告。」這句話後來也成為西方文學與神學裡，談論「無辜者的血在呼求公義」時，經常被引用的意象。',
      '亞伯雖然在世的篇幅極短，卻在後世的宗教與文學傳統裡，被塑造成「無辜受害者」與「蒙神悅納的義人」的原型象徵——新約《希伯來書》甚至將他列為信心偉人之首，稱他「雖然死了，卻因這信仍舊說話」。與該隱一樣，亞伯的故事目前也沒有發現與希臘神話存在直接對應的敘事母題，因此同樣獨立收錄，不強行連結任何跨文化對照。'
    ]},

  { id:'lilith', gen:'crosscultural', zh:'莉莉絲', gr:'Lilith', roman:'—', epithet:'拒絕臣服、從敘事裡消失的亞當第一任妻子',
    domain:'夜之魔女、反抗、被抹除的敘事', symbol:'貓頭鷹與荒野之夜', parents:[], links:['adam'],
    astro:'目前沒有廣為人知的正式天體命名。',
    story:'依照猶太教一支較晚出現的民間傳說，莉莉絲才是亞當真正的第一任妻子——與亞當同樣取自塵土所造、地位平等，卻因拒絕臣服而憤然離開伊甸園，此後在猶太民間信仰裡，逐漸演變成盤據荒野、專門加害嬰兒的夜魔形象。',
    fullStory:[
      '莉莉絲並未出現在《創世記》正典文本裡，她的故事最早見於西元十世紀左右成書的《便西拉字母書》——一部帶有諷刺與民間故事色彩的猶太文獻，並不具備正典地位。依照這則傳說，上帝其實造過兩個版本的「第一位女性」：莉莉絲是第一版，與亞當同樣取自塵土捏塑而成，地位理應與亞當完全平等；夏娃則是後來才取自亞當的肋骨所造的第二版。',
      '莉莉絲與亞當的婚姻很快便產生了裂痕——傳說記載，兩人時常爭執不下，莉莉絲堅持不願採取臣服於下的姿態，認為自己與亞當出身相同、地位平等，不該有誰臣服於誰的問題。她因此憤而說出上帝的聖名（一項據信具有強大魔法力量的禁忌行為），飛離伊甸園，從此不知去向。',
      '上帝派出三位天使追捕莉莉絲，威脅她若不歸來，她所生的惡魔子嗣每日都將有數百個夭折——莉莉絲拒絕返回，此後在猶太民間信仰裡，逐漸演變成一個盤據荒野、專門在夜間加害新生兒與孕婦的夜魔形象，中世紀的猶太家庭甚至會在嬰兒房裡懸掛護身符，特別用來抵禦莉莉絲的侵擾。近代女性主義思潮重新詮釋這則傳說時，莉莉絲的形象出現了顯著翻轉——不再被視為邪惡的夜魔，而是被重新解讀為史上第一位拒絕臣服、追求平等的女性象徵。這則「被主流敘事抹除、又在後世被重新奪回話語權」的故事本身，或許正是莉莉絲的傳說，至今依然令人著迷的原因。'
    ]},

  { id:'ophiuchus', gen:'ophiuchus', zh:'蛇夫座', gr:'Ophiuchus', roman:'—', epithet:'黃道上被正式除名的第十三個星座',
    domain:'醫術、蛇與重生、被遺忘的存在', symbol:'纏繞雙蛇的權杖', parents:['apollo'], links:['chiron'],
    astro:'太陽實際運行經過蛇夫座的時間，比經過天蠍座還要長——現代天文學家依照精確的星座邊界重新計算後發現，黃道其實穿越了十三個星座，而不是傳統占星術裡的十二個。',
    story:'蛇夫座對應的神話人物，通常被認為是阿斯克勒庇俄斯——醫神阿波羅之子，醫術高明到甚至能讓死者復生，因此觸怒冥王黑帝斯，被宙斯用雷霆擊斃。太陽實際運行的軌跡，確實會穿過這片星空，卻始終被排除在傳統黃道十二宮之外。',
    fullStory:[
      '蛇夫座所對應的神話人物，多數傳統將其認定為阿斯克勒庇俄斯——太陽神阿波羅與凡人公主科洛尼斯之子，自幼跟隨半人馬凱隆習醫，醫術之精湛，甚至能讓死者起死回生。這項能力打破了生死之間本該恪守的界線，讓冥王黑帝斯深感不滿，向兄長宙斯告狀，宙斯權衡之下，最終以雷霆親手擊殺了阿斯克勒庇俄斯——卻也感念他生前濟世救人的功績，將他的形象升上夜空，成為蛇夫座。',
      '依照國際天文聯合會於一九三〇年正式劃定的精確星座邊界重新計算，太陽在一年之中運行的軌跡，確實會穿越蛇夫座的範圍，時間長度甚至超過穿越天蠍座的時間——這意味著，如果完全依照現代天文學的實際觀測結果，黃道帶上其實存在著十三個星座，而非傳統占星術沿用至今的十二個。然而由於蛇夫座從未被納入巴比倫時代就已定型的黃道十二宮傳統，這第十三個星座，至今仍被排除在絕大多數占星文化之外——阿斯克勒庇俄斯救人性命卻觸怒神祇的故事，某種程度上，也像是一則關於「跨越了不該跨越的界線，就注定要被排除在外」的隱喻。'
    ]},
];
